# ─── Cache utilities ──────────────────────────────────────────────────────────

def _carregar_cache() -> Dict:
    """Load the local cache from disk."""
    if ARQUIVO_CACHE.exists():
        try:
            with open(ARQUIVO_CACHE, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {}
    return {}


def _salvar_cache(cache: Dict) -> None:
    """Persist the local cache to disk."""
    try:
        with open(ARQUIVO_CACHE, "w", encoding="utf-8") as f:
            json.dump(cache, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.warning("Could not save cache: %s", e)


def _cache_get(chave: str) -> Optional[Any]:
    """Return cached value if still within TTL, otherwise None."""
    cache = _carregar_cache()
    entrada = cache.get(chave)
    if entrada:
        ts = entrada.get("timestamp", 0)
        if (time.time() - ts) < CACHE_TTL:
            logger.debug("Cache HIT for key: %s", chave)
            return entrada.get("dados")
    return None


def _cache_set(chave: str, dados: Any) -> None:
    """Store data in cache with current timestamp."""
    cache = _carregar_cache()
    cache[chave] = {"timestamp": time.time(), "dados": dados}
    _salvar_cache(cache)

# ─── History utilities ────────────────────────────────────────────────────────

def registrar_historico(modo: str, parametros: Dict) -> None:
    """Add an entry to the execution history."""
    historico: List = []
    if ARQUIVO_HISTORICO.exists():
        try:
            with open(ARQUIVO_HISTORICO, "r", encoding="utf-8") as f:
                historico = json.load(f)
        except Exception:
            historico = []
    entrada = {
        "id": len(historico) + 1,
        "data": datetime.datetime.now().isoformat(),
        "modo": modo,
        "parametros": parametros,
    }
    historico.append(entrada)
    try:
        with open(ARQUIVO_HISTORICO, "w", encoding="utf-8") as f:
            json.dump(historico, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.warning("Could not write history: %s", e)


def listar_historico() -> List[Dict]:
    """Return the list of history entries."""
    if ARQUIVO_HISTORICO.exists():
        try:
            with open(ARQUIVO_HISTORICO, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    return []

