def _baixar_json_grupos(url: str, arquivo_local: str = "tg.json") -> bool:
    """Download the ETDA group catalogue and save it locally."""
    resp = _req_get(url, timeout=30)
    if resp:
        try:
            with open(arquivo_local, "w", encoding="utf-8") as f:
                json.dump(resp.json(), f, ensure_ascii=False, indent=4)
            logger.info("Group catalogue updated: %s", arquivo_local)
            return True
        except Exception as e:
            logger.error("Error saving catalogue: %s", e)
    return False


def _carregar_json_grupos(arquivo_local: str = "tg.json") -> Optional[Dict]:
    """Load the local group catalogue."""
    try:
        with open(arquivo_local, "r", encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        logger.error("File %s not found.", arquivo_local)
    except json.JSONDecodeError:
        logger.error("File %s is corrupted.", arquivo_local)
    return None


def _aplicar_wildcard(padrao: str, texto: str) -> bool:
    """Wildcard search (* supported) against text."""
    regex = padrao.replace("*", ".*").lower()
    return bool(re.search(regex, texto.lower()))


def _buscar_grupos(dados: List[Dict], filtros: Dict[str, str],
                   operador: str = "AND") -> List[Dict]:
    """
    Search groups by multiple criteria (sector, country, tool, name, etc.).
    operador: 'AND' (all filters must match) or 'OR' (any filter matches).
    """
    resultados = []
    for item in dados:
        if not isinstance(item, dict):
            continue
        correspondencias = []
        for chave, valor in filtros.items():
            campo = item.get(chave, "")
            correspondencias.append(_aplicar_wildcard(valor, str(campo)))
        if operador == "AND":
            if all(correspondencias):
                resultados.append(item)
        else:  # OR
            if any(correspondencias):
                resultados.append(item)
    return resultados


def _extrair_ids_grupo(resultados: List[Dict]) -> List[str]:
    """Extract MITRE IDs (Gxxxx) from the 'mitre-attack' field."""
    ids = []
    for r in resultados:
        mitre = r.get("mitre-attack", [])
        if isinstance(mitre, list):
            for entrada in mitre:
                m = re.search(r"/groups/(G\d+)", str(entrada))
                if m:
                    ids.append(m.group(1))
    return list(dict.fromkeys(ids))  # deduplicar, preservar ordem


def _extrair_nomes_atores(resultados: List[Dict]) -> List[str]:
    """Extract actor names from the 'actor' field."""
    return [r.get("actor", "") for r in resultados if r.get("actor")]


def _extrair_aliases(resultado: Dict) -> List[str]:
    """Extract aliases/alternative names from the 'names' field."""
    aliases = []
    nomes = resultado.get("names", [])
    if isinstance(nomes, list):
        for n in nomes:
            if isinstance(n, dict):
                aliases.append(f"{n.get('name', '')} [{n.get('name-giver', '?')}]")
    return aliases


def _primeira_str(values: Any, fallback: str = "") -> str:
    """
    Return the first non-empty string from *values*.

    Accepts a single string, a flat list of strings, a list-of-lists, or None.
    Recursively flattens one level of nesting so callers never need to worry
    about whether the value came in as ``"Brazil"``, ``["Brazil"]``, or
    ``[["Brazil"]]``.
    """
    if not values and values != 0:
        return fallback
    if isinstance(values, str):
        return values or fallback
    if isinstance(values, list):
        for item in values:
            result = _primeira_str(item, "")
            if result:
                return result
        return fallback
    return str(values) or fallback


def _como_lista(value: Any) -> List[str]:
    """
    Coerce *value* to a flat list of non-empty strings.

    Handles None, strings, flat lists, and lists-of-lists produced by
    inconsistent LLM responses.  Each element of a nested list is
    recursively unwrapped so the result is always List[str].
    """
    if value is None:
        return []
    if isinstance(value, str):
        return [value] if value.strip() else []
    if isinstance(value, list):
        result: List[str] = []
        for item in value:
            if isinstance(item, list):
                result.extend(_como_lista(item))
            elif item is not None:
                s = str(item).strip()
                if s:
                    result.append(s)
        return result
    return [str(value)] if str(value).strip() else []


# Sentinel tokens that LLMs often emit to signal "no data available".
# All comparisons use .strip().lower() so casing/whitespace variants are caught.
_EMPTY_SENTINELS: frozenset = frozenset({
    "n/a", "na", "none", "null", "unknown",
    "no description available",
    "not available", "not applicable",
    "no data", "no information", "no info",
    "-", "--", "---", "n.a.", "n.a",
})


def _is_empty_value(value: Any) -> bool:
    """Return True if *value* should be treated as absent / empty.

    Catches None, empty string, whitespace-only string, and any of the
    sentinel tokens that LLMs commonly emit to indicate missing data
    (e.g. "N/A", "None", "No description available", "Unknown", …).
    """
    if value is None:
        return True
    if not isinstance(value, str):
        return False
    stripped = value.strip().lower()
    return stripped == "" or stripped in _EMPTY_SENTINELS


def _sanitize_str(value: Any) -> str:
    """Return *value* as a clean string, or empty string if it is a sentinel.

    Suitable for scalar LLM fields (first_seen, origin_location, …) that may
    contain "N/A", "None", empty string, etc.
    """
    if _is_empty_value(value):
        return ""
    return str(value).strip()


def _sanitize_list(value: Any) -> List[str]:
    """Return *value* as a flat list of non-sentinel strings.

    Strips sentinel tokens element-by-element so lists like
    ["Healthcare", "N/A", ""] become ["Healthcare"].
    """
    raw = _como_lista(value)
    return [item for item in raw if not _is_empty_value(item)]




def _normalizar_resultado_grupo(r: Dict) -> Dict:
    """
    Normalise a single threat-group result dict into a unified internal schema
    that the HTML renderer understands, regardless of whether the data originates
    from the ETDA catalogue (normal path) or from the LLM fallback.

    LLM models routinely deviate from the system-prompt schema — they use
    alternative key names, nest values differently, or place fields at the
    top level instead of inside the expected sub-objects.  This function
    performs exhaustive alias resolution so all known variant key names are
    mapped to the canonical internal field, regardless of model or version.

    All list fields are guaranteed to be flat List[str] after normalisation.
    All string fields are guaranteed to be non-None strings (empty string when
    no value is available).
    Missing fields are set to safe empty defaults so downstream renderers can
    use .get() without risk of KeyError / AttributeError.

    Additional LLM-only fields that have no ETDA equivalent are collected
    under ``_llm_extra`` so the renderer can present them without polluting
    the shared schema namespace.

    Alias maps
    ----------
    The following alternative key names are recognised for each canonical field.
    All aliases are case-sensitive (the LLM system-prompt uses these names).

    general_information sub-object
        actor name      : threat_actor_name | adversary_name | name
        description     : overview | description | summary
        motivation      : motivation
        active_since    : active_since | first_seen | first_activity | status_since
        actor_type      : actor_type | type | category
        crowdstrike_id  : crowdstrike_identifier | crowdstrike_id | cs_id

    country_of_origin sub-object
        primary_location: primary_location | location | country | origin
        region          : region | area | sub_region

    modus_operandi sub-object
        description     : description | summary | overview
        key_tactics     : key_tactics | key_activities | tactics | activities

    tactics block (top-level alternative to mitre_attack_tactics_and_techniques)
        tactics_and_techniques | mitre_attack | attack_techniques

    Top-level field aliases (direct LLM root keys)
        tools           : tools | tools_and_malware | tools_used | malware | software
        observed-sectors: observed-sectors | targeted_sectors | targeted_industries
                          | observed_sectors
        observed-countries: observed-countries | targeted_geographies | target_geography
                            | targeted_countries | observed_countries
        names/aliases   : names | aliases
    """
    # Work on a shallow copy to avoid mutating the caller's dict
    n: Dict = dict(r)

    is_llm = bool(n.get("_llm_source"))

    if is_llm:
        gen = n.get("general_information") or {}
        if not isinstance(gen, dict):
            gen = {}

        ta = n.get("threat_actor") or {}
        if not isinstance(ta, dict):
            ta = {}

        tgt = n.get("targeting") or {}
        if not isinstance(tgt, dict):
            tgt = {}

        # ── actor name ────────────────────────────────────────────────────
        if not n.get("actor"):
            n["actor"] = _primeira_str([
                ta.get("name"),
                ta.get("threat_actor_name"),
                gen.get("threat_actor_name"),
                gen.get("adversary_name"),
                gen.get("name"),
                n.get("threat_actor_name"),
                n.get("name"),
            ]) or ""

        # ── description / overview ────────────────────────────────────────
        if not n.get("description"):
            raw_desc = _primeira_str([
                ta.get("description"),
                ta.get("overview"),
                ta.get("summary"),
                gen.get("overview"),
                gen.get("description"),
                gen.get("summary"),
                n.get("detailed_description"),     # Plump Spider alias
                n.get("overview"),                 # flat alias
                n.get("summary"),                  # flat alias (mapped last to avoid
                                                   # overwriting description with a short summary)
            ]) or ""
            # Sanitise sentinel values ("No description available", "N/A", …)
            n["description"] = _sanitize_str(raw_desc)

        # ── motivation ────────────────────────────────────────────────────
        if not n.get("motivation"):
            mot_raw = (
                ta.get("motivation")
                or gen.get("motivation")
                or n.get("motivation_raw")
                or n.get("motivation")
            )
            if mot_raw:
                # Sanitise sentinel values element-by-element
                n["motivation"] = _sanitize_list(mot_raw)

        # ── first-seen / active_since ─────────────────────────────────────
        if not n.get("first-seen"):
            raw_fs = _primeira_str([
                ta.get("first_observed"),
                ta.get("first_seen"),
                ta.get("active_since"),
                gen.get("active_since"),
                gen.get("first_seen"),
                gen.get("first_activity"),
                gen.get("status_since"),
                n.get("first_observed"),
                n.get("first_seen"),
                n.get("active_since"),
            ]) or ""
            n["first-seen"] = _sanitize_str(raw_fs)

        # ── last-seen / last_activity ─────────────────────────────────────
        # The ETDA field is "last-seen"; LLM models may use various alternative
        # key names at root level or inside general_information / threat_actor.
        if not n.get("last-seen"):
            raw_ls = _primeira_str([
                n.get("last-seen"),          # canonical key (already checked above)
                n.get("last_seen"),          # snake_case top-level variant
                n.get("last_activity"),      # activity-based alias
                n.get("active_until"),       # "active until" alias
                n.get("last_observed"),      # "last observed" alias
                ta.get("last_seen"),
                ta.get("status"),         # nested inside threat_actor
                ta.get("last_observed"),
                ta.get("last_activity"),
                ta.get("active_until"),
                gen.get("last_seen"),        # nested inside general_information
                gen.get("last_activity"),
                gen.get("active_until"),
                gen.get("last_observed"),
            ]) or ""
            n["last-seen"] = _sanitize_str(raw_ls)

        # ── country_of_origin / suspected_origin → country ───────────────
        # country_of_origin may be a dict (sub-object) or a plain string.
        coo_raw = n.get("country_of_origin")
        if isinstance(coo_raw, str):
            # Plump Spider schema: "country_of_origin": "Russia (Suspected)"
            coo = {}
            if not n.get("country"):
                c = _sanitize_str(coo_raw)
                n["country"] = [c] if c else []
        else:
            coo = coo_raw or {}
            if not isinstance(coo, dict):
                coo = {}
        if not n.get("country"):
            primary = _sanitize_str(_primeira_str([
                ta.get("suspected_origin"),
                ta.get("country"),
                ta.get("origin"),
                coo.get("primary_location"),
                coo.get("location"),
                coo.get("country"),
                coo.get("origin"),
                n.get("suspected_origin"),
                n.get("suspected_attribution"),
                n.get("origin"),                  # flat "origin" alias
            ]))
            n["country"] = [primary] if primary else []

        # ── targeted sectors ──────────────────────────────────────────────
        if not n.get("observed-sectors"):
            # Try targeting sub-object (new LLM fallback schema)
            raw = (
                tgt.get("industries")
                or tgt.get("sectors")
                or tgt.get("targeted_sectors")
                or ta.get("target_sectors")
                or n.get("target_sectors")
                or tgt.get("targeted_industries")
                or []
            )
            # Try nested sub-object (schema v1 / original prompt)
            if not raw:
                tsg = n.get("targeted_sectors_and_geographies") or {}
                if isinstance(tsg, dict):
                    raw = tsg.get("targeted_sectors") or tsg.get("sectors") or []
            # Fall back to flat top-level aliases — includes Plump Spider keys
            if not raw:
                raw = (
                    n.get("target_sectors")          # Plump Spider alias
                    or n.get("targeted_sectors")
                    or n.get("targeted_industries")
                    or n.get("observed_sectors")
                    or n.get("industries")
                    or n.get("sectors")
                    or []
                )
            # Sanitise sentinel values element-by-element
            n["observed-sectors"] = _sanitize_list(raw)

        # ── targeted geographies / observed-countries ─────────────────────
        if not n.get("observed-countries"):
            raw = (
                tgt.get("geographies")
                or tgt.get("countries")
                or tgt.get("targeted_geographies")
                or ta.get("target_geographies")
                or tgt.get("targeted_countries")
                or []
            )
            if not raw:
                tsg = n.get("targeted_sectors_and_geographies") or {}
                if isinstance(tsg, dict):
                    raw = (
                        tsg.get("targeted_geographies")
                        or tsg.get("geographies")
                        or []
                    )
            if not raw:
                raw = (
                    n.get("target_geographies")      # Plump Spider alias
                    or n.get("target_countries")     # Plump Spider alias
                    or n.get("target_geography")
                    or n.get("targeted_geographies")
                    or n.get("targeted_countries")
                    or n.get("observed_countries")
                    or n.get("geographies")
                    or n.get("countries")
                    or []
                )
            # Sanitise sentinel values element-by-element
            n["observed-countries"] = _sanitize_list(raw)

        # ── tools / malware ───────────────────────────────────────────────
        if not n.get("tools"):
            raw_tools = (
                n.get("malware_and_tools")       # Plump Spider alias
                or n.get("tools_and_malware")
                or n.get("tools_used")
                or n.get("malware")
                or n.get("software")
                or n.get("associated_tools_and_malware")  # FallBack schema (list of {name, category, description})
                or []
            )
            # Handle list of dicts [{"name": "...", "type": "...", ...}] or list of str
            if isinstance(raw_tools, list):
                extracted_tools = []
                for item in raw_tools:
                    if isinstance(item, dict):
                        tool_name = item.get("name") or item.get("tool") or item.get("malware")
                        if tool_name:
                            clean = _sanitize_str(str(tool_name))
                            if clean:
                                extracted_tools.append(clean)
                    elif item:
                        clean = _sanitize_str(str(item))
                        if clean:
                            extracted_tools.append(clean)
                n["tools"] = extracted_tools
            else:
                n["tools"] = _sanitize_list(raw_tools)

        # ── aliases / names ───────────────────────────────────────────────
        # The LLM sometimes returns aliases as a flat list of strings under
        # "aliases" at root or inside general_information / threat_actor.
        # The ETDA schema expects "names" as a list of {"name": ..., "name-giver": ...} dicts.
        # We promote flat string aliases to that format when "names" is empty.
        if not n.get("names"):
            raw_aliases = (
                ta.get("aliases")
                or n.get("aliases")
                or gen.get("aliases")
                or n.get("known_aliases")          # Plump Spider alias
                or n.get("alternative_names")      # generic alias
                or []
            )
            # Sanitise sentinel values before promoting to name dicts
            alias_list = _sanitize_list(raw_aliases)
            if alias_list:
                n["names"] = [
                    {"name": a, "name-giver": "LLM"} for a in alias_list
                ]

        # ── operations / notable_campaigns ────────────────────────────────
        if not n.get("operations"):
            raw_campaigns = (
                n.get("notable_campaigns")
                or n.get("campaigns")
                or n.get("operations")
                or []
            )
            if isinstance(raw_campaigns, list) and raw_campaigns:
                ops_list = []
                for camp in raw_campaigns:
                    if isinstance(camp, dict):
                        dt = str(camp.get("year") or camp.get("date") or "").strip()
                        tit = str(camp.get("title") or "").strip()
                        det = str(camp.get("details") or camp.get("activity") or camp.get("description") or "").strip()
                        activity_text = f"{tit} - {det}".strip(" -") if tit and det else (tit or det)
                        if activity_text:
                            ops_list.append({"date": dt, "activity": activity_text})
                    elif isinstance(camp, str) and camp.strip():
                        ops_list.append({"date": "", "activity": camp.strip()})
                if ops_list:
                    n["operations"] = ops_list

        # ── authoritative_references / information ───────────────────────
        # The LLM may return references as:
        #   a) flat URL strings           → stored as-is
        #   b) ETDA-style dicts           → {"title": ..., "url": ...}
        #   c) LLM-style source/title     → {"source": ..., "title": ...}
        # Cases (b) and (c) must be preserved as dicts so the renderer can
        # format them properly; only plain strings and unrecognised scalars
        # are coerced via _como_lista.
        if not n.get("information"):
            raw_refs = (
                n.get("authoritative_references")
                or n.get("references")
                or n.get("reference_urls")
                or n.get("sources")
                or []
            )
            if raw_refs:
                if isinstance(raw_refs, list):
                    coerced_refs = []
                    for ref in raw_refs:
                        if isinstance(ref, dict):
                            # Preserve dicts intact — renderer handles both
                            # {"title", "url"} and {"source", "title"} shapes
                            coerced_refs.append(ref)
                        elif ref:
                            s = _sanitize_str(str(ref))
                            if s:
                                coerced_refs.append(s)
                    n["information"] = coerced_refs
                else:
                    s = _sanitize_str(str(raw_refs))
                    n["information"] = [s] if s else []

        # ── Collect LLM-only extra fields for dedicated rendering ─────────
        extra: Dict = {}

        # crowdstrike_identifier / actor_type from general_information or threat_actor
        cs_id = _primeira_str([
            ta.get("crowdstrike_identifier"),
            ta.get("crowdstrike_id"),
            ta.get("cs_id"),
            gen.get("crowdstrike_identifier"),
            gen.get("crowdstrike_id"),
            gen.get("cs_id"),
        ])
        if cs_id:
            extra["crowdstrike_identifier"] = cs_id

        at = _primeira_str([
            ta.get("category"),
            ta.get("actor_type"),
            ta.get("type"),
            gen.get("actor_type"),
            gen.get("type"),
            gen.get("category"),
        ])
        if at:
            extra["actor_type"] = at

        # Status
        status_val = _primeira_str([ta.get("status"), gen.get("status"), n.get("status")])
        if status_val:
            extra["status"] = status_val

        # country_of_origin region / details / suspected_origin
        region = _primeira_str([
            ta.get("suspected_origin"),
            coo.get("region"),
            coo.get("area"),
            coo.get("sub_region"),
        ])
        if not region:
            # Fall back to the 'details' field which often contains region info
            details = _primeira_str([coo.get("details")])
            if details:
                region = details[:120]
        if region:
            extra["origin_region"] = region

        # modus_operandi — resolve key name aliases including attack_vectors
        mo = n.get("modus_operandi") or {}
        if not isinstance(mo, dict):
            mo = {}
        mo_desc = _primeira_str([
            mo.get("description"),
            mo.get("summary"),
            mo.get("overview"),
        ])
        mo_tactics_raw = (
            mo.get("key_tactics")
            or mo.get("key_activities")
            or mo.get("tactics")
            or mo.get("activities")
            or n.get("attack_vectors")
            or []
        )
        mo_tactics = _como_lista(mo_tactics_raw)
        if mo_desc or mo_tactics:
            extra["modus_operandi"] = {
                "description": mo_desc or "",
                "key_tactics": mo_tactics,
            }

        # ── MITRE ATT&CK structured techniques ────────────────────────────
        # Schema v1 (original system prompt):
        #   mitre_attack_tactics_and_techniques: {tactic_key: [{technique_id, ...}]}
        # Schema v2 (real gemini / claude responses):
        #   tactics_and_techniques: {framework: ..., items: [{tactic, technique_id, ...}]}
        # Schema v3 (other variants):
        #   mitre_attack_matrix | mitre_attack | attack_techniques | techniques: [{...}]
        matt_canonical: Dict = {}

        # Check schema v1 first
        matt_v1 = n.get("mitre_attack_tactics_and_techniques") or {}
        if isinstance(matt_v1, dict) and matt_v1:
            matt_canonical = matt_v1

        # Check schema v2 — items list with a 'tactic' field per item
        if not matt_canonical:
            tt_block = n.get("tactics_and_techniques") or {}
            if not isinstance(tt_block, dict):
                tt_block = {}
            items = tt_block.get("items") or []
            if not isinstance(items, list):
                items = []
            if items:
                # Re-index by tactic key so the renderer (which iterates by
                # tactic) can process them uniformly
                from collections import defaultdict as _dd
                grouped: Dict = _dd(list)
                for item in items:
                    if not isinstance(item, dict):
                        continue
                    tactic_label = str(item.get("tactic", "unknown")).lower()
                    tactic_key = tactic_label.replace(" ", "_").replace("-", "_")
                    tech_entry = {
                        "technique_id":   item.get("technique_id", ""),
                        "technique_name": item.get("technique_name", ""),
                        "description":    item.get("description", ""),
                    }
                    grouped[tactic_key].append(tech_entry)
                matt_canonical = dict(grouped)

        # Check schema v3 flat alternatives (including mitre_attack_matrix)
        # Also handles "mitre_attack_techniques" (Plump Spider schema key)
        if not matt_canonical:
            for key in (
                "mitre_attack_matrix", "mitre_attack", "attack_techniques",
                "techniques", "mitre_attack_techniques",   # Plump Spider alias
            ):
                raw_flat = n.get(key)
                if isinstance(raw_flat, list) and raw_flat:
                    from collections import defaultdict as _dd
                    grouped2: Dict = _dd(list)
                    for item in raw_flat:
                        if not isinstance(item, dict):
                            continue
                        tactic_label = str(item.get("tactic", "unknown")).lower()
                        tactic_key = tactic_label.replace(" ", "_").replace("-", "_")
                        grouped2[tactic_key].append({
                            "technique_id":   item.get("technique_id", ""),
                            "technique_name": item.get("technique_name", ""),
                            "description":    item.get("description", ""),
                        })
                    matt_canonical = dict(grouped2)
                    break

        if matt_canonical:
            extra["mitre_attack_tactics_and_techniques"] = matt_canonical

        # ── tactics_techniques_procedure (new ETDA-LLM field) ─────────────
        # Accept the canonical key produced by the new system prompt plus
        # several aliases that LLMs have been observed to use.
        ttp_raw = (
            n.get("tactics_techniques_procedure")
            or n.get("tactics_techniques_procedures")  # plural variant
            or n.get("ttp")
            or n.get("ttps")
            or n.get("attack_patterns")
            or n.get("tactics_techniques")
        )
        if isinstance(ttp_raw, dict) and ttp_raw:
            extra["tactics_techniques_procedure"] = ttp_raw

        # ── mitigation_and_defenses (new ETDA-LLM field) ──────────────────
        # Accept canonical key plus common aliases (dict or flat list)
        mit_raw = (
            n.get("mitigation_and_defenses")
            or n.get("mitigations_and_defenses")    # alternate spelling
            or n.get("mitigations")
            or n.get("defenses")
            or n.get("defense_recommendations")
            or n.get("countermeasures")
        )
        if isinstance(mit_raw, dict) and mit_raw:
            extra["mitigation_and_defenses"] = mit_raw
        elif isinstance(mit_raw, list) and mit_raw:
            extra["mitigation_and_defenses"] = {
                "mitigations": [],
                "defense_recommendations": _como_lista(mit_raw),
                "detection_indicators": [],
            }

        # ── group_profile schema (FallBack / new LLM schema) ─────────────────
        # When the LLM returns the alternative top-level "group_profile" key,
        # preserve the entire sub-object (and its sibling sections) inside
        # _llm_extra so the renderer can present them in dedicated blocks.
        gp_raw = n.get("group_profile")
        if isinstance(gp_raw, dict) and gp_raw:
            # Sanitise every scalar field — discard "N/A", "None", etc.
            extra["group_profile_data"] = {
                "primary_name":       _sanitize_str(gp_raw.get("primary_name")),
                "threat_actor_type":  _sanitize_str(gp_raw.get("threat_actor_type")),
                "aliases":            _sanitize_list(gp_raw.get("aliases") or []),
                "first_seen":         _sanitize_str(gp_raw.get("first_seen")),
                "origin_location":    _sanitize_str(gp_raw.get("origin_location")),
                "motivation":         _sanitize_str(gp_raw.get("motivation")),
                "active_status":      _sanitize_str(gp_raw.get("active_status")),
                "summary":            _sanitize_str(gp_raw.get("summary")),
            }

            # ── Propagate group_profile fields to canonical schema fields ────────
            # group_profile sub-fields are nested, so the earlier alias resolution
            # (which only looks at root keys and known sub-objects) misses them.
            # Populate canonical fields here, only when still empty, so higher-
            # priority sources already resolved above are never overwritten.

            # actor name — primary_name
            if not n.get("actor"):
                gp_name = _sanitize_str(gp_raw.get("primary_name"))
                if gp_name:
                    n["actor"] = gp_name

            # first-seen — first_seen
            if not n.get("first-seen"):
                gp_fs = _sanitize_str(gp_raw.get("first_seen"))
                if gp_fs:
                    n["first-seen"] = gp_fs

            # country — origin_location
            if not n.get("country"):
                gp_origin = _sanitize_str(gp_raw.get("origin_location"))
                if gp_origin:
                    n["country"] = [gp_origin]

            # motivation — motivation (may be a string or list in the FallBack schema)
            if not n.get("motivation"):
                gp_mot_raw = gp_raw.get("motivation")
                gp_mot = _sanitize_list(gp_mot_raw) if isinstance(gp_mot_raw, list) else (
                    [_sanitize_str(gp_mot_raw)] if gp_mot_raw and not _is_empty_value(gp_mot_raw) else []
                )
                if gp_mot:
                    n["motivation"] = gp_mot

            # names / aliases — aliases list
            if not n.get("names"):
                gp_aliases = _sanitize_list(gp_raw.get("aliases") or [])
                if gp_aliases:
                    n["names"] = [{"name": a, "name-giver": "LLM"} for a in gp_aliases]

            # description — summary
            if not n.get("description"):
                gp_summary = _sanitize_str(gp_raw.get("summary"))
                if gp_summary:
                    n["description"] = gp_summary

        # target_demographics — sanitise lists element-by-element
        td_raw = n.get("target_demographics")
        if isinstance(td_raw, dict) and td_raw:
            extra["target_demographics_data"] = {
                "sectors":              _sanitize_list(td_raw.get("sectors") or []),
                "geographies":          _sanitize_list(td_raw.get("geographies") or []),
                "excluded_geographies": _sanitize_list(td_raw.get("excluded_geographies") or []),
            }

            # ── Propagate target_demographics to canonical schema fields ─────────
            # These lists are the most specific source for observed sectors and
            # observed countries in the FallBack schema — populate canonical fields
            # only when they are still empty (do-not-overwrite convention).

            # observed-sectors — sectors
            if not n.get("observed-sectors"):
                td_sectors = _sanitize_list(td_raw.get("sectors") or [])
                if td_sectors:
                    n["observed-sectors"] = td_sectors

            # observed-countries — geographies (target countries, not excluded)
            if not n.get("observed-countries"):
                td_geos = _sanitize_list(td_raw.get("geographies") or [])
                if td_geos:
                    n["observed-countries"] = td_geos

        # attack_vector_and_tactics
        avt_raw = n.get("attack_vector_and_tactics")
        if isinstance(avt_raw, dict) and avt_raw:
            extra["attack_vector_and_tactics_data"] = avt_raw  # keep full dict

        # mitre_attack_mapping (flat list schema from group_profile FallBack)
        # Also accept "mitre_attack_techniques" (Plump Spider schema key) as
        # an alternative source for the same flat-list mapping data.
        mam_raw = (
            n.get("mitre_attack_mapping")
            or n.get("mitre_attack_techniques")
            or n.get("tactics_techniques_procedures")    # Plump Spider alias
        )
        if isinstance(mam_raw, list) and mam_raw:
            extra["mitre_attack_mapping_data"] = mam_raw

        # associated_tools_and_malware (rich list with name/category/description)
        atm_raw = n.get("associated_tools_and_malware")
        if isinstance(atm_raw, list) and atm_raw:
            extra["associated_tools_and_malware_data"] = atm_raw

        # mitigations_and_recommendations — accepts both:
        #   a) flat list of strings (legacy / FallBack)
        #   b) list of {category, actions[]} dicts (Plump Spider / structured)
        mar_raw = n.get("mitigations_and_recommendations")
        if isinstance(mar_raw, list) and mar_raw:
            # Check if entries are dicts (structured) or plain strings (flat)
            if mar_raw and isinstance(mar_raw[0], dict):
                # Structured — preserve as-is for mit_recs renderer
                extra["mitigation_recommendations_data"] = mar_raw
                # Also build a flattened version for the legacy mar renderer
                flat_items = []
                for entry in mar_raw:
                    if isinstance(entry, dict):
                        cat = _sanitize_str(entry.get("category", ""))
                        for act in _como_lista(entry.get("actions") or []):
                            clean = _sanitize_str(str(act))
                            if clean:
                                flat_items.append(f"{cat}: {clean}" if cat else clean)
                if flat_items:
                    extra["mitigations_and_recommendations_data"] = flat_items
            else:
                extra["mitigations_and_recommendations_data"] = _sanitize_list(mar_raw)

        # authoritative_sources — sanitise flat list
        as_raw = n.get("authoritative_sources")
        if isinstance(as_raw, list) and as_raw:
            extra["authoritative_sources_data"] = _sanitize_list(as_raw)

        # ── [NEW] Plump Spider / variant schema fields ────────────────────────
        # attack_lifecycle — ordered phases list
        # Accepts list of strings or list of {phase, description/activity} dicts.
        al_raw = n.get("attack_lifecycle")
        if isinstance(al_raw, list) and al_raw:
            extra["attack_lifecycle_data"] = al_raw

        # infrastructure_and_c2 — C2 / infrastructure details
        # Accepts a dict {c2_protocols, hosting, obfuscation, ...} or a plain string.
        ic2_raw = n.get("infrastructure_and_c2")
        if ic2_raw:
            if isinstance(ic2_raw, dict):
                extra["infrastructure_and_c2_data"] = ic2_raw
            elif isinstance(ic2_raw, str):
                s = _sanitize_str(ic2_raw)
                if s:
                    extra["infrastructure_and_c2_data"] = {"description": s}

        # ── [NEW] Structured schema fields (9-key fixed schema) ──────────────
        # These three keys belong to the _LLM_APT_STRUCTURED_SYSTEM_PROMPT
        # schema and are absent from the legacy FallBack / ETDA schemas.

        # profile — metadata block (title, last_updated, tlp_classification)
        prof_raw = n.get("profile")
        if isinstance(prof_raw, dict) and prof_raw:
            extra["profile_data"] = {
                "title":              _sanitize_str(prof_raw.get("title")),
                "last_updated":       _sanitize_str(prof_raw.get("last_updated")),
                "tlp_classification": _sanitize_str(prof_raw.get("tlp_classification")),
            }

        # attack_chain_and_tactics — 9-key structured tactic dict
        act_raw = n.get("attack_chain_and_tactics")
        if isinstance(act_raw, dict) and act_raw:
            extra["attack_chain_and_tactics_data"] = act_raw  # keep full dict

        # mitigation_recommendations — list of {category, actions[]} dicts
        mit_recs_raw = n.get("mitigation_recommendations")
        if isinstance(mit_recs_raw, list) and mit_recs_raw:
            extra["mitigation_recommendations_data"] = mit_recs_raw

        # authoritative_references — list of {source, title, type} dicts
        auth_refs_raw = n.get("authoritative_references")
        if isinstance(auth_refs_raw, list) and auth_refs_raw:
            extra["authoritative_references_data"] = auth_refs_raw

        # ── actor_details / targeting_profile / associated_malware_and_tools ──
        # Some LLM models deviate from the system-prompt schema and return an
        # alternative top-level structure.  Map these keys into the canonical
        # shared fields so downstream rendering works correctly.
        # All mappings respect the "do not overwrite" convention: a field is
        # only set when it is still absent or contains only sentinel values.
        act_det = n.get("actor_details") or {}
        if not isinstance(act_det, dict):
            act_det = {}

        tgt_prof = n.get("targeting_profile") or {}
        if not isinstance(tgt_prof, dict):
            tgt_prof = {}

        amt = n.get("associated_malware_and_tools") or {}
        if not isinstance(amt, dict):
            amt = {}

        # country — actor_details.origin_region
        if not n.get("country"):
            origin = _sanitize_str(act_det.get("origin_region"))
            if origin:
                n["country"] = [origin]

        # motivation — actor_details.motivation
        if not n.get("motivation"):
            mot = act_det.get("motivation")
            cleaned_mot = _sanitize_list(mot) if isinstance(mot, list) else (
                [_sanitize_str(mot)] if mot and not _is_empty_value(mot) else []
            )
            if cleaned_mot:
                n["motivation"] = cleaned_mot

        # first-seen — actor_details.active_since
        if not n.get("first-seen"):
            n["first-seen"] = _sanitize_str(act_det.get("active_since"))

        # last-seen — actor_details.status
        if not n.get("last-seen"):
            n["last-seen"] = _sanitize_str(act_det.get("status"))

        # aliases / names — actor_details.aliases
        if not n.get("names"):
            raw_ad_aliases = act_det.get("aliases") or []
            ad_alias_list = _sanitize_list(raw_ad_aliases)
            if ad_alias_list:
                n["names"] = [{"name": a, "name-giver": "LLM"} for a in ad_alias_list]

        # observed-sectors — targeting_profile.target_industries
        if not n.get("observed-sectors"):
            raw_ind = tgt_prof.get("target_industries") or []
            cleaned_ind = _sanitize_list(raw_ind)
            if cleaned_ind:
                n["observed-sectors"] = cleaned_ind

        # observed-countries — targeting_profile.target_geographies
        if not n.get("observed-countries"):
            raw_geo = tgt_prof.get("target_geographies") or []
            cleaned_geo = _sanitize_list(raw_geo)
            if cleaned_geo:
                n["observed-countries"] = cleaned_geo

        # tools — concatenate the four sub-arrays of associated_malware_and_tools
        if not n.get("tools"):
            raw_tools_concat = (
                _como_lista(amt.get("first_stage_loaders") or [])
                + _como_lista(amt.get("secondary_payloads") or [])
                + _como_lista(amt.get("post_exploitation_and_utility") or [])
                + _como_lista(amt.get("ransomware_affiliations") or [])
            )
            cleaned_tools = list(dict.fromkeys(
                t for t in _sanitize_list(raw_tools_concat) if t
            ))  # deduplicate while preserving order
            if cleaned_tools:
                n["tools"] = cleaned_tools

        # description — summary (top-level)
        if not n.get("description"):
            n["description"] = _sanitize_str(n.get("summary"))

        # ── actor_profile sub-object aliases ──────────────────────────────────
        # Some LLM models wrap actor data inside an "actor_profile" sub-dict.
        # After root-level unwrapping (Step 4b in _normalizar_resposta_llm_apt)
        # the inner fields are usually already at root, but when the sub-object
        # survives (e.g. partial unwrap or direct call to the normaliser) we
        # resolve each field from actor_profile and fill any canonical field
        # that is still empty.  This is the fallback of last resort.
        ap = n.get("actor_profile") or {}
        if not isinstance(ap, dict):
            ap = {}

        # last-seen — actor_profile.active_period
        if not n.get("last-seen"):
            n["last-seen"] = _sanitize_str(ap.get("active_period"))

        # names / aliases — actor_profile.associated_names
        if not n.get("names"):
            raw_ap_names = ap.get("associated_names") or []
            ap_alias_list = _sanitize_list(raw_ap_names)
            if ap_alias_list:
                n["names"] = [{"name": a, "name-giver": "LLM"} for a in ap_alias_list]

        # motivation — actor_profile.motivation
        if not n.get("motivation"):
            ap_mot = ap.get("motivation")
            cleaned_ap_mot = _sanitize_list(ap_mot) if isinstance(ap_mot, list) else (
                [_sanitize_str(ap_mot)] if ap_mot and not _is_empty_value(ap_mot) else []
            )
            if cleaned_ap_mot:
                n["motivation"] = cleaned_ap_mot

        # country — actor_profile.origin
        if not n.get("country"):
            ap_origin = _sanitize_str(ap.get("origin"))
            if ap_origin:
                n["country"] = [ap_origin]

        # tools — associated_malware_and_tools (root key) OR nested inside actor_profile
        # Check the root key first; fall back to actor_profile sub-object.
        if not n.get("tools"):
            ap_amt = n.get("associated_malware_and_tools") or ap.get("associated_malware_and_tools") or {}
            if isinstance(ap_amt, dict) and ap_amt:
                ap_tools_concat = (
                    _como_lista(ap_amt.get("first_stage_loaders") or [])
                    + _como_lista(ap_amt.get("secondary_payloads") or [])
                    + _como_lista(ap_amt.get("post_exploitation_and_utility") or [])
                    + _como_lista(ap_amt.get("ransomware_affiliations") or [])
                )
                cleaned_ap_tools = list(dict.fromkeys(
                    t for t in _sanitize_list(ap_tools_concat) if t
                ))
                if cleaned_ap_tools:
                    n["tools"] = cleaned_ap_tools
            elif isinstance(ap_amt, list) and ap_amt:
                # Flat list of strings or {name, ...} dicts
                extracted = []
                for item in ap_amt:
                    if isinstance(item, dict):
                        tool_name = (
                            item.get("name") or item.get("tool") or item.get("malware")
                        )
                        if tool_name:
                            clean = _sanitize_str(str(tool_name))
                            if clean:
                                extracted.append(clean)
                    elif item:
                        clean = _sanitize_str(str(item))
                        if clean:
                            extracted.append(clean)
                if extracted:
                    n["tools"] = list(dict.fromkeys(extracted))

        # MITRE ATT&CK — mitre_attack_ttps (root key) OR nested inside actor_profile
        # Check the root key first; fall back to actor_profile sub-object.
        ap_ttps_raw = n.get("mitre_attack_ttps") or ap.get("mitre_attack_ttps")
        if isinstance(ap_ttps_raw, list) and ap_ttps_raw:
            # Persist full list in extra for dedicated renderer (same slot as
            # mitre_attack_mapping_data so the existing MITRE table renders it)
            if not extra.get("mitre_attack_mapping_data"):
                extra["mitre_attack_mapping_data"] = ap_ttps_raw
            # Also feed bare technique IDs into the canonical mitre-attack list
            current_mitre = list(n.get("mitre-attack") or [])
            for ttp in ap_ttps_raw:
                if isinstance(ttp, dict):
                    tid = _sanitize_str(ttp.get("technique_id", ""))
                    if tid and tid not in current_mitre:
                        current_mitre.append(tid)
                elif isinstance(ttp, str):
                    clean_id = _sanitize_str(ttp)
                    if clean_id and clean_id not in current_mitre:
                        current_mitre.append(clean_id)
            if current_mitre:
                n["mitre-attack"] = current_mitre

        # MITRE ATT&CK — mitre_att_and_ck (root key alias)
        # Feeds the same canonical fields as mitre_attack_ttps above.
        # Only runs when mitre_attack_mapping_data is still empty (i.e. no
        # higher-priority key has already populated it).
        mitre_alt_raw = n.get("mitre_att_and_ck")
        if isinstance(mitre_alt_raw, list) and mitre_alt_raw:
            if not extra.get("mitre_attack_mapping_data"):
                extra["mitre_attack_mapping_data"] = mitre_alt_raw
            current_mitre_alt = list(n.get("mitre-attack") or [])
            for ttp in mitre_alt_raw:
                if isinstance(ttp, dict):
                    tid = _sanitize_str(ttp.get("technique_id", ""))
                    if tid and tid not in current_mitre_alt:
                        current_mitre_alt.append(tid)
                elif isinstance(ttp, str):
                    clean_id = _sanitize_str(ttp)
                    if clean_id and clean_id not in current_mitre_alt:
                        current_mitre_alt.append(clean_id)
            if current_mitre_alt:
                n["mitre-attack"] = current_mitre_alt

        # motivation — primary_motivations (root key alias)
        # Only runs when motivation is still unset or empty.
        if not n.get("motivation"):
            pm_raw = n.get("primary_motivations")
            if pm_raw:
                n["motivation"] = _sanitize_list(pm_raw)

        n["_llm_extra"] = extra

    # ── Ensure all shared list fields are flat List[str] ─────────────────────
    # String fields (information, names) are NOT coerced to flat strings here —
    # they keep their dict-element structure so callers that iterate them
    # (e.g. _extrair_aliases, reference-link renderer) continue to work.
    for list_field in (
        "country", "motivation", "observed-sectors",
        "observed-countries", "tools", "mitre-attack",
    ):
        val = n.get(list_field)
        if val is None:
            n[list_field] = []
        elif isinstance(val, list):
            # Flatten to remove nested lists, then strip sentinel values
            # ("N/A", "unknown", etc.) element-by-element.
            n[list_field] = _sanitize_list(val)
        else:
            # Scalar value (str / int / …) — wrap as single-element list,
            # discarding sentinel values.
            if isinstance(val, str):
                clean = _sanitize_str(val)
                n[list_field] = [clean] if clean else []
            else:
                n[list_field] = [str(val)]

    # ── Sanitise shared scalar string fields (applies to LLM and ETDA) ───────
    # These fields may arrive pre-populated with LLM sentinel strings like
    # "N/A", "Unknown", "No description available" which are converted to
    # empty string so the renderer shows the proper placeholder instead.
    for str_field in ("description", "first-seen", "last-seen"):
        raw = n.get(str_field)
        if raw is not None:
            n[str_field] = _sanitize_str(raw)

    # "information" and "names" hold dicts — preserve as-is but ensure list type
    for list_field in ("information", "names"):
        val = n.get(list_field)
        if val is None:
            n[list_field] = []
        elif not isinstance(val, list):
            n[list_field] = [val]
        # Elements may be dicts; do NOT stringify them here

    # ── Ensure enrichment private fields exist with safe defaults ────────────
    for priv_list in (
        "_otx_iocs", "_kev_correlacoes", "_threatfox_iocs",
        "_malwarebazaar_amostras", "_ransomware_vitimas",
        "_misp_eventos", "_opencti_dados", "_malpedia_families",
    ):
        if not isinstance(n.get(priv_list), list):
            n[priv_list] = []

    for priv_dict in ("_malpedia_actor",):
        if not isinstance(n.get(priv_dict), dict):
            n[priv_dict] = {}

    if not isinstance(n.get("_otx_pulses"), int):
        n["_otx_pulses"] = 0

    if "_llm_extra" not in n:
        n["_llm_extra"] = {}

    return n


# ─── OTX AlienVault enrichment ───────────────────────────────────────────────

# Maximum number of pulses and indicators fetched per actor — controls the
# request volume against the API without degrading the report usefulness.
_OTX_MAX_PULSOS      = 5    # pulses returned by the search
_OTX_MAX_INDICADORES = 10   # indicators fetched per pulse

# Extended timeout for the OTX API, which frequently takes 30-40s to respond
# on free-text searches. The default 20s timeout was insufficient, causing
# silent ReadTimeout errors on most calls.
_OTX_TIMEOUT_BUSCA   = 45   # seconds — pulse search (slowest operation)
_OTX_TIMEOUT_IOCS    = 30   # seconds — indicator fetch per pulse

# Specific TTL for cached empty OTX results (0 pulses found).
# When the API returns 0 results — whether due to an unknown actor, partial
# timeout, or momentary unavailability — the result must not be cached under
# the global 24h TTL, as that would block retries within the same session.
# With the short TTL (10 min), the empty cache entry expires quickly and the
# search is retried.
_OTX_CACHE_TTL_VAZIO = 600  # 10 minutes


def _buscar_otx_indicadores_pulso(pulse_id: str, headers: Dict[str, str]) -> List[Dict]:
    """
    Fetch the indicators (IoCs) for a specific OTX pulse.

    Uses the correct API v1 endpoint:
        GET /api/v1/pulses/{pulse_id}/indicators

    The /api/v1/search/pulses endpoint does NOT return indicators embedded in
    the pulse objects — they must be retrieved separately via this endpoint.
    Each returned indicator contains at least the following fields:
        indicator : IoC value (IP, domain, hash, URL, etc.)
        type      : indicator type (IPv4, domain, FileHash-MD5, etc.)
        created   : creation date/time (ISO 8601)
        title     : optional indicator title/description

    The response is cached individually by pulse_id to avoid duplicate
    requests within the same session.
    """
    chave_cache = f"otx_pulse_iocs_{pulse_id}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        logger.debug("OTX cache HIT for pulse indicators %s", pulse_id)
        return cached

    url = f"https://otx.alienvault.com/api/v1/pulses/{pulse_id}/indicators"
    try:
        resp = requests.get(url, headers=headers, timeout=_OTX_TIMEOUT_IOCS)
        if resp.status_code == 429:
            logger.warning("OTX rate-limit (429) on pulse indicators %s — waiting 10s", pulse_id)
            time.sleep(10)
            resp = requests.get(url, headers=headers, timeout=_OTX_TIMEOUT_IOCS)
        if resp.status_code == 404:
            logger.debug("OTX pulse not found (404): %s", pulse_id)
            return []
        if resp.status_code == 403:
            logger.warning("OTX access denied (403) for pulse %s — check OTX_API_KEY", pulse_id)
            return []
        resp.raise_for_status()
        # The indicators endpoint response structure:
        # { "results": [...], "count": N, "next": ..., "previous": ... }
        dados = resp.json()
        iocs = dados.get("results", [])
        if not isinstance(iocs, list):
            logger.debug("OTX: unexpected indicator structure for pulse %s", pulse_id)
            iocs = []
        _cache_set(chave_cache, iocs)
        return iocs
    except Timeout:
        logger.warning("OTX timeout fetching indicators for pulse %s", pulse_id)
    except ConnectionError:
        logger.warning("OTX no connection while fetching indicators for pulse %s", pulse_id)
    except RequestException as exc:
        logger.warning("OTX request error on indicators for pulse %s: %s", pulse_id, exc)
    except Exception as exc:
        logger.warning("OTX unexpected error on indicators for pulse %s: %s", pulse_id, exc)
    return []


def _buscar_otx(nome_ator: str) -> Dict:
    """
    Search threat actor information on OTX AlienVault (requires OTX_API_KEY).

    Correct OTX API v1 flow
    -----------------------
    1. GET /api/v1/search/pulses?q={name}&limit=N
       Returns a list of pulses related to the search term.
       IMPORTANT: this response does NOT include the 'indicators' field
       embedded in the pulse objects — only metadata (id, name, author,
       tags, etc.).

    2. For each returned pulse, GET /api/v1/pulses/{id}/indicators
       Returns the actual IoCs for that pulse with fields:
           indicator, type, created, title, description, etc.

    Returns a dict with the structure expected by the enrichment block:
        {
          "results": [
            {
              "id":         str,   -- pulse ID
              "name":       str,   -- pulse title
              "author":     str,   -- pulse author
              "tags":       list,  -- pulse tags
              "indicators": list,  -- IoCs retrieved via secondary endpoint
            },
            ...
          ],
          "count": int
        }

    Results with 0 pulses are cached with a short TTL (_OTX_CACHE_TTL_VAZIO)
    to allow retries within the same session if the failure is transient.
    Incorrect parameters or a missing key result in an empty dict, fully
    preserving the original group data.
    """
    if not OTX_API_KEY:
        return {}

    chave_cache = f"otx_{nome_ator}"

    # Check the cache respecting the reduced TTL for empty results.
    # _cache_get uses the global TTL (24h); here we check manually to
    # distinguish between "no result" and "with result".
    cache_raw = _carregar_cache()
    entrada_cache = cache_raw.get(chave_cache)
    if entrada_cache:
        ts_cache = entrada_cache.get("timestamp", 0)
        dados_cache = entrada_cache.get("dados")
        if dados_cache is not None:
            qtd_cache = len(dados_cache.get("results", [])) if isinstance(dados_cache, dict) else 0
            # Apply short TTL when the cached result is empty (0 pulses)
            ttl_aplicavel = _OTX_CACHE_TTL_VAZIO if qtd_cache == 0 else CACHE_TTL
            if (time.time() - ts_cache) < ttl_aplicavel:
                logger.debug("OTX cache HIT for actor: %s (%d pulse(s))", nome_ator, qtd_cache)
                return dados_cache

    headers = {"X-OTX-API-KEY": OTX_API_KEY}

    # Step 1 — search for pulses related to the actor.
    # The name is URL-encoded to correctly handle spaces and special
    # characters (e.g. "Lazarus Group" → "Lazarus%20Group").
    nome_encoded = _url_quote(nome_ator, safe="")
    url_busca = (
        f"https://otx.alienvault.com/api/v1/search/pulses"
        f"?q={nome_encoded}&limit={_OTX_MAX_PULSOS}"
    )

    # Attempt the request with a second try in case of timeout.
    # The OTX API is known to be slow (30-40s on free-text searches).
    resp_busca = None
    for tentativa in range(1, 3):  # up to 2 attempts
        try:
            resp_busca = requests.get(url_busca, headers=headers, timeout=_OTX_TIMEOUT_BUSCA)
            break  # success — exit the retry loop
        except Timeout:
            logger.warning(
                "OTX timeout searching pulses for '%s' (attempt %d/2)",
                nome_ator, tentativa,
            )
            if tentativa < 2:
                time.sleep(5)  # brief wait before retry
            else:
                return {}
        except ConnectionError:
            logger.warning("OTX no connection while searching pulses for '%s'", nome_ator)
            return {}
        except RequestException as exc:
            logger.warning("OTX request error searching for '%s': %s", nome_ator, exc)
            return {}
        except Exception as exc:
            logger.warning("OTX unexpected error searching for '%s': %s", nome_ator, exc)
            return {}

    if resp_busca is None:
        return {}

    try:
        if resp_busca.status_code == 429:
            logger.warning("OTX rate-limit (429) on pulse search for '%s' — waiting 10s", nome_ator)
            time.sleep(10)
            resp_busca = requests.get(url_busca, headers=headers, timeout=_OTX_TIMEOUT_BUSCA)
        if resp_busca.status_code == 401:
            logger.error("OTX authentication failed (401) — check the OTX_API_KEY variable")
            return {}
        if resp_busca.status_code == 403:
            logger.error("OTX access denied (403) on pulse search for '%s'", nome_ator)
            return {}
        resp_busca.raise_for_status()
    except Timeout:
        logger.warning("OTX timeout on rate-limit retry for '%s'", nome_ator)
        return {}
    except RequestException as exc:
        logger.warning("OTX HTTP error on search for '%s': %s", nome_ator, exc)
        return {}

    try:
        payload = resp_busca.json()
    except Exception as exc:
        logger.warning("OTX invalid response (non-JSON) for '%s': %s", nome_ator, exc)
        return {}

    pulsos_raw = payload.get("results", [])
    if not isinstance(pulsos_raw, list):
        logger.debug("OTX: 'results' field missing or unexpected for '%s'", nome_ator)
        pulsos_raw = []

    # Step 2 — for each pulse, fetch the actual indicators via the dedicated
    # endpoint. The 'indicators' field is NOT present in the search response.
    pulsos_enriquecidos: List[Dict] = []
    for pulso in pulsos_raw[:_OTX_MAX_PULSOS]:
        if not isinstance(pulso, dict):
            continue
        pulse_id = pulso.get("id", "")
        indicadores: List[Dict] = []
        if pulse_id:
            indicadores = _buscar_otx_indicadores_pulso(pulse_id, headers)

        pulsos_enriquecidos.append({
            "id":         pulse_id,
            "name":       pulso.get("name", ""),
            "author":     pulso.get("author_name", ""),
            "tags":       pulso.get("tags", []),
            "indicators": indicadores[:_OTX_MAX_INDICADORES],
        })

    resultado = {
        "results": pulsos_enriquecidos,
        "count":   payload.get("count", len(pulsos_enriquecidos)),
    }
    # Persist to cache; results with 0 pulses use the short TTL (via the
    # custom check at the top of this function) to allow retries.
    _cache_set(chave_cache, resultado)
    logger.info(
        "OTX: %d pulse(s) found for '%s'",
        len(pulsos_enriquecidos), nome_ator,
    )
    return resultado


def _buscar_virustotal_malware(nome_malware: str) -> Dict:
    """
    Search malware information on VirusTotal (free tier).
    Returns metadata for the searched entity.
    """
    if not VT_API_KEY:
        return {}
    chave_cache = f"vt_{nome_malware}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    url = f"https://www.virustotal.com/api/v3/search?query={nome_malware}"
    headers = {"x-apikey": VT_API_KEY}
    resp = _req_get(url, headers=headers, timeout=20)
    if resp:
        dados = resp.json()
        _cache_set(chave_cache, dados)
        return dados
    return {}


def _buscar_cisa_kev() -> List[Dict]:
    """Download and return the CISA KEV (Known Exploited Vulnerabilities) list."""
    chave_cache = "cisa_kev"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    resp = _req_get(URL_CISA_KEV, timeout=30)
    if resp:
        dados = resp.json().get("vulnerabilities", [])
        _cache_set(chave_cache, dados)
        return dados
    return []


def _correlacionar_cisa_kev(resultado_grupo: Dict, kev_lista: List[Dict]) -> List[Dict]:
    """
    Correlaciona ferramentas/CVEs de um grupo com a lista CISA KEV.

    Cruza o campo 'tools' do grupo com os campos 'product' e 'vendorProject'
    do KEV. Retorna lista de entradas KEV correspondentes enriquecidas.
    """
    correlacoes: List[Dict] = []
    ferramentas_raw = resultado_grupo.get("tools", [])
    if isinstance(ferramentas_raw, str):
        ferramentas_raw = [f.strip() for f in ferramentas_raw.split(",")]
    ferramentas = [f.lower() for f in ferramentas_raw if f]

    for entrada in kev_lista:
        produto = entrada.get("product", "").lower()
        fornecedor = entrada.get("vendorProject", "").lower()
        cve = entrada.get("cveID", "")
        for ferr in ferramentas:
            if ferr and (ferr in produto or ferr in fornecedor):
                correlacoes.append({
                    "cve": cve,
                    "produto": entrada.get("product", ""),
                    "fornecedor": entrada.get("vendorProject", ""),
                    "nome_vuln": entrada.get("vulnerabilityName", ""),
                    "data_adicao": entrada.get("dateAdded", ""),
                    "data_limite": entrada.get("dueDate", ""),
                    "descricao_curta": entrada.get("shortDescription", "")[:200],
                    "ferramenta_match": ferr,
                })
                break  # evitar duplicatas por ferramenta
    # Ordenar por data de adição mais recente
    correlacoes.sort(key=lambda x: x.get("data_adicao", ""), reverse=True)
    return correlacoes


def _buscar_nvd_cve(cve_id: str) -> Dict:
    """
    Busca detalhes de um CVE na NVD (National Vulnerability Database).

    Retorna CVSS score/vetor e descrição. NVD_API_KEY melhora rate-limit (opcional).
    """
    chave_cache = f"nvd_{cve_id}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    params: Dict[str, str] = {"cveId": cve_id}
    headers = {}
    if NVD_API_KEY:
        headers["apiKey"] = NVD_API_KEY
    resp = _req_get(URL_NVD_CVE, headers=headers, timeout=20)
    if resp:
        try:
            vulns = resp.json().get("vulnerabilities", [])
            if vulns:
                cve_item = vulns[0].get("cve", {})
                # Pega CVSS v3.1 com fallback para v3.0 e v2.0
                metricas = cve_item.get("metrics", {})
                cvss_score = None
                cvss_vetor = None
                cvss_severidade = None
                for versao in ("cvssMetricV31", "cvssMetricV30", "cvssMetricV2"):
                    lista_metricas = metricas.get(versao, [])
                    if lista_metricas:
                        dados_cvss = lista_metricas[0].get("cvssData", {})
                        cvss_score = dados_cvss.get("baseScore")
                        cvss_vetor = dados_cvss.get("vectorString", "")
                        cvss_severidade = lista_metricas[0].get("baseSeverity", "")
                        break
                descricao = ""
                for desc in cve_item.get("descriptions", []):
                    if desc.get("lang") == "en":
                        descricao = desc.get("value", "")[:300]
                        break
                resultado = {
                    "cve": cve_id,
                    "cvss_score": cvss_score,
                    "cvss_vetor": cvss_vetor,
                    "cvss_severidade": cvss_severidade,
                    "descricao": descricao,
                }
                _cache_set(chave_cache, resultado)
                return resultado
        except Exception as e:
            logger.debug("Error parsing NVD response for %s: %s", cve_id, e)
    return {}


def _buscar_threatfox_malware(nome_malware: str) -> List[Dict]:
    """
    Search IoCs associated with a malware/family on ThreatFox (Abuse.ch).

    Returns a list of IoCs (IPs, domains, hashes) with metadata.
    No authentication required, but THREATFOX_API_KEY may be sent.
    """
    chave_cache = f"threatfox_{nome_malware.lower()}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    payload: Dict[str, Any] = {
        "query": "taginfo",
        "tag": nome_malware,
        "limit": 10,
    }
    headers: Dict[str, str] = {}
    if THREATFOX_API_KEY:
        headers["Auth-Key"] = THREATFOX_API_KEY
    try:
        resp = requests.post(URL_THREATFOX, json=payload, headers=headers, timeout=20)
        if resp and resp.status_code == 200:
            dados = resp.json()
            iocs = dados.get("data", []) or []
            if isinstance(iocs, list):
                resultado = [
                    {
                        "ioc": item.get("ioc", ""),
                        "tipo": item.get("ioc_type", ""),
                        "confianca": item.get("confidence_level", 0),
                        "malware": item.get("malware", ""),
                        "data": item.get("first_seen", ""),
                    }
                    for item in iocs[:10]
                ]
                _cache_set(chave_cache, resultado)
                return resultado
    except Exception as e:
        logger.debug("ThreatFox error for %s: %s", nome_malware, e)
    return []


def _buscar_malwarebazaar(nome_malware: str) -> List[Dict]:
    """
    Search malware samples on MalwareBazaar (Abuse.ch).

    Returns hashes and metadata for samples associated with the name/family.
    No authentication required by default.
    """
    chave_cache = f"mwbazaar_{nome_malware.lower()}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    payload: Dict[str, str] = {
        "query": "get_taginfo",
        "tag": nome_malware,
        "limit": "10",
    }
    try:
        resp = requests.post(URL_MALWAREBAZAAR, data=payload, timeout=20)
        if resp and resp.status_code == 200:
            dados = resp.json()
            amostras = dados.get("data", []) or []
            if isinstance(amostras, list):
                resultado = [
                    {
                        "sha256": item.get("sha256_hash", ""),
                        "nome": item.get("file_name", ""),
                        "tipo": item.get("file_type", ""),
                        "tamanho": item.get("file_size", 0),
                        "data": item.get("first_seen", ""),
                        "tags": item.get("tags", []),
                    }
                    for item in amostras[:10]
                ]
                _cache_set(chave_cache, resultado)
                return resultado
    except Exception as e:
        logger.debug("MalwareBazaar error for %s: %s", nome_malware, e)
    return []


def _buscar_ransomware_live(nome_grupo: str) -> List[Dict]:
    """
    Search recent victims related to a ransomware group via Ransomware.live.

    Returns a list of victims (company, country, date). No authentication required.
    """
    chave_cache = f"ransom_live_{nome_grupo.lower()}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    try:
        resp = _req_get(URL_RANSOMWARE_LIVE, timeout=20)
        if resp:
            vitimas_todas = resp.json() if isinstance(resp.json(), list) else []
            nome_lower = nome_grupo.lower()
            vitimas_filtradas = [
                {
                    "empresa": v.get("victim", ""),
                    "pais": v.get("country", ""),
                    "data": v.get("published", ""),
                    "grupo": v.get("group", ""),
                    "website": v.get("website", ""),
                }
                for v in vitimas_todas
                if nome_lower in str(v.get("group", "")).lower()
            ][:10]
            _cache_set(chave_cache, vitimas_filtradas)
            return vitimas_filtradas
    except Exception as e:
        logger.debug("Ransomware.live error for %s: %s", nome_grupo, e)
    return []


def _buscar_misp_ator(nome_ator: str) -> List[Dict]:
    """
    Search events related to a threat actor in MISP (local instance).

    Requires MISP_URL and MISP_API_KEY to be configured. Returns a list of events.
    """
    if not MISP_URL or not MISP_API_KEY:
        return []
    chave_cache = f"misp_{nome_ator.lower()}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    headers = {
        "Authorization": MISP_API_KEY,
        "Accept": "application/json",
        "Content-Type": "application/json",
    }
    url = f"{MISP_URL.rstrip('/')}/events/restSearch"
    payload = {
        "value": nome_ator,
        "type": "text",
        "limit": 10,
        "returnFormat": "json",
    }
    try:
        resp = requests.post(url, json=payload, headers=headers, timeout=20, verify=False)
        if resp and resp.status_code == 200:
            dados = resp.json()
            eventos = dados.get("response", []) or []
            resultado = [
                {
                    "id": e.get("Event", {}).get("id", ""),
                    "info": e.get("Event", {}).get("info", ""),
                    "data": e.get("Event", {}).get("date", ""),
                    "tags": [
                        t.get("name", "")
                        for t in e.get("Event", {}).get("Tag", [])
                    ][:5],
                }
                for e in eventos[:10]
            ]
            _cache_set(chave_cache, resultado)
            return resultado
    except Exception as e:
        logger.debug("MISP error for %s: %s", nome_ator, e)
    return []


def _buscar_opencti_ator(nome_ator: str) -> List[Dict]:
    """
    Search a threat actor in OpenCTI via the GraphQL API.

    Requires OPENCTI_URL and OPENCTI_API_KEY to be configured.
    """
    if not OPENCTI_URL or not OPENCTI_API_KEY:
        return []
    chave_cache = f"opencti_{nome_ator.lower()}"
    cached = _cache_get(chave_cache)
    if cached is not None:
        return cached
    headers = {
        "Authorization": f"Bearer {OPENCTI_API_KEY}",
        "Content-Type": "application/json",
    }
    query = """
    query SearchThreatActor($nome: String!) {
      threatActors(filters: {key: "name", values: [$nome]}, first: 5) {
        edges {
          node {
            id
            name
            description
            aliases
            first_seen
            last_seen
            sophistication
            primary_motivation
          }
        }
      }
    }
    """
    url = f"{OPENCTI_URL.rstrip('/')}/graphql"
    try:
        resp = requests.post(
            url,
            json={"query": query, "variables": {"nome": nome_ator}},
            headers=headers,
            timeout=20,
        )
        if resp and resp.status_code == 200:
            dados = resp.json()
            edges = dados.get("data", {}).get("threatActors", {}).get("edges", [])
            resultado = [
                {
                    "id": e["node"].get("id", ""),
                    "nome": e["node"].get("name", ""),
                    "descricao": (e["node"].get("description") or "")[:300],
                    "aliases": e["node"].get("aliases", []),
                    "primeiro_visto": e["node"].get("first_seen", ""),
                    "ultimo_visto": e["node"].get("last_seen", ""),
                    "sofisticacao": e["node"].get("sophistication", ""),
                    "motivacao": e["node"].get("primary_motivation", ""),
                }
                for e in edges
            ]
            _cache_set(chave_cache, resultado)
            return resultado
    except Exception as e:
        logger.debug("OpenCTI error for %s: %s", nome_ator, e)
    return []


# ─── Malpedia enrichment ──────────────────────────────────────────────────────

# Base URL for the Malpedia public REST API
_MALPEDIA_BASE_URL = "https://malpedia.caad.fkie.fraunhofer.de"


class MalpediaClient:
    """
    Lightweight client for the Malpedia public REST API.

    Authentication: optional API token via 'Authorization: apitoken <TOKEN>'.
    When no token is provided the client falls back to anonymous access,
    which is rate-limited but fully functional for read-only endpoints.

    All responses are cached in the shared Chimera cache store so that
    repeated lookups within the same session do not trigger extra requests.

    Endpoints used
    --------------
    GET /api/get/actor/{actor_name}
        Full metadata for a threat actor (description, aliases, targets,
        motivations, references, associated families).

    GET /api/get/family/{family_name}
        Full metadata for a malware family (description, aliases, samples,
        external URLs, common name).

    GET /api/list/actors
        List of all known actor slugs — used for fuzzy name matching.

    GET /api/list/malware/families
        List of all known family slugs — used for fuzzy name matching.
    """

    # Fields extracted from the /api/get/actor response that are
    # surfaced in the enriched result dict under _malpedia_actor.
    _ACTOR_FIELDS = (
        "description", "aliases", "meta",
        "families", "cfr-target-category",
        "cfr-suspected-victims", "cfr-suspected-state-sponsors",
        "cfr-type-of-incident", "attribution-confidence",
        "references",
    )

    # Fields extracted from the /api/get/family response that are
    # surfaced in the enriched result dict under _malpedia_families.
    _FAMILY_FIELDS = (
        "description", "aliases", "common_name", "urls",
        "attribution", "notes",
    )

    def __init__(self, token: str = "", timeout: int = 20) -> None:
        """
        Initialise the client.

        Parameters
        ----------
        token   : Malpedia API token (empty string → anonymous access).
        timeout : HTTP request timeout in seconds (default: 20).
        """
        self._token = token.strip()
        self._timeout = timeout
        self._headers: Dict[str, str] = {"Accept": "application/json"}
        if self._token:
            self._headers["Authorization"] = f"apitoken {self._token}"
        logger.debug(
            "MalpediaClient initialised — authenticated=%s",
            bool(self._token),
        )

    # ── internal helpers ──────────────────────────────────────────────────────

    def _get(self, endpoint: str) -> Optional[Any]:
        """
        Perform a GET request against the Malpedia API.

        Handles rate-limiting (HTTP 429) with a single 15-second retry,
        timeouts, and generic HTTP errors.  Returns the parsed JSON body
        on success, or None on any failure.
        """
        url = f"{_MALPEDIA_BASE_URL}{endpoint}"
        cache_key = f"malpedia_{endpoint}"
        cached = _cache_get(cache_key)
        if cached is not None:
            logger.debug("Malpedia cache HIT: %s", endpoint)
            return cached

        logger.debug("Malpedia GET %s", url)
        try:
            resp = requests.get(
                url, headers=self._headers, timeout=self._timeout
            )
            if resp.status_code == 429:
                logger.warning(
                    "Malpedia rate-limit (429) on %s — retrying in 15s", url
                )
                time.sleep(15)
                resp = requests.get(
                    url, headers=self._headers, timeout=self._timeout
                )
            if resp.status_code == 404:
                logger.debug("Malpedia 404 for %s — entity not found", endpoint)
                return None
            resp.raise_for_status()
            data = resp.json()
            _cache_set(cache_key, data)
            return data
        except Timeout:
            logger.warning("Malpedia timeout on %s", url)
        except ConnectionError:
            logger.warning("Malpedia connection error on %s", url)
        except RequestException as exc:
            logger.warning("Malpedia request error on %s: %s", url, exc)
        except Exception as exc:
            logger.warning("Malpedia unexpected error on %s: %s", url, exc)
        return None

    # ── slug normalisation ────────────────────────────────────────────────────

    @staticmethod
    def _to_slug(name: str) -> str:
        """
        Convert a free-form actor/family name to a Malpedia-style slug.

        Malpedia slugs are lowercase with spaces replaced by underscores
        and most punctuation stripped (hyphens kept).
        Examples:
          "APT28"         → "apt28"
          "Lazarus Group" → "lazarus_group"
          "TEMP.Veles"    → "temp.veles"
        """
        slug = name.lower().strip()
        slug = re.sub(r"[^\w\.\-]", "_", slug)
        slug = re.sub(r"_+", "_", slug).strip("_")
        return slug

    # ── actor lookup ──────────────────────────────────────────────────────────

    def get_actor(self, actor_name: str) -> Dict:
        """
        Fetch enrichment data for a threat actor from Malpedia.

        Tries the direct slug first; if that returns nothing, fetches the
        full actor list and attempts a case-insensitive prefix/substring
        match against all known slugs.

        Returns a normalised dict with the following keys (all optional):
            description         : str  — actor description
            aliases             : List[str]
            target_categories   : List[str]  — targeted industry categories
            suspected_victims   : List[str]  — targeted countries/regions
            suspected_sponsors  : List[str]  — suspected sponsoring states
            incident_type       : str
            attribution_confidence: str
            families            : List[str]  — associated malware families
            references          : List[str]  — external reference URLs
            malpedia_url        : str  — direct link to the actor page
        """
        if not actor_name:
            return {}

        slug = self._to_slug(actor_name)
        data = self._get(f"/api/get/actor/{slug}")

        # Fallback: fuzzy match against the actor list
        if data is None:
            data = self._fuzzy_actor_lookup(actor_name, slug)

        if not data or not isinstance(data, dict):
            return {}

        return self._normalise_actor(data, slug)

    def _fuzzy_actor_lookup(self, actor_name: str, slug: str) -> Optional[Dict]:
        """
        Attempt a fuzzy match against all Malpedia actor slugs.

        Strategy (in order):
          1. Exact slug match.
          2. Slug is a prefix of a known actor slug.
          3. Slug appears as a substring of a known actor slug.
          4. The actor name (lowercased) appears as a substring of any slug.
        """
        all_actors = self._get("/api/list/actors")
        if not all_actors or not isinstance(all_actors, list):
            return None

        # Malpedia returns a list of dicts: [{"name": slug, ...}, ...]
        # or sometimes a plain list of slug strings.
        def _slug_of(entry: Any) -> str:
            if isinstance(entry, dict):
                return (entry.get("name") or entry.get("slug") or "").lower()
            return str(entry).lower()

        candidates = [_slug_of(e) for e in all_actors]
        name_lower = actor_name.lower()

        for match_slug in candidates:
            if match_slug == slug:
                return self._get(f"/api/get/actor/{match_slug}")
        for match_slug in candidates:
            if match_slug.startswith(slug) or slug.startswith(match_slug):
                return self._get(f"/api/get/actor/{match_slug}")
        for match_slug in candidates:
            if slug in match_slug or match_slug in slug:
                return self._get(f"/api/get/actor/{match_slug}")
        for match_slug in candidates:
            # e.g. actor_name="APT 28" → name_lower="apt 28" vs slug "apt28"
            if name_lower.replace(" ", "") in match_slug.replace("_", ""):
                return self._get(f"/api/get/actor/{match_slug}")
        return None

    @staticmethod
    def _normalise_actor(data: Dict, slug: str) -> Dict:
        """Map raw Malpedia actor response to the internal enrichment schema."""
        meta = data.get("meta", {}) or {}

        # Aliases: may be a list of strings or a list of dicts with a 'name' key
        raw_aliases = data.get("aliases") or []
        if isinstance(raw_aliases, list):
            aliases = [
                (a.get("name") if isinstance(a, dict) else str(a))
                for a in raw_aliases
                if a
            ]
        else:
            aliases = []

        # References: list of URL strings or dicts with 'url'
        raw_refs = data.get("references") or []
        if isinstance(raw_refs, list):
            refs = [
                (r.get("url") if isinstance(r, dict) else str(r))
                for r in raw_refs
                if r
            ]
        else:
            refs = []

        # Associated malware families
        families_raw = data.get("families") or []
        if isinstance(families_raw, list):
            families = [
                (f.get("name") if isinstance(f, dict) else str(f))
                for f in families_raw
                if f
            ]
        else:
            families = []

        return {
            "description":             (data.get("description") or "")[:600],
            "aliases":                 aliases[:10],
            "target_categories":       meta.get("cfr-target-category") or [],
            "suspected_victims":       meta.get("cfr-suspected-victims") or [],
            "suspected_sponsors":      meta.get("cfr-suspected-state-sponsors") or [],
            "incident_type":           meta.get("cfr-type-of-incident") or "",
            "attribution_confidence":  meta.get("attribution-confidence") or "",
            "families":                families[:15],
            "references":              refs[:10],
            "malpedia_url":            f"{_MALPEDIA_BASE_URL}/actors/{slug}",
        }

    # ── malware family lookup ─────────────────────────────────────────────────

    def get_family(self, family_name: str) -> Dict:
        """
        Fetch enrichment data for a malware family from Malpedia.

        Applies the same slug-then-fuzzy strategy as get_actor.

        Returns a normalised dict with the following keys (all optional):
            description  : str
            common_name  : str
            aliases      : List[str]
            urls         : List[str]  — external write-ups and reports
            attribution  : List[str]  — attributed threat actors
            notes        : str
            malpedia_url : str
        """
        if not family_name:
            return {}

        slug = self._to_slug(family_name)
        data = self._get(f"/api/get/family/{slug}")

        if data is None:
            data = self._fuzzy_family_lookup(family_name, slug)

        if not data or not isinstance(data, dict):
            return {}

        return self._normalise_family(data, slug)

    def _fuzzy_family_lookup(self, family_name: str, slug: str) -> Optional[Dict]:
        """Fuzzy slug match against the Malpedia malware family list."""
        all_families = self._get("/api/list/malware/families")
        if not all_families or not isinstance(all_families, list):
            return None

        def _slug_of(entry: Any) -> str:
            if isinstance(entry, dict):
                return (entry.get("name") or entry.get("slug") or "").lower()
            return str(entry).lower()

        candidates = [_slug_of(e) for e in all_families]
        name_lower = family_name.lower()

        for match_slug in candidates:
            if match_slug == slug:
                return self._get(f"/api/get/family/{match_slug}")
        for match_slug in candidates:
            if match_slug.startswith(slug) or slug.startswith(match_slug):
                return self._get(f"/api/get/family/{match_slug}")
        for match_slug in candidates:
            if slug in match_slug or match_slug in slug:
                return self._get(f"/api/get/family/{match_slug}")
        for match_slug in candidates:
            if name_lower.replace(" ", "") in match_slug.replace("_", ""):
                return self._get(f"/api/get/family/{match_slug}")
        return None

    @staticmethod
    def _normalise_family(data: Dict, slug: str) -> Dict:
        """Map raw Malpedia family response to the internal enrichment schema."""
        # URLs / external write-ups
        raw_urls = data.get("urls") or []
        if isinstance(raw_urls, list):
            urls = [
                (u.get("url") if isinstance(u, dict) else str(u))
                for u in raw_urls
                if u
            ]
        else:
            urls = []

        # Aliases
        raw_aliases = data.get("aliases") or []
        if isinstance(raw_aliases, list):
            aliases = [
                (a.get("name") if isinstance(a, dict) else str(a))
                for a in raw_aliases
                if a
            ]
        else:
            aliases = []

        # Attribution (list of actor names/slugs)
        raw_attr = data.get("attribution") or []
        if isinstance(raw_attr, list):
            attribution = [
                (a.get("actor") if isinstance(a, dict) else str(a))
                for a in raw_attr
                if a
            ]
        else:
            attribution = []

        return {
            "description":  (data.get("description") or "")[:500],
            "common_name":  data.get("common_name") or "",
            "aliases":      aliases[:8],
            "urls":         urls[:10],
            "attribution":  attribution[:8],
            "notes":        (data.get("notes") or "")[:300],
            "malpedia_url": f"{_MALPEDIA_BASE_URL}/families/{slug}",
        }


def _buscar_malpedia_ator(client: "MalpediaClient", nome_ator: str) -> Dict:
    """
    Wrapper that fetches Malpedia actor enrichment data for a given actor name.

    Returns the normalised enrichment dict (may be empty if not found or if
    MALPEDIA_ENRICHMENT_ENABLED is False).
    """
    if not MALPEDIA_ENRICHMENT_ENABLED:
        return {}
    try:
        return client.get_actor(nome_ator)
    except Exception as exc:
        logger.debug("Malpedia actor lookup failed for '%s': %s", nome_ator, exc)
        return {}


def _buscar_malpedia_families(client: "MalpediaClient",
                               family_names: List[str]) -> List[Dict]:
    """
    Fetch Malpedia enrichment data for each malware family in *family_names*.

    Returns a list of dicts (one per successfully matched family).
    Families that yield no Malpedia data are silently skipped.
    """
    if not MALPEDIA_ENRICHMENT_ENABLED:
        return []
    results: List[Dict] = []
    for name in family_names[:5]:  # limit to avoid overloading the API
        if not name:
            continue
        try:
            data = client.get_family(name)
            if data:
                data["_input_name"] = name
                results.append(data)
        except Exception as exc:
            logger.debug(
                "Malpedia family lookup failed for '%s': %s", name, exc
            )
    return results


