# ─── Mandatory top-level keys for the structured response schema ──────────────
# Used by _validar_schema_estruturado to detect and validate responses that
# follow the new fixed schema, distinguishing them from legacy free-text responses.
_STRUCTURED_SCHEMA_TOP_LEVEL_KEYS: Tuple[str, ...] = (
    "profile",
    "actor_details",
    "summary",
    "targeting_profile",
    "attack_chain_and_tactics",
    "associated_malware_and_tools",
    "mitre_attack_mapping",
    "mitigation_recommendations",
    "authoritative_references",
)


def _validar_schema_estruturado(data: Dict) -> Tuple[bool, List[str]]:
    """Validate that *data* contains every mandatory top-level key of the
    structured response schema.

    Returns
    -------
    Tuple[bool, List[str]]
        (True, []) when all required keys are present.
        (False, missing_keys) when one or more keys are absent.
    """
    missing = [k for k in _STRUCTURED_SCHEMA_TOP_LEVEL_KEYS if k not in data]
    return (len(missing) == 0), missing



# ─── ETDA schema field specification ─────────────────────────────────────────
# Canonical field lists used by _normalizar_resposta_llm_apt to enforce
# schema conformance on every LLM response without discarding content.
_ETDA_LIST_FIELDS: Tuple[str, ...] = (
    "country", "motivation", "observed-sectors",
    "observed-countries", "tools", "mitre-attack", "information",
)
_ETDA_OBJECT_LIST_FIELDS: Tuple[str, ...] = (
    "names", "operations", "counter-operations",
)


def _normalizar_resposta_llm_apt(raw: str, group_name: str) -> Optional[Dict]:
    """
    Parse and normalise a raw LLM response into a strict ETDA-compatible dict.

    Processing pipeline
    -------------------
    1. Strip optional markdown fences (```json...```) or prose surrounding
       an embedded JSON block.
    2. Attempt ``json.loads`` on the cleaned string.
    3. If step 2 fails, extract the first ``{...}`` block via regex and retry.
    4. Validate the parsed value is a ``dict``; return None otherwise.
    5. Check for the ``_llm_no_data`` sentinel; return None if present.
    6. Enforce types for every ETDA schema field:

       - **Plain list fields** (``_ETDA_LIST_FIELDS``): coerce bare strings to
         ``[string]``; other non-list scalars are wrapped in a list.
       - **Object-list fields** (``_ETDA_OBJECT_LIST_FIELDS``): coerce a lone
         ``dict`` to ``[dict]``; non-list/non-dict values become ``[]``.
         Per-item coercion rules:

         * ``names`` items that are plain strings become
           ``{"name": value, "name-giver": ""}``.
         * ``operations`` / ``counter-operations`` items that are plain
           strings become ``{"date": "", "activity": value}``.

    7. Guarantee ``actor`` is present (fallback: *group_name*).
    8. Auto-generate ``uuid`` (UUID v4) if absent or empty.
    9. Auto-fill ``last-card-change`` with today's ISO date if absent.

    Parameters
    ----------
    raw : str
        Raw text content returned by the LLM.
    group_name : str
        Original search term; used as fallback for the ``actor`` field.

    Returns
    -------
    Optional[Dict]
        Normalised ETDA-schema dict, or ``None`` if the response cannot be
        parsed or the LLM explicitly signalled it has no data.

    Examples
    --------
    Markdown fence stripping::

        raw = '```json\\n{"actor": "APT28", "country": "Russia"}\\n```'
        result = _normalizar_resposta_llm_apt(raw, "APT28")
        # -> {"actor": "APT28", "country": ["Russia"], "uuid": "...", ...}

    String-to-list coercion::

        raw = '{"actor": "Lazarus", "tools": "BlindingCan"}'
        result = _normalizar_resposta_llm_apt(raw, "Lazarus")
        # -> {"actor": "Lazarus", "tools": ["BlindingCan"], ...}

    Plain-string names coercion::

        raw = '{"actor": "Fancy Bear", "names": ["APT28", "Sofacy"]}'
        result = _normalizar_resposta_llm_apt(raw, "Fancy Bear")
        # -> {"names": [{"name": "APT28", "name-giver": ""},
        #               {"name": "Sofacy", "name-giver": ""}], ...}

    No-data sentinel::

        raw = '{"_llm_no_data": true}'
        result = _normalizar_resposta_llm_apt(raw, "Unknown Group")
        # -> None

    Embedded JSON in prose::

        raw = 'Sure! Here is the data: {"actor": "APT1"} Hope that helps!'
        result = _normalizar_resposta_llm_apt(raw, "APT1")
        # -> {"actor": "APT1", "uuid": "...", "last-card-change": "..."}
    """
    if not raw:
        return None

    # ── Step 1: strip markdown fences and surrounding prose ───────────────────
    cleaned = raw.strip()
    # Remove leading ```json / ``` fences
    cleaned = re.sub(r"^```[a-zA-Z]*\s*", "", cleaned)
    # Remove trailing ``` fences
    cleaned = re.sub(r"\s*```\s*$", "", cleaned.rstrip())
    cleaned = cleaned.strip()

    # ── Step 2: direct JSON parse ──────────────────────────────────────────────
    data: Optional[Dict] = None
    try:
        data = json.loads(cleaned)
    except json.JSONDecodeError:
        pass

    # ── Step 3: extract first {...} block if direct parse failed ──────────────
    if data is None:
        match = re.search(r"\{.*\}", cleaned, re.DOTALL)
        if match:
            try:
                data = json.loads(match.group(0))
            except json.JSONDecodeError as exc:
                logger.warning(
                    "LLM APT fallback: JSON parse error for group '%s': %s — raw: %.400s",
                    group_name, exc, raw,
                )
                return None
        else:
            logger.warning(
                "LLM APT fallback: no JSON object found in LLM response "
                "for group '%s' — raw: %.400s",
                group_name, raw,
            )
            return None

    # ── Step 4: must be a dict ─────────────────────────────────────────────────
    if not isinstance(data, dict):
        logger.warning(
            "LLM APT fallback: unexpected response type (%s) for group '%s'.",
            type(data).__name__, group_name,
        )
        return None

    # ── Step 4b: unwrap single-key root wrappers ──────────────────────────────
    # Some LLM models encapsulate the entire profile under a single root key
    # (e.g. {"actor_profile": {...}}, {"threat_actor": {...}}).  When the
    # parsed dict has exactly ONE key and its value is a dict, promote the
    # inner dict to root level so all downstream alias resolution can work.
    # We also unwrap well-known named wrappers even when other keys co-exist.
    _KNOWN_WRAPPERS = (
        "actor_profile", "threat_actor_profile", "threat_actor",
        "group_profile", "apt_profile", "profile_data",
        "intelligence_profile", "actor",
    )
    # Unwrap single-key wrapper first (model-agnostic)
    if len(data) == 1:
        sole_key, sole_val = next(iter(data.items()))
        if isinstance(sole_val, dict) and sole_key not in ("_llm_no_data",):
            logger.debug(
                "LLM APT fallback: unwrapping single-key root wrapper '%s' for '%s'.",
                sole_key, group_name,
            )
            data = sole_val
    # Then unwrap known named wrappers even when other top-level keys exist
    elif not any(
        k in data for k in ("actor", "country", "motivation", "description",
                             "actor_details", "general_information", "threat_actor",
                             "summary", "observed-sectors", "tools")
    ):
        for wrapper_key in _KNOWN_WRAPPERS:
            inner = data.get(wrapper_key)
            if isinstance(inner, dict) and inner:
                logger.debug(
                    "LLM APT fallback: unwrapping named root wrapper '%s' for '%s'.",
                    wrapper_key, group_name,
                )
                # Merge: inner dict takes precedence; keep any sibling top-level keys
                merged = dict(data)
                merged.pop(wrapper_key, None)
                merged.update(inner)
                data = merged
                break

    # ── Step 5: _llm_no_data sentinel ─────────────────────────────────────────
    if data.get("_llm_no_data"):
        logger.info(
            "LLM APT fallback: agent reported no data for group '%s'.", group_name
        )
        return None

    # ── Step 6a: enforce plain list fields ────────────────────────────────────
    for field in _ETDA_LIST_FIELDS:
        val = data.get(field)
        if val is None:
            continue
        if isinstance(val, str):
            data[field] = [val] if val.strip() else []
        elif not isinstance(val, list):
            data[field] = [str(val)]
        # Already a list → keep as-is

    # ── Step 6b: enforce object-list fields ───────────────────────────────────
    for field in _ETDA_OBJECT_LIST_FIELDS:
        val = data.get(field)
        if val is None:
            continue
        if isinstance(val, dict):
            val = [val]
        elif not isinstance(val, list):
            val = []
        coerced: List[Dict] = []
        for item in val:
            if isinstance(item, str) and item.strip():
                if field == "names":
                    coerced.append({"name": item, "name-giver": ""})
                else:  # operations / counter-operations
                    coerced.append({"date": "", "activity": item})
            elif isinstance(item, dict):
                coerced.append(item)
            # Drop None / empty strings / other non-dict non-str items
        data[field] = coerced

    # ── Step 7: guarantee actor field ─────────────────────────────────────────
    if not data.get("actor"):
        data["actor"] = group_name

    # ── Step 8: auto-generate uuid (v4) if missing ────────────────────────────
    if not data.get("uuid"):
        data["uuid"] = str(_uuid_mod.uuid4())

    # ── Step 9: auto-fill last-card-change with today's date ──────────────────
    if not data.get("last-card-change"):
        data["last-card-change"] = datetime.date.today().isoformat()

    return data


def _chamar_llm_raw(system_prompt: str, user_prompt: str) -> str:
    """
    Dispatch a single LLM completion request using the globally configured provider.

    Mirrors the retry/back-off logic already used by QueryGeneratorLLM._call_llm
    but is defined here as a module-level helper so it can be used by
    _buscar_via_agente_llm without requiring a full QueryGeneratorLLM instance.

    Returns the response text, or an empty string on failure.
    """
    for attempt in range(1, LLM_MAX_RETRIES + 1):
        try:
            provider = LLM_PROVIDER.lower()

            if provider == "openai":
                url = (LLM_BASE_URL or "https://api.openai.com") + "/v1/chat/completions"
                payload = {
                    "model": LLM_MODEL,
                    "messages": [
                        {"role": "system", "content": system_prompt},
                        {"role": "user",   "content": user_prompt},
                    ],
                    "temperature": 0.0,
                    "max_tokens":  4096,
                    # Enforce JSON-only output at the API level for models that
                    # support it (gpt-4o, gpt-4-turbo, gpt-3.5-turbo-1106+).
                    # The system prompt already instructs JSON-only output; this
                    # provides a second enforcement layer.
                    "response_format": {"type": "json_object"},
                }
                headers = {
                    "Authorization": f"Bearer {LLM_API_KEY}",
                    "Content-Type":  "application/json",
                }
                resp = requests.post(url, json=payload, headers=headers, timeout=LLM_TIMEOUT)
                resp.raise_for_status()
                return resp.json()["choices"][0]["message"]["content"].strip()

            if provider == "anthropic":
                url = (LLM_BASE_URL or "https://api.anthropic.com") + "/v1/messages"
                payload = {
                    "model":      LLM_MODEL,
                    "max_tokens": 4096,
                    "system":     system_prompt,
                    "messages": [{"role": "user", "content": user_prompt}],
                }
                headers = {
                    "x-api-key":         LLM_API_KEY,
                    "anthropic-version": "2023-06-01",
                    "Content-Type":      "application/json",
                }
                resp = requests.post(url, json=payload, headers=headers, timeout=LLM_TIMEOUT)
                resp.raise_for_status()
                return resp.json()["content"][0]["text"].strip()

            if provider == "google":
                model_id = LLM_MODEL or "gemini-1.5-pro"
                url = (
                    (LLM_BASE_URL or "https://generativelanguage.googleapis.com")
                    + f"/v1beta/models/{model_id}:generateContent?key={LLM_API_KEY}"
                )
                combined = f"{system_prompt}\n\n{user_prompt}"
                payload = {
                    "contents": [{"parts": [{"text": combined}]}],
                    "generationConfig": {
                        "temperature":    0.0,
                        "maxOutputTokens": 4096,
                        # Enforce JSON MIME type for Gemini models that support it
                        "responseMimeType": "application/json",
                    },
                }
                resp = requests.post(url, json=payload, timeout=LLM_TIMEOUT)
                resp.raise_for_status()
                return resp.json()["candidates"][0]["content"]["parts"][0]["text"].strip()

            # Ollama / Azure OpenAI / IBM ICA / unknown OpenAI-compatible endpoint
            if provider == "ollama":
                base = LLM_BASE_URL or "http://localhost:11434"
                url = base.rstrip("/") + "/api/chat"
                payload = {
                    "model": LLM_MODEL,
                    "messages": [
                        {"role": "system", "content": system_prompt},
                        {"role": "user",   "content": user_prompt},
                    ],
                    "stream": False,
                    # Ollama native JSON mode: constrains generation to valid JSON
                    "format":  "json",
                    "options": {"temperature": 0.0},
                }
                resp = requests.post(url, json=payload, timeout=LLM_TIMEOUT)
                resp.raise_for_status()
                return resp.json().get("message", {}).get("content", "").strip()

            if provider == "ibm_ica":
                # IBM ICA /agents/chat/completions endpoint
                # ─────────────────────────────────────────────────────────────
                # Key differences from the standard OpenAI schema:
                #   1. LLM_BASE_URL must be the FULL endpoint URL, including the
                #      /chat/completions path, e.g.:
                #      https://<host>/ica/v1/agents/chat/completions
                #      The path is NOT appended here — set it explicitly in .env.
                #   2. The `model` field IS included — the IBM ICA chat/completions
                #      endpoint requires it to select the deployed model.
                #   3. `temperature` and `max_tokens` are not accepted and must
                #      be omitted to avoid a 400 Bad Request.
                #   4. Only `Authorization: Bearer <key>` is sent — the
                #      `api-key` header used by Azure is NOT sent.
                #   5. `stream: false` is required to receive a complete response.
                # ─────────────────────────────────────────────────────────────
                if not LLM_BASE_URL:
                    logger.error(
                        "LLM APT fallback: LLM_BASE_URL must be set to the full IBM ICA "
                        "endpoint URL when using provider 'ibm_ica', e.g. "
                        "https://<host>/ica/v1/agents/chat/completions"
                    )
                    return ""
                url = LLM_BASE_URL  # full endpoint URL — do not append any path
                payload = {
                    "model": LLM_MODEL,
                    "messages": [
                        {"role": "user", "content": user_prompt},
                    ],
                    "stream": False,
                    # 'temperature' and 'max_tokens' are intentionally omitted —
                    # the IBM ICA agents endpoint rejects these fields with HTTP 400.
                }
                headers = {
                    "accept":        "application/json",
                    "Authorization": f"Bearer {LLM_API_KEY}",
                    "Content-Type":  "application/json",
                }
                resp = requests.post(url, json=payload, headers=headers, timeout=LLM_TIMEOUT)
                resp.raise_for_status()
                return resp.json()["choices"][0]["message"]["content"].strip()

            # azure_openai or unknown provider — OpenAI-compatible REST
            # LLM_BASE_URL is used as the base (without path); the versioned
            # path /chat/completions?api-version=2024-02-01 is appended here.
            base = LLM_BASE_URL or "https://api.openai.com"
            url = base.rstrip("/") + "/chat/completions?api-version=2024-02-01"
            payload = {
                "messages": [
                    {"role": "system", "content": system_prompt},
                    {"role": "user",   "content": user_prompt},
                ],
                "temperature": 0.0,
                "max_tokens":  4096,
                # Enforce JSON-only output for Azure OpenAI (2024-02-01+) and
                # other OpenAI-compatible endpoints that honour response_format.
                "response_format": {"type": "json_object"},
            }
            headers = {
                "api-key":       LLM_API_KEY,
                "Authorization": f"Bearer {LLM_API_KEY}",
                "Content-Type":  "application/json",
            }
            resp = requests.post(url, json=payload, headers=headers, timeout=LLM_TIMEOUT)
            resp.raise_for_status()
            return resp.json()["choices"][0]["message"]["content"].strip()

        except Exception as exc:
            msg = str(exc)
            is_rate_limit = "429" in msg or "rate" in msg.lower() or "quota" in msg.lower()
            if is_rate_limit and attempt < LLM_MAX_RETRIES:
                wait_secs = 2 ** attempt
                logger.warning(
                    "LLM APT fallback — rate-limit hit (attempt %d/%d), waiting %ds: %s",
                    attempt, LLM_MAX_RETRIES, wait_secs, msg[:200],
                )
                time.sleep(wait_secs)
                continue
            logger.error(
                "LLM APT fallback — call failed (attempt %d/%d): %s",
                attempt, LLM_MAX_RETRIES, msg[:400],
            )
            if attempt == LLM_MAX_RETRIES:
                return ""
    return ""


def _buscar_via_agente_llm(group_name: str) -> Optional[Dict]:
    """
    Query the LLM agent for threat group intelligence when ETDA returns no results.

    This function is the LLM fallback for the FindAPTGroups module.  It is
    invoked automatically by executar_find_apt_groups when _buscar_grupos
    returns an empty list for a given search term.

    Query strategy (two-phase)
    --------------------------
    Phase 1 — Structured schema:
        Uses ``_LLM_APT_STRUCTURED_SYSTEM_PROMPT``, which instructs the LLM to
        return a fixed, pre-determined JSON schema with all nine mandatory
        top-level keys.  The response is validated with
        ``_validar_schema_estruturado``; if all keys are present the result is
        returned directly (the ``_normalizar_resultado_grupo`` normaliser maps
        every field of this schema into canonical fields).

    Phase 2 — Legacy free-text fallback (last resort):
        If phase 1 produces an invalid or incomplete structured response the
        function falls back to ``_LLM_APT_FALLBACK_SYSTEM_PROMPT`` — the
        original ETDA-compatible schema — and processes the response through
        ``_normalizar_resposta_llm_apt`` as before.  This path is preserved for
        full backwards compatibility.

    An additional sentinel field ``_llm_source`` is injected into the returned
    dict so callers can distinguish LLM-sourced records from ETDA records.

    Parameters
    ----------
    group_name : str
        The threat/eCrime group name as typed by the user or provided via
        batch args.  Used verbatim as the LLM query term.

    Returns
    -------
    Optional[Dict]
        A single ETDA-schema-compatible dict if the LLM found data, or
        None if:
          - LLM_APT_FALLBACK_ENABLED is False.
          - LLM_API_KEY is missing (except for Ollama).
          - The LLM explicitly signals no data (``_llm_no_data`` sentinel).
          - Both phases fail to produce a parseable JSON response.
    """
    # Guard: fallback must be explicitly enabled
    if not LLM_APT_FALLBACK_ENABLED:
        return None

    # Guard: API key required for non-local providers
    if not LLM_API_KEY and LLM_PROVIDER.lower() not in ("ollama",):
        logger.warning(
            "LLM APT fallback: LLM_API_KEY is not set for provider '%s' — skipping.",
            LLM_PROVIDER,
        )
        return None

    logger.info(
        "LLM APT fallback ACTIVATED for group '%s' (provider=%s model=%s)",
        group_name, LLM_PROVIDER, LLM_MODEL,
    )

    # ── Phase 1: structured fixed-schema query ────────────────────────────────
    # The user prompt reinforces the actor name and the JSON-only constraint at
    # the user-turn level; the system prompt carries the mandatory schema.
    structured_user_prompt = (
        f"Produce a complete threat intelligence profile for the threat/eCrime group "
        f'named "{group_name}" following EXACTLY the JSON schema defined in the '
        f"system prompt. Draw ONLY from publicly known, authoritative sources "
        f"(CrowdStrike, Mandiant/Google, Microsoft, Palo Alto Unit 42, Recorded Future, "
        f"Kaspersky, Symantec, ESET, CISA, NSA, NCSC, FBI, MITRE ATT&CK). "
        f"Return ONLY a single valid JSON object — no markdown, no prose, no text "
        f"outside the JSON. Every top-level key is mandatory."
    )

    raw_structured = _chamar_llm_raw(
        _LLM_APT_STRUCTURED_SYSTEM_PROMPT, structured_user_prompt
    )

    if raw_structured:
        # Quick raw-JSON check for the _llm_no_data sentinel BEFORE full
        # normalisation — _normalizar_resposta_llm_apt returns None for the
        # sentinel, making it indistinguishable from a parse error.  Checking
        # here lets us avoid Phase 2 when the LLM explicitly has no data.
        try:
            _quick = json.loads(
                re.sub(r"^```[a-zA-Z]*\s*", "", raw_structured.strip())
                .rstrip().rstrip("`").strip()
            )
            if isinstance(_quick, dict) and _quick.get("_llm_no_data"):
                logger.info(
                    "LLM APT fallback: agent reported no data for group '%s' "
                    "(structured schema path).",
                    group_name,
                )
                return None
        except (json.JSONDecodeError, Exception):
            pass  # full normaliser will handle errors

        # Attempt to parse and normalise the structured response
        structured_data = _normalizar_resposta_llm_apt(raw_structured, group_name)
        if structured_data is not None:
            valid, missing_keys = _validar_schema_estruturado(structured_data)
            if valid:
                logger.info(
                    "LLM APT fallback (structured): all schema keys present for '%s'.",
                    group_name,
                )
                structured_data["_llm_source"] = True
                structured_data["_llm_model"]  = LLM_MODEL
                return structured_data
            else:
                logger.warning(
                    "LLM APT fallback (structured): missing keys %s for group '%s' "
                    "— falling back to legacy schema.",
                    missing_keys, group_name,
                )
    else:
        logger.warning(
            "LLM APT fallback (structured): empty response for '%s' "
            "— falling back to legacy schema.",
            group_name,
        )

    # ── Phase 2: legacy free-text / ETDA-compatible schema (last resort) ─────
    # User prompt: explicitly request strict JSON with the full ETDA schema.
    # The system prompt already carries the schema; this message reinforces the
    # actor name and the JSON-only constraint at the user-turn level.
    legacy_user_prompt = (
        f"Provide a complete threat intelligence profile for the threat/eCrime group "
        f'named "{group_name}". '
        f"Draw from authoritative public sources such as vendor blogs "
        f"(CrowdStrike, Mandiant/Google, Microsoft, Palo Alto Unit 42, Recorded Future, "
        f"Kaspersky, Symantec, ESET), government advisories (CISA, NSA, NCSC, FBI), "
        f"and the MITRE ATT&CK knowledge base. "
        f"Return ONLY a single valid JSON object following the schema in the system "
        f"prompt — no markdown, no prose, no text outside the JSON."
    )

    raw_legacy = _chamar_llm_raw(_LLM_APT_FALLBACK_SYSTEM_PROMPT, legacy_user_prompt)

    if not raw_legacy:
        logger.warning(
            "LLM APT fallback: empty response on both attempts for group '%s'.",
            group_name,
        )
        return None

    # Delegate all parsing, validation and normalisation to the dedicated helper.
    # _normalizar_resposta_llm_apt handles: markdown fence stripping, JSON extraction
    # from prose, type coercion for all ETDA fields, uuid generation, and
    # last-card-change back-fill.
    data = _normalizar_resposta_llm_apt(raw_legacy, group_name)
    if data is None:
        return None

    # Inject source markers so downstream consumers can distinguish LLM-sourced
    # records from ETDA catalogue records.
    data["_llm_source"] = True
    data["_llm_model"]  = LLM_MODEL

    logger.info(
        "LLM APT fallback (legacy): data retrieved for group '%s' via %s/%s.",
        group_name, LLM_PROVIDER, LLM_MODEL,
    )
    return data


# ─── Terminal display ─────────────────────────────────────────────────────────

def _exibir_resumo_rapido(resultados: List[Dict]) -> None:
    """Display a quick summary in the terminal: total groups and top 5."""
    total = len(resultados)
    print(Fore.LIGHTCYAN_EX + "\n" + "="*60)
    print(f"  Groups found: {Fore.YELLOW}{total}{Fore.LIGHTCYAN_EX}")
    print("="*60 + Style.RESET_ALL)
    if total > 0:
        print(Fore.GREEN + "  Top 5 groups:")
        for i, r in enumerate(resultados[:5], 1):
            ator = r.get("actor", "Unknown")
            pais = ", ".join(r.get("country", ["?"])) if isinstance(r.get("country"), list) else r.get("country", "?")
            print(f"    {i}. {ator}  ({pais})")
        print(Style.RESET_ALL)


def _exibir_resultados_paginados(resultados: List[Dict], modo_resumido: bool,
                                 por_pagina: int = 5) -> None:
    """Display results with pagination."""
    total = len(resultados)
    paginas = max(1, (total + por_pagina - 1) // por_pagina)
    pagina = 1
    chaves_resumo = ["actor", "names", "country", "description",
                     "observed-sectors", "observed-countries", "tools", "mitre-attack"]
    while True:
        inicio = (pagina - 1) * por_pagina
        fim = inicio + por_pagina
        print(f"\n--- Page {pagina}/{paginas} ---\n")
        for resultado in resultados[inicio:fim]:
            if modo_resumido:
                dado = {k: resultado.get(k, "N/A") for k in chaves_resumo}
            else:
                dado = resultado
            print(json.dumps(dado, indent=2, ensure_ascii=False))
        if pagina < paginas:
            resp = input("\nPress Enter for next page | 'q' to quit: ").strip().lower()
            if resp == "q":
                break
            pagina += 1
        else:
            break


# ─── Save output files ────────────────────────────────────────────────────────

def _salvar_lista(caminho: str, itens: List[str]) -> None:
    """Save a list of strings to a text file."""
    with open(caminho, "w", encoding="utf-8") as f:
        for item in itens:
            f.write(f"{item}\n")
    logger.info("File saved: %s", caminho)
    print(f"  -> Data saved at: {caminho}")


