# ─── Module main function ─────────────────────────────────────────────────────

def executar_find_apt_groups(args_batch: Optional[Dict] = None) -> Optional[Dict]:
    """
    Execute the FindAPTGroups module.
    Returns a dict with group IDs and timestamp for chaining.
    """
    # Module banner
    print(Fore.LIGHTRED_EX + """
+--------------------------------------------+
|         FindAPTGroups v2.0                 |
|   Identification & Filtering of Threat     |
|   Actors by Sector / Country / Tool        |
+--------------------------------------------+""" + Style.RESET_ALL)

    # Download/load catalogue
    print(Fore.CYAN + "\n[*] Fetching Threat Actor catalogue (ETDA)..." + Style.RESET_ALL)
    _baixar_json_grupos(URL_ETDA)
    dados_json = _carregar_json_grupos()
    if not dados_json:
        print(Fore.RED + "ERROR: Could not load the group catalogue." + Style.RESET_ALL)
