    # ── Enrichment via OTX AlienVault ────────────────────────────────────────
    if OTX_API_KEY:
        print(Fore.CYAN + "\n[*] Enriching via OTX AlienVault..." + Style.RESET_ALL)
        fontes_consultadas.append("OTX AlienVault API")
