            actor_name = r.get("actor", "")
            iocs_otx: List[Dict] = []
            pulse_count = 0
            if actor_name:
                otx_data = _buscar_otx(actor_name)
                # _buscar_otx returns {} when the key is missing, a network
                # error occurs, or the actor was not found — no data is lost.
                pulses = otx_data.get("results", [])
                pulse_count = len(pulses)
                for pulse in pulses:
                    # The 'indicators' field is populated by _buscar_otx via
                    # the /api/v1/pulses/{id}/indicators endpoint (not by the search).
                    pulse_name = pulse.get("name", "")
                    for indicator in pulse.get("indicators", []):
                        if not isinstance(indicator, dict):
                            continue
                        value = indicator.get("indicator", "").strip()
                        ioc_type  = indicator.get("type", "").strip()
                        if not value:
                            continue
                        iocs_otx.append({
                            "value": value,
                            "type":  ioc_type,
                            "pulse": pulse_name,
                            "date":  indicator.get("created", ""),
                        })
