    # ── ThreatFox enrichment ─────────────────────────────────────────────────
    print(Fore.CYAN + "[*] Querying ThreatFox (Abuse.ch)..." + Style.RESET_ALL)
    fontes_consultadas.append("ThreatFox (Abuse.ch)")
