def executar_find_apt_attck(ids_grupos: Optional[List[str]] = None,
                             caminho_ids: Optional[str] = None,
                             args_batch: Optional[Dict] = None) -> Optional[Dict]:
    """
    Execute the FindAPTAttck module.
    Accepts a list of IDs, a file path, or interactive mode.
    Returns a dict with techniques and the generated file path for chaining.
    """
    print(Fore.LIGHTCYAN_EX + """
+--------------------------------------------+
|         FindAPTAttck v2.0                  |
|   Correlation with MITRE ATT&CK Framework  |
+--------------------------------------------+""" + Style.RESET_ALL)

    # Determine ATT&CK domain
    dominio_chave = "e"
    if args_batch:
        dominio_chave = args_batch.get("domain", "e")
    else:
        print("\nATT&CK domain:")
        print("  e — Enterprise (default)")
        print("  m — Mobile")
        print("  i — ICS")
        dom_inp = input(Fore.LIGHTGREEN_EX + "Domain [e]: " + Style.RESET_ALL).strip().lower() or "e"
        if dom_inp in DOMINIOS_ATTCK:
            dominio_chave = dom_inp

    dominio = DOMINIOS_ATTCK[dominio_chave]
    store = _obter_store_attck(dominio)
    if not store:
        print(Fore.RED + "ERROR: Could not load MITRE ATT&CK data." + Style.RESET_ALL)
        return None

    # Determine groups to process
    grupos_para_processar = []

    if args_batch and args_batch.get("actor"):
        # Batch mode: search by name
        res = _buscar_grupo_por_nome(store, args_batch["actor"])
        if res:
            grupos_para_processar = [res[0]]
    elif caminho_ids and os.path.isfile(caminho_ids):
        # Load from file
        print(Fore.CYAN + f"[*] Loading IDs from file: {caminho_ids}" + Style.RESET_ALL)
        with open(caminho_ids, "r", encoding="utf-8") as f:
            ids_arquivo = [l.strip() for l in f if l.strip()]
        for gid in ids_arquivo:
            if PADRAO_ATTCK_ID.match(gid):
                res = _buscar_grupo_por_id(store, gid)
            else:
                res = _buscar_grupo_por_nome(store, gid)
            if res:
                grupos_para_processar.append(res[0])
    elif ids_grupos:
        for gid in ids_grupos:
            res = _buscar_grupo_por_id(store, gid)
            if res:
                grupos_para_processar.append(res[0])
    else:
        # Interactive mode
        print(Fore.LIGHTGREEN_EX)
        tipo_busca = input("Search by (N)ame or ATT&CK (ID)? ").strip().upper()
        valor = input("Search value: ").strip()
        print(Style.RESET_ALL)
        if tipo_busca == "N":
            res = _buscar_grupo_por_nome(store, valor)
        else:
            res = _buscar_grupo_por_id(store, valor)

        if not res:
            print(Fore.RED + f"No group found for '{valor}'." + Style.RESET_ALL)
            return None

        if len(res) == 1:
            grupos_para_processar = [res[0]]
        else:
            print(f"\n{len(res)} groups found:")
            for i, g in enumerate(res, 1):
                print(f"  {i}. {g.get('name')}")
            escolha = input("Choose by number (or 'A' for all): ").strip().upper()
            if escolha == "A":
                grupos_para_processar = res
            else:
                try:
                    grupos_para_processar = [res[int(escolha) - 1]]
                except (ValueError, IndexError):
                    print(Fore.RED + "Invalid choice." + Style.RESET_ALL)
                    return None

    if not grupos_para_processar:
        print(Fore.RED + "No groups to process." + Style.RESET_ALL)
        return None

    resultado_final = {"grupos": [], "arquivos_tecnicas": [], "html_paths": []}

    for grupo in grupos_para_processar:
        print(Fore.GREEN + f"\n[*] Processing: {grupo.get('name')} ({grupo.get('external_references', [{}])[0].get('external_id', '?')})" + Style.RESET_ALL)

        # Display basic information
        print(f"  Aliases: {Fore.LIGHTMAGENTA_EX}{', '.join(grupo.get('aliases', ['N/A']))}{Style.RESET_ALL}")

        # Processar técnicas e táticas do grupo via STIX/ATT&CK
        dados = _processar_tecnicas_grupo(store, grupo)

        # ── VirusTotal enrichment for tools/malware ──────────────────────
        if VT_API_KEY and dados["ferramentas"]:
            print(Fore.CYAN + "  [*] Enriching tools via VirusTotal..." + Style.RESET_ALL)
            for ferr in dados["ferramentas"]:
                vt_dados = _buscar_virustotal_malware(ferr["nome"])
                items_vt = vt_dados.get("data", [])
                if items_vt and isinstance(items_vt, list):
                    primeiro = items_vt[0]
                    attrs = primeiro.get("attributes", {})
                    stats = attrs.get("last_analysis_stats", {})
                    ferr["_vt"] = {
                        "deteccoes": stats.get("malicious", 0),
                        "total": sum(stats.values()) if stats else 0,
                        "label": attrs.get("meaningful_name", ""),
                        "tags": attrs.get("tags", [])[:5],
                        "tipo_arquivo": attrs.get("type_description", ""),
                    }

        # Display MITRE ATT&CK ASCII matrix
        _exibir_matriz_ascii(dados["taticas"])

        # Display associated tactics
        print(Fore.CYAN + "\n  Associated tactics:" + Style.RESET_ALL)
        for tat, tid in sorted(dados["taticas"].items()):
            print(f"    -> {tat.replace('-',' ').title()} ({tid})")

        # Display techniques hierarchically
        print(Fore.CYAN + f"\n  Techniques ({len(dados['tecnicas'])} found):" + Style.RESET_ALL)
        for t in dados["tecnicas"][:20]:  # limit terminal output
            subs = f"  [{', '.join(t['subtecnicas'][:3])}]" if t["subtecnicas"] else ""
            print(f"    {Fore.YELLOW}{t['id']}{Style.RESET_ALL} — {t['nome']}{Fore.LIGHTBLACK_EX}{subs}{Style.RESET_ALL}")

        # Display tools/malware
        if dados["ferramentas"]:
            print(Fore.CYAN + f"\n  Tools/Malware ({len(dados['ferramentas'])}):" + Style.RESET_ALL)
            for ferr in dados["ferramentas"][:15]:
                vt_info = ferr.get("_vt", {})
                vt_str = f"  [VT: {vt_info['deteccoes']}/{vt_info['total']}]" if vt_info else ""
                print(f"    * {ferr['nome']} [{ferr['tipo']}]{Fore.RED}{vt_str}{Style.RESET_ALL}")

        # Top 10
        print(Fore.CYAN + "\n  Top 10 Techniques:" + Style.RESET_ALL)
        for prefixo, count in dados["top10"]:
            barra = "█" * min(20, count * 2)
            print(f"    {prefixo}  {Fore.GREEN}{barra}{Style.RESET_ALL}  ({count}x)")

        # Calculate score
        score = _calcular_score_hunting(dados["tecnicas"])
        class_sc, _ = _classificar_score(score)
        print(Fore.YELLOW + f"\n  Hunting Priority Score: {score}/100 — {class_sc}" + Style.RESET_ALL)

        # Save techniques to file
        arquivo_tec = _salvar_tecnicas_arquivo(grupo, dados["top10"], dados)

        # Generate HTML report
        caminho_html = _gerar_html_attck(grupo, dados, score)

        resultado_final["grupos"].append({
            "grupo": grupo.get("name"),
            "dados": dados,
            "score": score,
        })
        if arquivo_tec:
            resultado_final["arquivos_tecnicas"].append(arquivo_tec)
        if caminho_html:
            resultado_final["html_paths"].append(caminho_html)

    registrar_historico("FindAPTAttck", {
        "grupos": [g["grupo"] for g in resultado_final["grupos"]],
        "dominio": dominio,
    })

    return resultado_final


# ═══════════════════════════════════════════════════════════════════════════════
# MODULE 3 — FindSigRules
# ═══════════════════════════════════════════════════════════════════════════════

def atualizar_regras_sigma() -> bool:
    """
    Update the local Sigma rules repository before execution.

    Strategy:
      1. Resolve the repository root: either the 'sigma/' subdirectory next to
         this script, or the parent of the configured rules path.
      2. If the directory does not exist, perform an initial clone.
      3. If the directory exists and is a Git repo, run 'git pull'.
      4. On any failure (no network, permission error, git not found, etc.) a
         warning is printed and execution continues normally with the existing
         local rules — the script is never interrupted.

    Returns:
        True  — repository updated or already up to date.
        False — update skipped or failed (non-fatal).
    """
    # ── Determine the repository root directory ──────────────────────────────
    # Prefer the 'sigma/' subdirectory that ships alongside this script.
    raiz_script = Path(__file__).parent
    repo_dir = raiz_script / "sigma"

    # If that does not exist, try to infer the root from the configured rules
    # path (strip the trailing 'rules' segment when present).
    if not repo_dir.exists():
        caminho_regras = _carregar_config_sigma()
        p = Path(caminho_regras)
        if p.name == "rules" and (p.parent / ".git").is_dir():
            repo_dir = p.parent
        elif (p / ".git").is_dir():
            repo_dir = p

    url_sigma = "https://github.com/SigmaHQ/sigma.git"

    # ── Try to read the actual remote URL from the local repo ─────────────────
    if repo_dir.exists() and (repo_dir / ".git").is_dir():
        try:
            res = subprocess.run(
                ["git", "-C", str(repo_dir), "remote", "get-url", "origin"],
                capture_output=True, text=True, timeout=10,
            )
            if res.returncode == 0 and res.stdout.strip():
                url_sigma = res.stdout.strip()
        except Exception:
            pass  # keep the default URL

    # ── Case 1: repository does not exist locally → initial clone ─────────────
    if not repo_dir.exists():
        print(
            Fore.CYAN + f"\n[*] Sigma rules repository not found at '{repo_dir}'."
            + Style.RESET_ALL
        )
        print(Fore.CYAN + f"    Performing initial clone from {url_sigma} ..." + Style.RESET_ALL)
        logger.info("Cloning Sigma rules repository from %s into %s", url_sigma, repo_dir)
        try:
            resultado = subprocess.run(
                ["git", "clone", "--depth", "1", url_sigma, str(repo_dir)],
                capture_output=True, text=True, timeout=300,
            )
            if resultado.returncode == 0:
                print(Fore.GREEN + "    [OK] Sigma rules cloned successfully." + Style.RESET_ALL)
                logger.info("Sigma rules cloned successfully into %s", repo_dir)
                return True
            else:
                stderr = resultado.stderr.strip()
                print(
                    Fore.YELLOW
                    + f"    [!] Clone failed: {stderr[:200] if stderr else 'unknown error'}"
                    + Style.RESET_ALL
                )
                logger.warning("Sigma clone failed: %s", stderr)
                return False
        except FileNotFoundError:
            print(
                Fore.YELLOW
                + "    [!] 'git' not found in PATH. Skipping Sigma update."
                + Style.RESET_ALL
            )
            logger.warning("git executable not found; Sigma clone skipped.")
            return False
        except subprocess.TimeoutExpired:
            print(
                Fore.YELLOW
                + "    [!] Clone timed out. Continuing with existing rules."
                + Style.RESET_ALL
            )
            logger.warning("Sigma clone timed out.")
            return False
        except Exception as exc:
            print(Fore.YELLOW + f"    [!] Unexpected error during clone: {exc}" + Style.RESET_ALL)
            logger.warning("Unexpected error during Sigma clone: %s", exc)
            return False

    # ── Case 2: directory exists but is not a Git repository ──────────────────
    if not (repo_dir / ".git").is_dir():
        print(
            Fore.YELLOW
            + f"\n[!] '{repo_dir}' exists but is not a Git repository. "
            + "Skipping automatic update."
            + Style.RESET_ALL
        )
        logger.warning(
            "Sigma rules path '%s' exists but has no .git — skipping update.", repo_dir
        )
        return False

    # ── Case 3: valid Git repository → git pull ───────────────────────────────
    print(Fore.CYAN + "\n[*] Updating Sigma rules repository (git pull) ..." + Style.RESET_ALL)
    logger.info("Running 'git pull' in Sigma repository at %s", repo_dir)
    try:
        resultado = subprocess.run(
            ["git", "-C", str(repo_dir), "pull", "--ff-only", "--quiet"],
            capture_output=True, text=True, timeout=120,
        )
        if resultado.returncode == 0:
            saida = resultado.stdout.strip()
            if saida and saida.lower() != "already up to date.":
                print(Fore.GREEN + f"    [OK] {saida}" + Style.RESET_ALL)
            else:
                print(Fore.GREEN + "    [OK] Sigma rules already up to date." + Style.RESET_ALL)
            logger.info("Sigma rules updated successfully.")
            return True
        else:
            stderr = resultado.stderr.strip()
            print(
                Fore.YELLOW
                + f"    [!] git pull failed: {stderr[:200] if stderr else 'non-zero exit'}"
                + "  — continuing with existing rules."
                + Style.RESET_ALL
            )
            logger.warning("Sigma git pull failed: %s", stderr)
            return False
    except FileNotFoundError:
        print(
            Fore.YELLOW
            + "    [!] 'git' not found in PATH. Skipping Sigma update."
            + Style.RESET_ALL
        )
        logger.warning("git executable not found; Sigma pull skipped.")
        return False
    except subprocess.TimeoutExpired:
        print(
            Fore.YELLOW
            + "    [!] git pull timed out. Continuing with existing rules."
            + Style.RESET_ALL
        )
        logger.warning("Sigma git pull timed out.")
        return False
    except Exception as exc:
        print(
            Fore.YELLOW
            + f"    [!] Unexpected error during update: {exc}"
            + "  — continuing with existing rules."
            + Style.RESET_ALL
        )
        logger.warning("Unexpected error during Sigma git pull: %s", exc)
        return False


def _carregar_config_sigma() -> str:
    """Load the Sigma rules path from config.ini (cross-platform)."""
    config = configparser.ConfigParser()
    # Use Path to locate config.ini relative to the script directory
    config_path = Path(__file__).parent / "config.ini"
    config.read(str(config_path), encoding="utf-8")
    so = platform.system()
    try:
        if so.startswith("Win"):
            raw = config["settings"].get("path_windows", r"C:\tools\sigma\rules")
        else:
            raw = config["settings"].get("path", "/opt/sigma/rules")
        return str(Path(raw))          # normalise separators for current OS
    except Exception:
        candidato = Path(__file__).parent / "sigma" / "rules"
        return str(candidato) if candidato.is_dir() else "."


def atualizar_sigma_cli() -> bool:
    """
    Update the sigma-cli package before execution.

    Strategy:
      1. Detect the sigma-cli executable and read the currently installed
         version via 'pip show sigma-cli' (using sys.executable to guarantee
         the correct environment, regardless of virtualenv or PATH quirks).
      2. Run 'pip install --upgrade sigma-cli' with the same Python
         interpreter that is executing this script.
      3. After the upgrade, read the new version and log both values
         (before / after) for traceability.
      4. On any failure (no network, pip not available, permission error,
         etc.) a warning is printed and execution continues normally —
         the script is never interrupted.

    Returns:
        True  — upgrade succeeded or package was already at the latest version.
        False — upgrade skipped or failed (non-fatal).
    """
    # ── Helper: get the installed version via 'pip show sigma-cli' ───────────
    def _versao_instalada() -> str:
        """Return the currently installed sigma-cli version, or empty string."""
        try:
            res = subprocess.run(
                [sys.executable, "-m", "pip", "show", "sigma-cli"],
                capture_output=True, text=True, timeout=15,
            )
            for linha in res.stdout.splitlines():
                if linha.startswith("Version:"):
                    return linha.split(":", 1)[1].strip()
        except Exception:
            pass
        return ""

    # ── Helper: resolve the sigma executable path ─────────────────────────────
    def _caminho_sigma() -> str:
        """Return the sigma executable path found in PATH, or 'sigma' as fallback."""
        exe = shutil.which("sigma") or shutil.which("sigma.exe")
        return exe if exe else "sigma"

    # ── Read installed version before the upgrade ─────────────────────────────
    versao_antes = _versao_instalada()
    caminho_exe = _caminho_sigma()

    if versao_antes:
        print(
            Fore.CYAN
            + f"\n[*] Updating sigma-cli (installed: v{versao_antes}) ..."
            + Style.RESET_ALL
        )
        logger.info(
            "Starting sigma-cli upgrade — current version: %s | executable: %s",
            versao_antes, caminho_exe,
        )
    else:
        print(Fore.CYAN + "\n[*] Installing/updating sigma-cli ..." + Style.RESET_ALL)
        logger.info("sigma-cli not detected; attempting installation via pip.")

    # ── Run pip install --upgrade sigma-cli ───────────────────────────────────
    cmd = [sys.executable, "-m", "pip", "install", "--upgrade", "sigma-cli"]
    try:
        resultado = subprocess.run(
            cmd,
            capture_output=True, text=True, timeout=180,
        )

        versao_depois = _versao_instalada()

        if resultado.returncode == 0:
            if versao_antes and versao_depois and versao_antes == versao_depois:
                # pip ran successfully but nothing changed
                print(
                    Fore.GREEN
                    + f"    [OK] sigma-cli already at the latest version (v{versao_depois})."
                    + Style.RESET_ALL
                )
                logger.info("sigma-cli already up to date at v%s.", versao_depois)
            elif versao_depois:
                print(
                    Fore.GREEN
                    + f"    [OK] sigma-cli updated: v{versao_antes} → v{versao_depois}."
                    + Style.RESET_ALL
                )
                logger.info(
                    "sigma-cli updated successfully: v%s → v%s.",
                    versao_antes, versao_depois,
                )
            else:
                # pip exited 0 but version could not be read (edge case)
                print(
                    Fore.GREEN
                    + "    [OK] sigma-cli upgrade command completed."
                    + Style.RESET_ALL
                )
                logger.info("sigma-cli upgrade command completed (version unreadable).")
            return True
        else:
            stderr = resultado.stderr.strip()
            print(
                Fore.YELLOW
                + f"    [!] sigma-cli upgrade failed: "
                + f"{stderr[:200] if stderr else 'non-zero exit'}"
                + "  — continuing with current version."
                + Style.RESET_ALL
            )
            logger.warning(
                "sigma-cli pip upgrade failed (exit %d): %s",
                resultado.returncode, stderr,
            )
            return False

    except FileNotFoundError:
        # pip module not found or sys.executable is invalid
        print(
            Fore.YELLOW
            + "    [!] pip not available via the current Python interpreter. "
            + "Skipping sigma-cli update."
            + Style.RESET_ALL
        )
        logger.warning(
            "pip not found for interpreter '%s'; sigma-cli update skipped.",
            sys.executable,
        )
        return False
    except subprocess.TimeoutExpired:
        print(
            Fore.YELLOW
            + "    [!] sigma-cli upgrade timed out. "
            + "Continuing with current version."
            + Style.RESET_ALL
        )
        logger.warning("sigma-cli pip upgrade timed out.")
        return False
    except Exception as exc:
        print(
            Fore.YELLOW
            + f"    [!] Unexpected error during sigma-cli upgrade: {exc}"
            + "  — continuing with current version."
            + Style.RESET_ALL
        )
        logger.warning("Unexpected error during sigma-cli upgrade: %s", exc)
        return False


def _verificar_ambiente_sigma() -> Dict[str, Any]:
    """
    Verifica a integridade do ambiente sigma-cli antes de qualquer conversão.

    Detecta:
      - Crash de importação causado por plugins instalados incompatíveis com a
        versão atual do pySigma (ex.: ConditionTransformation removida na v1.x).
      - sigma-cli ausente no PATH.
      - Versões instaladas de sigma-cli e pySigma.

    Retorna um dict com:
      {
        "ok": bool,           # False se sigma sequer inicializa
        "versao_sigma_cli": str,
        "versao_pysigma": str,
        "erro_importacao": str,  # traceback completo se falhar
        "plugins_problematicos": List[str],
      }
    """
    resultado: Dict[str, Any] = {
        "ok": False,
        "versao_sigma_cli": "",
        "versao_pysigma": "",
        "erro_importacao": "",
        "plugins_problematicos": [],
    }

    # ── 1. Ler versões via pip show (não depende do sigma.exe) ────────────────
    for pkg, chave in [("sigma-cli", "versao_sigma_cli"), ("pysigma", "versao_pysigma")]:
        try:
            res = subprocess.run(
                [sys.executable, "-m", "pip", "show", pkg],
                capture_output=True, text=True, timeout=15,
            )
            for linha in res.stdout.splitlines():
                if linha.startswith("Version:"):
                    resultado[chave] = linha.split(":", 1)[1].strip()
        except Exception:
            pass

    # ── 2. Verificar se sigma.exe inicializa sem travar ───────────────────────
    try:
        probe = subprocess.run(
            ["sigma", "version"],
            capture_output=True, text=True, timeout=15,
        )
        if probe.returncode == 0:
            resultado["ok"] = True
        else:
            # sigma existe mas trava — capturar traceback completo
            resultado["erro_importacao"] = (probe.stderr or probe.stdout).strip()
            # Extrair nomes dos pacotes/módulos mencionados no traceback
            for linha in resultado["erro_importacao"].splitlines():
                if "site-packages" in linha and "sigma" in linha.lower():
                    # ex.: File "...site-packages\sigma\backends\cortexxdr\..."
                    partes = linha.replace("\\", "/").split("/")
                    for j, p in enumerate(partes):
                        if p == "sigma" and j + 1 < len(partes):
                            modulo = f"sigma.{partes[j+1]}.{partes[j+2].replace('.py','')}" \
                                     if j + 2 < len(partes) else f"sigma.{partes[j+1]}"
                            if modulo not in resultado["plugins_problematicos"]:
                                resultado["plugins_problematicos"].append(modulo)
    except FileNotFoundError:
        resultado["erro_importacao"] = "sigma-cli executable not found in PATH."
    except subprocess.TimeoutExpired:
        resultado["erro_importacao"] = "sigma version timed out."
    except Exception as exc:
        resultado["erro_importacao"] = str(exc)

    return resultado


def _listar_backends_sigma() -> List[str]:
    """
    Lista os backends disponíveis no sigma-cli instalado.

    Usa 'sigma list targets' e analisa a saída em Python puro (sem shell).
    Se o sigma-cli não inicializar (ex.: plugin incompatível instalado),
    exibe o diagnóstico completo e retorna a lista de fallback.
    """
    # ── Verificar integridade do ambiente antes de listar ─────────────────────
    amb = _verificar_ambiente_sigma()
    if not amb["ok"]:
        print(
            Fore.YELLOW
            + "\n[!] sigma-cli não inicializa corretamente. Detalhes:"
            + Style.RESET_ALL
        )
        print(Fore.RED + amb["erro_importacao"][:600] + Style.RESET_ALL)
        if amb["plugins_problematicos"]:
            print(
                Fore.YELLOW
                + "    Módulos possivelmente incompatíveis: "
                + ", ".join(amb["plugins_problematicos"])
                + Style.RESET_ALL
            )
        logger.error(
            "sigma-cli startup failure — versao_cli=%s versao_pysigma=%s — %s",
            amb["versao_sigma_cli"], amb["versao_pysigma"],
            amb["erro_importacao"][:400],
        )
        # Retorna fallback para não bloquear o fluxo
        return [
            "splunk", "lucene", "eql", "esql", "log_scale",
            "qradar", "sentinel_one",
        ]

    so = platform.system()
    try:
        # Usar 'sigma list targets' diretamente (funciona em Unix e Windows)
        result = subprocess.run(
            ["sigma", "list", "targets"],
            capture_output=True, text=True, timeout=20,
            shell=False,
        )

        if result.returncode == 0 and result.stdout:
            linhas = result.stdout.splitlines()
            backends: List[str] = []
            for linha in linhas:
                # Linha de tabela: | identificador | descrição | ... |
                partes = [p.strip() for p in linha.split("|") if p.strip()]
                if len(partes) >= 2 and partes[0] and not partes[0].startswith("-"):
                    # Pula a linha de cabeçalho (contém "Identifier")
                    if partes[0].lower() != "identifier":
                        backends.append(partes[0])
            if backends:
                logger.info("sigma list targets: %d backends detectados: %s", len(backends), backends)
                return backends
        elif result.stderr:
            logger.warning("sigma list targets stderr: %s", result.stderr[:300])

    except FileNotFoundError:
        logger.warning("sigma-cli not found in PATH; usando lista de fallback.")
    except subprocess.TimeoutExpired:
        logger.warning("sigma list targets timed out; usando lista de fallback.")
    except Exception as e:
        logger.warning("Erro ao listar backends sigma: %s", e)

    # Fallback: lista de backends conhecidos
    return [
        "splunk", "lucene", "eql", "esql", "log_scale",
        "qradar", "sentinel_one",
    ]


def _buscar_regras_sigma(caminho_regras: str, tecnica: str,
                          palavra_chave: Optional[str] = None,
                          nivel_min: Optional[str] = None) -> List[str]:
    """
    Search Sigma rule files that reference the given technique and keyword.
    Supports severity level filtering.
    """
    arquivos_encontrados = []

    caminho_path = Path(caminho_regras)
    if not caminho_path.is_dir():
        print(Fore.RED + f"Rules path not found: {caminho_regras}" + Style.RESET_ALL)
        return []

    niveis_ordem = {"informational": 0, "low": 1, "medium": 2, "high": 3, "critical": 4}
    nivel_min_num = niveis_ordem.get((nivel_min or "").lower(), 0)

    print(Fore.CYAN + f"[*] Searching rules for technique: {tecnica}" + Style.RESET_ALL)

    for raiz, _, arquivos in os.walk(str(caminho_path)):
        for arquivo in arquivos:
            if not arquivo.lower().endswith((".yml", ".yaml")):
                continue
            # Path.joinpath is cross-platform (no hardcoded separators)
            caminho_arq = str(Path(raiz) / arquivo)
            try:
                with open(caminho_arq, "r", encoding="utf-8", errors="ignore") as f:
                    conteudo = f.read()
                conteudo_lower = conteudo.lower()

                # Check if technique is present
                if tecnica.lower() not in conteudo_lower:
                    continue

                # Check additional keyword
                if palavra_chave and palavra_chave.lower() not in conteudo_lower:
                    continue

                # Level filter (if YAML is available)
                if YAML_AVAILABLE and nivel_min:
                    try:
                        dados_yaml = yaml.safe_load(conteudo)
                        nivel_regra = (dados_yaml or {}).get("level", "informational")
                        if niveis_ordem.get(nivel_regra.lower(), 0) < nivel_min_num:
                            continue
                    except Exception:
                        pass

                arquivos_encontrados.append(caminho_arq)
            except Exception as e:
                logger.debug("Error reading file %s: %s", caminho_arq, e)

    print(Fore.GREEN + f"  -> {len(arquivos_encontrados)} rule(s) found" + Style.RESET_ALL)
    return arquivos_encontrados


def _extrair_metadados_sigma(caminho_arq: str) -> Dict:
    """
    Extrai metadados completos de uma regra Sigma.

    Campos: título, descrição, autor, data, nível, tags, status, logsource,
    falsepositivos, referências e condição de detecção.
    """
    meta = {
        "arquivo": caminho_arq,
        "titulo": Path(caminho_arq).name,
        "descricao": "",
        "autor": "",
        "data": "",
        "nivel": "informational",
        "tags": [],
        "status": "",
        "logsource": {},
        "falsepositivos": [],     # campo estendido: false positives
        "referencias": [],        # campo estendido: references
        "condicao": "",           # campo estendido: detection.condition
    }
    if not YAML_AVAILABLE:
        return meta
    try:
        with open(caminho_arq, "r", encoding="utf-8", errors="ignore") as f:
            dados = yaml.safe_load(f)
        if not isinstance(dados, dict):
            return meta
        meta["titulo"]      = dados.get("title", meta["titulo"])
        meta["descricao"]   = dados.get("description", "")
        meta["autor"]       = dados.get("author", "")
        meta["data"]        = str(dados.get("date", ""))
        meta["nivel"]       = dados.get("level", "informational")
        meta["tags"]        = dados.get("tags", [])
        meta["status"]      = dados.get("status", "")
        meta["logsource"]   = dados.get("logsource", {})

        # False positives (pode ser string ou lista)
        fp_raw = dados.get("falsepositives", [])
        if isinstance(fp_raw, str):
            meta["falsepositivos"] = [fp_raw]
        elif isinstance(fp_raw, list):
            meta["falsepositivos"] = [str(fp) for fp in fp_raw if fp]

        # References (links externos para a regra)
        refs_raw = dados.get("references", [])
        if isinstance(refs_raw, str):
            meta["referencias"] = [refs_raw]
        elif isinstance(refs_raw, list):
            meta["referencias"] = [str(r) for r in refs_raw if r]

        # Condition da seção detection
        detec = dados.get("detection", {})
        if isinstance(detec, dict):
            meta["condicao"] = str(detec.get("condition", ""))

    except Exception as e:
        logger.debug("Erro ao parsear YAML %s: %s", caminho_arq, e)
    return meta


def _copiar_regras_findings(arquivos: List[str], tecnica: str) -> Tuple[List[str], str]:
    """Copy rule files to the findings directory."""
    ts = datetime.datetime.now().strftime("%Y%m%d%H%M")
    destino = DIR_FINDINGS / "sigma_rules" / f"techniques_{ts}"
    destino.mkdir(parents=True, exist_ok=True)

    copiados = []
    for arq in arquivos:
        try:
            dest = shutil.copy(arq, str(destino))
            copiados.append(dest)
        except Exception as e:
            logger.warning("Error copying %s: %s", arq, e)

    return copiados, str(destino)


# Padrões de erros conhecidos do sigma-cli para classificação automática
_SIGMA_ERROS_CONHECIDOS: List[Tuple[str, str]] = [
    ("SigmaFeatureNotSupportedByBackendError", "Funcionalidade não suportada pelo backend"),
    ("SigmaPluginNotFoundError",               "Plugin/backend não encontrado"),
    ("SigmaValueError",                        "Valor inválido na regra"),
    ("SigmaConditionError",                    "Condição de detecção inválida"),
    ("SigmaLogsourceError",                    "Logsource incompatível com o backend"),
    ("SigmaIdentifierError",                   "Identificador de campo não mapeado"),
    ("SigmaTransformationError",               "Erro em transformação de pipeline"),
    ("ImportError",                            "Plugin não instalado ou incompatível"),
    ("cannot import name",                     "Incompatibilidade de versão de plugin"),
    ("NotImplementedError",                    "Funcionalidade não implementada pelo backend"),
]


def _classificar_erro_sigma(stderr: str, stdout: str) -> Tuple[str, str]:
    """
    Classifica o erro de conversão do sigma-cli a partir de stderr/stdout.

    Retorna (tipo_erro, descricao_legivel).
    """
    texto_completo = (stderr + stdout).lower()
    for token, descricao in _SIGMA_ERROS_CONHECIDOS:
        if token.lower() in texto_completo:
            return token, descricao
    return "ERRO_DESCONHECIDO", "Erro não classificado"


def _converter_regras_sigma(arquivos: List[str], backend: str,
                             diretorio_destino: str) -> Dict[str, str]:
    """
    Converte regras Sigma para o backend especificado via sigma-cli.

    Melhorias em relação à versão anterior:
      - Verificação prévia do ambiente (sigma-cli inicializa sem crash).
      - Captura e exibe o stderr/stdout COMPLETOS de cada falha — sem truncar.
      - Classifica automaticamente o tipo de erro (SigmaFeatureNotSupportedByBackendError,
        SigmaPluginNotFoundError, ImportError de plugin incompatível, etc.).
      - Regras individuais com falha não interrompem o pipeline: são registradas
        em 'falhas' e contabilizadas no sumário final.
      - Grava um relatório estruturado de falhas em <dir_backend>/falhas_conversao.log.
      - Retorna o mapa filename → query convertida (apenas sucessos).

    Retorna:
        Dict[str, str] — mapa nome_base → conteúdo da query convertida.
        Regras com falha NÃO aparecem no dicionário de retorno.
    """
    # ── Verificar ambiente antes de começar ───────────────────────────────────
    amb = _verificar_ambiente_sigma()
    if not amb["ok"]:
        print(
            Fore.RED
            + f"\n[!] Conversão abortada: sigma-cli não inicializa.\n"
            + f"    {amb['erro_importacao'][:300]}"
            + Style.RESET_ALL
        )
        logger.error(
            "Conversão abortada — sigma-cli falhou na inicialização: %s",
            amb["erro_importacao"][:400],
        )
        return {}

    dir_backend = Path(diretorio_destino) / backend.upper()
    dir_backend.mkdir(parents=True, exist_ok=True)

    queries_convertidas: Dict[str, str] = {}
    # Registro detalhado de falhas: lista de dicts com metadados de cada erro
    falhas: List[Dict[str, str]] = []

    total = len(arquivos)
    print(
        Fore.CYAN
        + f"[*] Convertendo {total} regra(s) para {backend.upper()} ..."
        + Style.RESET_ALL
    )
    logger.info("Iniciando conversão de %d regra(s) para backend '%s'.", total, backend)

    for i, arq in enumerate(arquivos, 1):
        arq_path = Path(arq)
        nome_base = arq_path.stem
        arq_saida = dir_backend / f"{nome_base}.txt"

        # Comando passado ao sigma-cli.
        # --without-pipeline é necessário quando nenhuma pipeline é especificada,
        # pois o sigma-cli 3.x exige pipeline ou a flag explícita para suprimir
        # o erro "Processing pipeline required by backend".
        cmd_lista = [
            "sigma", "convert",
            "--without-pipeline",
            "-t", backend,
            "-f", "default",
            str(arq_path),
        ]

        logger.debug("[%d/%d] Convertendo: %s | cmd: %s", i, total, nome_base, " ".join(cmd_lista))

        try:
            resultado = subprocess.run(
                cmd_lista,
                shell=False,
                capture_output=True,
                text=True,
                timeout=30,
            )

            if resultado.returncode == 0 and resultado.stdout.strip():
                # Sucesso: gravar saída no arquivo e no dict
                conteudo_query = resultado.stdout.strip()
                arq_saida.write_text(conteudo_query, encoding="utf-8")
                queries_convertidas[nome_base] = conteudo_query
                print(Fore.GREEN + f"  [{i:>3}/{total}] OK  {nome_base}" + Style.RESET_ALL)
                logger.debug("Convertido com sucesso: %s", nome_base)

            elif resultado.returncode == 0 and not resultado.stdout.strip():
                # Exit 0 mas sem saída — regra não gerou query (ex.: logsource sem mapeamento)
                msg = (resultado.stderr.strip() or "Nenhuma query gerada (logsource possivelmente sem mapeamento para este backend).")
                tipo, desc = _classificar_erro_sigma(resultado.stderr, resultado.stdout)
                print(
                    Fore.YELLOW
                    + f"  [{i:>3}/{total}] SKIP {nome_base}"
                    + Style.RESET_ALL
                )
                print(
                    Fore.YELLOW
                    + f"         Tipo: {tipo} — {desc}"
                    + Style.RESET_ALL
                )
                logger.warning(
                    "SKIP [%s] backend=%s tipo=%s — %s",
                    nome_base, backend, tipo, msg[:300],
                )
                falhas.append({
                    "arquivo": str(arq_path),
                    "nome_base": nome_base,
                    "tipo": tipo,
                    "descricao": desc,
                    "stderr_completo": resultado.stderr,
                    "stdout_completo": resultado.stdout,
                    "returncode": str(resultado.returncode),
                })

            else:
                # Falha real (returncode != 0)
                stderr_full = resultado.stderr.strip()
                stdout_full = resultado.stdout.strip()
                tipo, desc = _classificar_erro_sigma(stderr_full, stdout_full)

                # Exibir o stderr COMPLETO no terminal (não truncado)
                print(
                    Fore.YELLOW
                    + f"  [{i:>3}/{total}] FAIL {nome_base}"
                    + Style.RESET_ALL
                )
                print(
                    Fore.YELLOW
                    + f"         Tipo: {tipo} — {desc}"
                    + Style.RESET_ALL
                )
                if stderr_full:
                    # Exibir as últimas 6 linhas do traceback (mais relevantes)
                    linhas_err = stderr_full.splitlines()
                    trecho = "\n".join(linhas_err[-6:]) if len(linhas_err) > 6 else stderr_full
                    print(Fore.RED + f"         Detalhe:\n{trecho}" + Style.RESET_ALL)

                logger.warning(
                    "FAIL [%s] backend=%s rc=%d tipo=%s\n--- stderr ---\n%s\n--- stdout ---\n%s",
                    nome_base, backend, resultado.returncode, tipo,
                    stderr_full, stdout_full,
                )
                falhas.append({
                    "arquivo": str(arq_path),
                    "nome_base": nome_base,
                    "tipo": tipo,
                    "descricao": desc,
                    "stderr_completo": stderr_full,
                    "stdout_completo": stdout_full,
                    "returncode": str(resultado.returncode),
                })

        except subprocess.TimeoutExpired:
            msg = f"Timeout (>30s) ao converter {nome_base}"
            print(Fore.YELLOW + f"  [{i:>3}/{total}] TIMEOUT {nome_base}" + Style.RESET_ALL)
            logger.warning(msg)
            falhas.append({
                "arquivo": str(arq_path),
                "nome_base": nome_base,
                "tipo": "TIMEOUT",
                "descricao": "Conversão excedeu 30 segundos",
                "stderr_completo": "",
                "stdout_completo": "",
                "returncode": "-1",
            })
        except FileNotFoundError:
            msg = "sigma-cli não encontrado no PATH durante a conversão"
            print(Fore.RED + f"  [{i:>3}/{total}] ERROR {nome_base} — {msg}" + Style.RESET_ALL)
            logger.error(msg)
            falhas.append({
                "arquivo": str(arq_path),
                "nome_base": nome_base,
                "tipo": "SIGMA_NOT_FOUND",
                "descricao": msg,
                "stderr_completo": "",
                "stdout_completo": "",
                "returncode": "-2",
            })
        except Exception as exc:
            msg = str(exc)
            print(Fore.RED + f"  [{i:>3}/{total}] ERROR {nome_base} — {msg}" + Style.RESET_ALL)
            logger.error("Erro inesperado ao converter %s: %s", arq, msg)
            falhas.append({
                "arquivo": str(arq_path),
                "nome_base": nome_base,
                "tipo": "ERRO_INESPERADO",
                "descricao": msg,
                "stderr_completo": "",
                "stdout_completo": "",
                "returncode": "-3",
            })

    # ── Sumário no console ────────────────────────────────────────────────────
    ok_count   = len(queries_convertidas)
    fail_count = len(falhas)
    print(
        Fore.CYAN
        + f"\n  Sumário da conversão ({backend.upper()}):"
        + Style.RESET_ALL
    )
    print(Fore.GREEN  + f"    Convertidas com sucesso : {ok_count}/{total}" + Style.RESET_ALL)
    if fail_count:
        print(Fore.YELLOW + f"    Falhas/skips            : {fail_count}/{total}" + Style.RESET_ALL)
        # Agrupar falhas por tipo
        por_tipo: Dict[str, int] = {}
        for f in falhas:
            por_tipo[f["tipo"]] = por_tipo.get(f["tipo"], 0) + 1
        for tipo, cnt in sorted(por_tipo.items(), key=lambda x: -x[1]):
            print(Fore.YELLOW + f"      {tipo:<45} {cnt} regra(s)" + Style.RESET_ALL)

    logger.info(
        "Conversão concluída — backend=%s ok=%d falha=%d total=%d",
        backend, ok_count, fail_count, total,
    )

    # ── Gravar relatório de falhas em arquivo estruturado ────────────────────
    if falhas:
        arq_falhas = dir_backend / "falhas_conversao.log"
        try:
            with open(str(arq_falhas), "w", encoding="utf-8") as f:
                f.write(
                    f"# Relatório de falhas de conversão Sigma\n"
                    f"# Backend: {backend.upper()}\n"
                    f"# Data   : {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
                    f"# Total  : {fail_count}/{total} regras não convertidas\n"
                    f"{'='*70}\n\n"
                )
                for entrada in falhas:
                    f.write(f"ARQUIVO  : {entrada['arquivo']}\n")
                    f.write(f"NOME     : {entrada['nome_base']}\n")
                    f.write(f"TIPO     : {entrada['tipo']}\n")
                    f.write(f"DESCRIÇÃO: {entrada['descricao']}\n")
                    f.write(f"EXIT CODE: {entrada['returncode']}\n")
                    if entrada["stderr_completo"]:
                        f.write(f"STDERR:\n{entrada['stderr_completo']}\n")
                    if entrada["stdout_completo"]:
                        f.write(f"STDOUT:\n{entrada['stdout_completo']}\n")
                    f.write(f"{'-'*70}\n\n")
            print(
                Fore.YELLOW
                + f"  -> Relatório de falhas gravado em: {arq_falhas}"
                + Style.RESET_ALL
            )
            logger.info("Relatório de falhas gravado: %s", arq_falhas)
        except Exception as exc:
            logger.warning("Não foi possível gravar relatório de falhas: %s", exc)

    return queries_convertidas


def _gerar_html_sigrules(metadados_regras: List[Dict], queries: Dict[str, str],
                          backend: str, tecnicas: List[str]) -> str:
    """Generate the full HTML report for FindSigRules."""
    ts_exib = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    ts_arquivo = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    tecnicas_str = "_".join(tecnicas[:3]) if tecnicas else "multi"
    nome_arquivo = f"chimera_report_SigRules_{tecnicas_str}_{ts_arquivo}.html"
    caminho = DIR_FINDINGS / nome_arquivo

    # Colour palette by severity level
    cores_nivel = {
        "critical": "#f85149",
        "high": "#f0883e",
        "medium": "#e3b341",
        "low": "#39d353",
        "informational": "#58a6ff",
    }

    # Summary items
    sumario_html = "".join(
        f'<li><a href="#regra-{i}">{m["titulo"][:60]}</a></li>'
        for i, m in enumerate(metadados_regras)
    )

    # Cards das regras
    cards_html = ""
    for i, meta in enumerate(metadados_regras):
        nivel = meta.get("nivel", "informational")
        cor_nivel = cores_nivel.get(nivel.lower(), "#8b949e")
        tags_html = " ".join(
            f'<span class="tag">{t}</span>' for t in meta.get("tags", [])[:8]
        )
        logsource = meta.get("logsource", {})
        logsource_str = ", ".join(f"{k}: {v}" for k, v in logsource.items())

        nome_base = os.path.splitext(os.path.basename(meta["arquivo"]))[0]
        query_html = ""
        if nome_base in queries:
            q = queries[nome_base]
            query_html = f"""
            <div class="query-bloco">
                <div class="query-header">Query {backend.upper()}</div>
                <pre class="query-code">{q}</pre>
            </div>"""

        # Falsos positivos documentados na regra
        fp_lista = meta.get("falsepositivos", [])
        fp_html = ""
        if fp_lista:
            fp_itens = "".join(f"<li>{fp}</li>" for fp in fp_lista[:5])
            fp_html = f"""
            <details class="sigma-detalhe">
                <summary class="sigma-detalhe-toggle">⚠️ Falsos Positivos ({len(fp_lista)})</summary>
                <ul class="fp-list">{fp_itens}</ul>
            </details>"""

        # Referências externas da regra
        refs_lista = meta.get("referencias", [])
        refs_html = ""
        if refs_lista:
            refs_itens = "".join(
                f'<li><a href="{r}" target="_blank">{r[:80]}</a></li>'
                for r in refs_lista[:5]
            )
            refs_html = f"""
            <details class="sigma-detalhe">
                <summary class="sigma-detalhe-toggle">🔗 Referências ({len(refs_lista)})</summary>
                <ul class="fp-list">{refs_itens}</ul>
            </details>"""

        # Condição de detecção
        condicao = meta.get("condicao", "")
        cond_html = ""
        if condicao:
            cond_html = f'<p class="sigma-cond"><strong>Condição de detecção:</strong> <code>{condicao}</code></p>'

        cards_html += f"""
        <div class="regra-card" id="regra-{i}">
            <div class="regra-header">
                <span class="nivel-badge" style="background:{cor_nivel}22; color:{cor_nivel}; border:1px solid {cor_nivel}">
                    {nivel.upper()}
                </span>
                <span class="regra-titulo">{meta['titulo']}</span>
            </div>
            <div class="regra-meta">
                <span><strong>Autor:</strong> {meta['autor'] or 'N/A'}</span>
                <span><strong>Data:</strong> {meta['data'] or 'N/A'}</span>
                <span><strong>Status:</strong> {meta['status'] or 'N/A'}</span>
                <span><strong>LogSource:</strong> {logsource_str or 'N/A'}</span>
            </div>
            <p class="regra-descricao">{meta['descricao'][:300] if meta['descricao'] else 'Sem descrição'}</p>
            {cond_html}
            <div class="tags-linha">{tags_html}</div>
            {fp_html}
            {refs_html}
            {query_html}
        </div>
        """

    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chimera — FindSigRules — {ts_exib}</title>
    <style>
        :root {{
            --bg: #0d1117; --surface: #161b22; --surface2: #21262d;
            --border: #30363d; --text: #e6edf3; --muted: #8b949e;
            --cyan: #39d353; --accent: #58a6ff;
        }}
        * {{ box-sizing: border-box; margin: 0; padding: 0; }}
        body {{ background: var(--bg); color: var(--text);
               font-family: 'Segoe UI', system-ui, sans-serif; font-size: 14px; line-height: 1.6; }}
        a {{ color: var(--accent); text-decoration: none; }}
        .container {{ max-width: 1100px; margin: 0 auto; padding: 32px 24px; }}
        header {{ border-bottom: 2px solid var(--cyan); padding-bottom: 16px; margin-bottom: 28px; }}
        header h1 {{ font-size: 1.8em; color: var(--cyan); }}
        header .meta {{ color: var(--muted); font-size: 0.85em; margin-top: 6px; }}
        .sumario {{ background: var(--surface); border: 1px solid var(--border);
                   border-radius: 8px; padding: 18px; margin-bottom: 28px; }}
        .sumario h2 {{ color: var(--cyan); margin-bottom: 10px; }}
        .sumario ol {{ padding-left: 20px; columns: 2; gap: 16px; color: var(--muted); }}
        .regra-card {{ background: var(--surface); border: 1px solid var(--border);
                      border-radius: 8px; padding: 18px; margin-bottom: 18px; }}
        .regra-header {{ display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }}
        .nivel-badge {{ padding: 3px 10px; border-radius: 10px; font-size: 0.75em; font-weight: 700; }}
        .regra-titulo {{ font-weight: 600; font-size: 1em; color: var(--text); }}
        .regra-meta {{ display: flex; gap: 20px; flex-wrap: wrap; font-size: 0.82em;
                      color: var(--muted); margin-bottom: 8px; }}
        .regra-descricao {{ color: var(--muted); font-size: 0.88em; margin-bottom: 10px; }}
        .tags-linha {{ margin-bottom: 12px; }}
        .tag {{ display: inline-block; background: #1a2a3a; color: var(--accent);
               border: 1px solid #1a3a5a; border-radius: 4px; padding: 1px 7px;
               font-size: 0.78em; margin: 2px; }}
        .query-bloco {{ background: #0d1117; border: 1px solid var(--border);
                       border-radius: 6px; margin-top: 12px; }}
        .query-header {{ background: var(--surface2); padding: 6px 14px; font-size: 0.8em;
                        color: var(--muted); border-bottom: 1px solid var(--border); }}
        .query-code {{ padding: 12px 14px; font-family: 'Cascadia Code', 'Fira Code', monospace;
                      font-size: 0.85em; color: #39d353; overflow-x: auto; white-space: pre-wrap; }}
        /* ── Campos estendidos Sigma ─────────────────────────────────── */
        .sigma-detalhe {{ margin-top: 8px; border: 1px solid var(--border); border-radius: 4px; overflow: hidden; }}
        .sigma-detalhe-toggle {{ cursor: pointer; padding: 5px 10px; background: var(--surface2);
                                 color: var(--muted); font-size: 0.82em; list-style: none; }}
        .sigma-detalhe-toggle::-webkit-details-marker {{ display: none; }}
        .fp-list {{ padding: 6px 16px 8px; color: var(--muted); font-size: 0.83em; }}
        .fp-list li {{ margin-bottom: 3px; }}
        .sigma-cond {{ font-size: 0.83em; color: var(--muted); margin: 6px 0; }}
        .sigma-cond code {{ background: var(--surface2); padding: 1px 5px; border-radius: 3px; color: var(--cyan); }}
        footer {{ border-top: 1px solid var(--border); padding-top: 16px; margin-top: 48px;
                 text-align: center; color: var(--muted); font-size: 0.8em; }}
    </style>
</head>
<body>
<div class="container">
    <header>
        <h1><img src="{_CHIMERA_LOGO_B64}" alt="Chimera" style="height:1.2em;vertical-align:middle;object-fit:contain;margin-right:0.4em;"> Chimera — FindSigRules</h1>
        <div class="meta">
            Técnicas: <strong>{', '.join(tecnicas)}</strong> &nbsp;|&nbsp;
            Backend: <strong>{backend.upper()}</strong> &nbsp;|&nbsp;
            {len(metadados_regras)} regra(s) &nbsp;|&nbsp; {ts_exib}
        </div>
    </header>

    <div class="sumario">
        <h2>Sumário — Regras Sigma Encontradas</h2>
        <ol>{sumario_html}</ol>
    </div>

    {cards_html}

    <footer>
        <p>Relatório gerado por <strong>Chimera v{VERSION}</strong> — Plataforma de Threat Intelligence &amp; Hunting</p>
    </footer>
</div>
</body>
</html>"""

    with open(caminho, "w", encoding="utf-8") as f:
        f.write(html)
    logger.info("Relatório SigRules salvo: %s", caminho)
    print(Fore.LIGHTGREEN_EX + f"  -> Relatório salvo em: {caminho}" + Style.RESET_ALL)
    # Open the finished FindSigRules report in the user's default browser
    _abrir_no_browser(str(caminho))
    return str(caminho)


def executar_find_sig_rules(arquivos_tecnicas: Optional[List[str]] = None,
                             args_batch: Optional[Dict] = None) -> Optional[Dict]:
    """
    Execute the FindSigRules module.
    Receives a list of technique file paths for chaining.
    """
    print(Fore.CYAN + """
+--------------------------------------------+
|         FindSigRules v2.0                  |
|   Technique Correlation with Sigma Rules   |
+--------------------------------------------+""" + Style.RESET_ALL)

    # Load rules path
    caminho_regras = args_batch.get("path", "") if args_batch else ""
    if not caminho_regras:
        caminho_regras = _carregar_config_sigma()
        if not args_batch:
            cam_inp = input(
                Fore.LIGHTGREEN_EX + f"Sigma rules path [{caminho_regras}]: " + Style.RESET_ALL
            ).strip()
            if cam_inp:
                caminho_regras = cam_inp

    # Determine techniques to search
    tecnicas: List[str] = []

    if args_batch and args_batch.get("technique"):
        tecnicas = [args_batch["technique"]]
    elif arquivos_tecnicas:
        print(Fore.CYAN + f"[*] Loading techniques from chained files..." + Style.RESET_ALL)
        for arq in arquivos_tecnicas:
            if os.path.isfile(arq):
                with open(arq, "r", encoding="utf-8") as f:
                    tecnicas.extend([l.strip() for l in f if l.strip()])
            elif os.path.isdir(arq):
                for nome_arq in os.listdir(arq):
                    if nome_arq.endswith(".txt"):
                        cam = os.path.join(arq, nome_arq)
                        with open(cam, "r", encoding="utf-8") as f:
                            tecnicas.extend([l.strip() for l in f if l.strip()])
    else:
        # Interactive mode
        tec_inp = input(Fore.LIGHTGREEN_EX + "Technique(s) to search (e.g. T1059 or .txt file): " + Style.RESET_ALL).strip()
        if os.path.isfile(tec_inp):
            with open(tec_inp, "r", encoding="utf-8") as f:
                tecnicas = [l.strip() for l in f if l.strip()]
        elif tec_inp:
            tecnicas = [t.strip() for t in tec_inp.split(",")]

    if not tecnicas:
        print(Fore.RED + "No technique specified." + Style.RESET_ALL)
        return None

    # Severity filter
    _NIVEL_MAP = {
        "i": "informational",
        "l": "low",
        "m": "medium",
        "h": "high",
        "c": "critical",
    }
    nivel_min = None
    if args_batch:
        nivel_min = args_batch.get("level")
    elif not args_batch:
        print("\nMinimum severity level filter:")
        print("  Leave blank to show all")
        print("  Options: i (informational), l (low), m (medium), h (high), c (critical)")
        while True:
            _inp = input(Fore.LIGHTGREEN_EX + "Minimum level []: " + Style.RESET_ALL).strip().lower()
            if _inp == "":
                nivel_min = None
                break
            if _inp in _NIVEL_MAP:
                nivel_min = _NIVEL_MAP[_inp]
                break
            print(Fore.RED + f"  Invalid option '{_inp}'. Use one of: i, l, m, h, c (or leave blank)." + Style.RESET_ALL)

    # Additional keyword
    palavra_chave = None
    if not args_batch:
        pk_inp = input(Fore.LIGHTGREEN_EX + "Additional keyword (optional): " + Style.RESET_ALL).strip()
        if pk_inp:
            palavra_chave = pk_inp

    # Search rules for each technique
    todos_arquivos: List[str] = []
    for tecnica in tecnicas:
        arqs = _buscar_regras_sigma(caminho_regras, tecnica, palavra_chave, nivel_min)
        todos_arquivos.extend(arqs)

    # Deduplicate
    todos_arquivos = list(dict.fromkeys(todos_arquivos))

    if not todos_arquivos:
        print(Fore.YELLOW + "No Sigma rules found for the specified techniques." + Style.RESET_ALL)
        return None

    print(Fore.GREEN + f"\n  Total unique rules found: {len(todos_arquivos)}" + Style.RESET_ALL)

    # Extract metadata
    metadados = [_extrair_metadados_sigma(arq) for arq in todos_arquivos]

    # Copy to findings
    copiados, dir_findings = _copiar_regras_findings(todos_arquivos, tecnicas[0] if tecnicas else "sigma")

    # Ask about conversion
    backend = ""
    queries_convertidas: Dict[str, str] = {}

    converter = False
    if args_batch and args_batch.get("backend"):
        converter = True
        backend = args_batch["backend"]
    elif not args_batch:
        conv_inp = input(Fore.LIGHTGREEN_EX + "\nConvert to query language? (Y/N): " + Style.RESET_ALL).strip().upper()
        converter = conv_inp == "Y"

    if converter:
        backends_disponiveis = _listar_backends_sigma()
        if not backend:
            print(Fore.CYAN + "\nAvailable backends:" + Style.RESET_ALL)
            for i, b in enumerate(backends_disponiveis, 1):
                print(f"  {i}. {b.upper()}")
            try:
                escolha = int(input(Fore.LIGHTGREEN_EX + "\nChoose by number: " + Style.RESET_ALL)) - 1
                backend = backends_disponiveis[escolha]
            except (ValueError, IndexError):
                print(Fore.RED + "Invalid choice." + Style.RESET_ALL)
                converter = False

        if converter and backend:
            # A mensagem "[*] Convertendo N regras..." agora é emitida dentro
            # de _converter_regras_sigma, junto com o sumário de falhas.
            queries_convertidas = _converter_regras_sigma(copiados, backend, dir_findings)

            # Exportar apenas as queries que foram convertidas com sucesso
            if queries_convertidas:
                nome_exp = DIR_FINDINGS / (
                    f"chimera_queries_{tecnicas[0] if tecnicas else 'multi'}"
                    f"_{backend}_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
                )
                with open(nome_exp, "w", encoding="utf-8") as f:
                    for nome, query in queries_convertidas.items():
                        f.write(f"# === {nome} ===\n{query}\n\n")
                print(Fore.GREEN + f"  -> Queries exportadas para: {nome_exp}" + Style.RESET_ALL)
            else:
                print(
                    Fore.YELLOW
                    + "  [!] Nenhuma query convertida com sucesso para exportar."
                    + Style.RESET_ALL
                )

    # Generate HTML report
    html_path_sig = _gerar_html_sigrules(metadados, queries_convertidas, backend or "N/A", tecnicas)

    registrar_historico("FindSigRules", {
        "tecnicas": tecnicas,
        "backend": backend,
        "total_regras": len(todos_arquivos),
    })

    return {
        "arquivos_regras": todos_arquivos,
        "metadados": metadados,
        "queries": queries_convertidas,
        "backend": backend,
        "html_path": html_path_sig,
    }


