class QueryGeneratorLLM:
    """
    Generate SIEM/EDR detection queries using an LLM backend.

    Two-layer strategy
    ------------------
    Layer A (primary, Sigma-anchored)
        Translates existing Sigma Rules to the target backend syntax when
        sigma-cli fails or the backend is unsupported.  Full traceability:
        every output query is anchored to its source Sigma Rule file path.

    Layer B (secondary, TTP-synthesised)
        Synthesises queries for TTPs that have no matching Sigma Rules.
        Input is the structured FindAPTAttck output (TTPs, tools, platforms,
        x_mitre_detection).  Output is tagged source="llm_synthesized" so
        analysts can prioritise review before activating in production.

    Provider support
    ----------------
    - openai        : OpenAI Chat Completions API  (gpt-4o, gpt-4-turbo, …)
    - anthropic     : Anthropic Messages API       (claude-3-5-sonnet, …)
    - google        : Google Generative AI         (gemini-1.5-pro, …)
    - ollama        : Ollama local server          (llama3, mistral, …)
    - azure_openai  : Azure OpenAI service         (any deployed model)
    """

    def __init__(
        self,
        provider: str = LLM_PROVIDER,
        api_key: str = LLM_API_KEY,
        model: str = LLM_MODEL,
        base_url: str = LLM_BASE_URL,
        timeout: int = LLM_TIMEOUT,
        max_retries: int = LLM_MAX_RETRIES,
    ) -> None:
        self.provider   = provider.lower()
        self.api_key    = api_key
        self.model      = model
        self.base_url   = base_url
        self.timeout    = timeout
        self.max_retries = max_retries
        logger.info(
            "QueryGeneratorLLM initialised — provider=%s model=%s",
            self.provider, self.model,
        )

    # ── Internal: raw LLM call ────────────────────────────────────────────────

    def _call_llm(self, system_prompt: str, user_prompt: str) -> str:
        """
        Dispatch a single completion request to the configured provider.

        Returns the response text or an empty string on failure.
        Implements exponential back-off retry for rate-limit errors (429).
        """
        for attempt in range(1, self.max_retries + 1):
            try:
                return self._dispatch(system_prompt, user_prompt)
            except Exception as exc:
                msg = str(exc)
                is_rate_limit = "429" in msg or "rate" in msg.lower() or "quota" in msg.lower()
                if is_rate_limit and attempt < self.max_retries:
                    wait = 2 ** attempt
                    logger.warning(
                        "LLM rate-limit hit (attempt %d/%d) — waiting %ds: %s",
                        attempt, self.max_retries, wait, msg[:200],
                    )
                    time.sleep(wait)
                    continue
                logger.error(
                    "LLM call failed (attempt %d/%d): %s",
                    attempt, self.max_retries, msg[:400],
                )
                if attempt == self.max_retries:
                    return ""
        return ""

    def _dispatch(self, system_prompt: str, user_prompt: str) -> str:
        """Route the call to the correct provider implementation."""
        if self.provider == "openai":
            return self._call_openai(system_prompt, user_prompt)
        if self.provider == "anthropic":
            return self._call_anthropic(system_prompt, user_prompt)
        if self.provider == "google":
            return self._call_google(system_prompt, user_prompt)
        if self.provider in ("ollama", "azure_openai"):
            return self._call_openai_compat(system_prompt, user_prompt)
        if self.provider == "ibm_ica":
            return self._call_ibm_ica(system_prompt, user_prompt)
        # Unknown provider: attempt OpenAI-compatible REST
        logger.warning("Unknown LLM provider '%s' — trying OpenAI-compatible REST.", self.provider)
        return self._call_openai_compat(system_prompt, user_prompt)

    def _call_openai(self, system_prompt: str, user_prompt: str) -> str:
        """Call the OpenAI Chat Completions API."""
        url = (self.base_url or "https://api.openai.com") + "/v1/chat/completions"
        payload = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user",   "content": user_prompt},
            ],
            "temperature": 0.1,
            "max_tokens":  2048,
        }
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type":  "application/json",
        }
        resp = requests.post(url, json=payload, headers=headers, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()
        return data["choices"][0]["message"]["content"].strip()

    def _call_openai_compat(self, system_prompt: str, user_prompt: str) -> str:
        """
        Call an OpenAI-compatible endpoint (Azure OpenAI, Ollama, LM Studio, …).
        Uses LLM_BASE_URL as the full base; for Azure the model becomes the
        deployment name.
        """
        base = self.base_url or "http://localhost:11434"
        # Ollama exposes /api/chat (not /v1/chat/completions)
        if self.provider == "ollama":
            url = base.rstrip("/") + "/api/chat"
            payload = {
                "model": self.model,
                "messages": [
                    {"role": "system", "content": system_prompt},
                    {"role": "user",   "content": user_prompt},
                ],
                "stream": False,
                "options": {"temperature": 0.1},
            }
            resp = requests.post(url, json=payload, timeout=self.timeout)
            resp.raise_for_status()
            data = resp.json()
            return data.get("message", {}).get("content", "").strip()
        # Azure OpenAI: base_url must include the deployment path
        url = base.rstrip("/") + "/chat/completions?api-version=2024-02-01"
        payload = {
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user",   "content": user_prompt},
            ],
            "temperature": 0.1,
            "max_tokens":  2048,
        }
        headers = {
            "api-key":      self.api_key,
            "Content-Type": "application/json",
        }
        resp = requests.post(url, json=payload, headers=headers, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()
        return data["choices"][0]["message"]["content"].strip()

    def _call_ibm_ica(self, system_prompt: str, user_prompt: str) -> str:
        """
        Call the IBM ICA /agents/chat/completions endpoint.

        IBM ICA agents endpoint contract differences vs. standard OpenAI schema:
          - ``base_url`` must be the **full** endpoint URL, including the path, e.g.
            ``https://<host>/ica/v1/agents/chat/completions``.
          - The ``model`` field IS sent in the request body to select the deployed model.
          - ``temperature`` and ``max_tokens`` are not accepted and must be omitted.
          - Authentication uses only ``Authorization: Bearer <key>``; the
            Azure-style ``api-key`` header is NOT sent.
          - ``stream: false`` is required to receive a complete, non-streaming response.
        """
        if not self.base_url:
            logger.error(
                "QueryGeneratorLLM: LLM_BASE_URL must be set to the full IBM ICA "
                "endpoint URL when using provider 'ibm_ica', e.g. "
                "https://<host>/ica/v1/agents/chat/completions"
            )
            return ""
        url = self.base_url  # full endpoint URL — do not append any path suffix
        payload = {
            "model": self.model,
            "messages": [
                {"role": "user", "content": user_prompt},
            ],
            "stream": False,
            # 'temperature' and 'max_tokens' intentionally omitted —
            # the IBM ICA agents endpoint rejects these fields with HTTP 400.
        }
        headers = {
            "accept":        "application/json",
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type":  "application/json",
        }
        resp = requests.post(url, json=payload, headers=headers, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()
        return data["choices"][0]["message"]["content"].strip()

    def _call_anthropic(self, system_prompt: str, user_prompt: str) -> str:
        """Call the Anthropic Messages API (claude-3-* models)."""
        url = (self.base_url or "https://api.anthropic.com") + "/v1/messages"
        payload = {
            "model":      self.model,
            "max_tokens": 2048,
            "system":     system_prompt,
            "messages": [{"role": "user", "content": user_prompt}],
        }
        headers = {
            "x-api-key":         self.api_key,
            "anthropic-version": "2023-06-01",
            "Content-Type":      "application/json",
        }
        resp = requests.post(url, json=payload, headers=headers, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()
        return data["content"][0]["text"].strip()

    def _call_google(self, system_prompt: str, user_prompt: str) -> str:
        """Call the Google Generative AI REST API (Gemini models)."""
        model_id = self.model or "gemini-1.5-pro"
        url = (
            (self.base_url or "https://generativelanguage.googleapis.com")
            + f"/v1beta/models/{model_id}:generateContent?key={self.api_key}"
        )
        combined = f"{system_prompt}\n\n{user_prompt}"
        payload = {
            "contents": [{"parts": [{"text": combined}]}],
            "generationConfig": {"temperature": 0.1, "maxOutputTokens": 2048},
        }
        resp = requests.post(url, json=payload, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()
        return data["candidates"][0]["content"]["parts"][0]["text"].strip()

    # ── Prompt builders ───────────────────────────────────────────────────────

    def build_layer_a_prompts(
        self, sigma_rule_path: str, backend: str
    ) -> Tuple[str, str]:
        """
        Build system + user prompts for Layer A (Sigma Rule → backend query).

        The model is instructed to produce ONLY the raw query string with no
        markdown fences, using only fields from the backend schema.  Any field
        it cannot map is annotated with an inline comment: # UNMAPPED: <field>.
        """
        schema = _LLM_BACKEND_SCHEMAS.get(backend, {})
        field_hints = json.dumps(schema.get("field_hints", {}), indent=2)
        notes       = "\n".join(f"  - {n}" for n in schema.get("notes", []))
        language    = schema.get("language", backend)

        # Load the raw YAML
        try:
            with open(sigma_rule_path, "r", encoding="utf-8", errors="ignore") as fh:
                rule_yaml = fh.read()
        except Exception as exc:
            logger.warning("Layer A: cannot read sigma rule %s: %s", sigma_rule_path, exc)
            rule_yaml = ""

        system_prompt = (
            f"You are a senior detection engineer specialising in {language}.\n"
            "Your task is to translate a Sigma Rule into a detection query for the target SIEM/EDR.\n\n"
            "STRICT RULES:\n"
            "1. Output ONLY the raw query string — no markdown fences, no explanations.\n"
            "2. Use ONLY field names from the provided field mapping below.\n"
            "3. Preserve the exact boolean logic of the Sigma detection.condition.\n"
            "4. Add a trailing inline comment referencing the Sigma Rule title.\n"
            "5. For any Sigma field you cannot map, add an inline comment: # UNMAPPED: <field>\n"
            "6. Do NOT invent field names that are not in the mapping.\n\n"
            f"TARGET BACKEND: {backend.upper()} ({language})\n\n"
            f"FIELD MAPPING (Sigma concept → {backend} field):\n{field_hints}\n\n"
            f"SYNTAX NOTES:\n{notes}\n"
        )
        user_prompt = (
            f"Translate the following Sigma Rule to a {backend.upper()} detection query.\n\n"
            f"--- SIGMA RULE ---\n{rule_yaml}\n--- END RULE ---\n\n"
            f"Output the {backend.upper()} query only."
        )
        return system_prompt, user_prompt

    def build_layer_b_prompts(
        self, ttp_context: Dict, backend: str
    ) -> Tuple[str, str]:
        """
        Build system + user prompts for Layer B (TTP context → synthesised query).

        The model is instructed to produce 1-3 queries of increasing specificity,
        each tagged with TTP ID and group name, and annotated with FP-risk level.
        """
        schema      = _LLM_BACKEND_SCHEMAS.get(backend, {})
        field_hints = json.dumps(schema.get("field_hints", {}), indent=2)
        notes       = "\n".join(f"  - {n}" for n in schema.get("notes", []))
        language    = schema.get("language", backend)

        ttp_id      = ttp_context.get("technique_id", "")
        ttp_name    = ttp_context.get("technique_name", "")
        tactic      = ttp_context.get("tactic", "")
        platforms   = ", ".join(ttp_context.get("platforms", []))
        data_src    = "\n".join(f"  - {d}" for d in ttp_context.get("data_sources", []))
        tools       = ", ".join(ttp_context.get("tools_associated", []))
        group       = ttp_context.get("group_name", "")
        aliases     = ", ".join(ttp_context.get("group_aliases", []))
        detection   = ttp_context.get("known_behaviors", ttp_context.get("description", ""))[:800]

        system_prompt = (
            f"You are a senior threat hunter with deep expertise in {language} "
            f"and adversary detection engineering.\n\n"
            "STRICT RULES:\n"
            "1. Use ONLY field names from the provided field mapping — never invent names.\n"
            "2. Produce exactly 1 to 3 queries of increasing specificity "
            "(broad → precise).\n"
            "3. Each query MUST include an inline comment: "
            f"# TTP: {ttp_id} | Group: {group}\n"
            "4. After each query, add a single line: # FP-RISK: LOW|MEDIUM|HIGH\n"
            "5. Prefer high-specificity indicators (command-line patterns, registry "
            "keys, hashes) over generic event-type filters.\n"
            "6. Output ONLY the queries and their inline comments — no markdown "
            "fences, no prose.\n\n"
            f"TARGET BACKEND: {backend.upper()} ({language})\n\n"
            f"FIELD MAPPING:\n{field_hints}\n\n"
            f"SYNTAX NOTES:\n{notes}\n"
        )
        user_prompt = (
            f"Generate {backend.upper()} detection queries for the following threat context.\n\n"
            f"TECHNIQUE   : {ttp_id} — {ttp_name}\n"
            f"TACTIC      : {tactic}\n"
            f"PLATFORMS   : {platforms}\n"
            f"GROUP       : {group} (aliases: {aliases})\n"
            f"TOOLS USED  : {tools}\n\n"
            f"DATA SOURCES:\n{data_src}\n\n"
            f"MITRE DETECTION GUIDANCE:\n{detection}\n\n"
            f"Generate the {backend.upper()} queries now."
        )
        return system_prompt, user_prompt


# ── Helper: extract TTP context from FindAPTAttck result ──────────────────────

def _extrair_contexto_ttp(grupo_dados: Dict, tecnica: Dict) -> Dict:
    """
    Build a structured context block for a single TTP from the FindAPTAttck
    result dict.  Used by Layer B prompt construction.

    Parameters
    ----------
    grupo_dados : one element of res_attck['grupos']
    tecnica     : one element of dados['tecnicas']

    Returns
    -------
    dict with keys: technique_id, technique_name, tactic, description,
    platforms, data_sources, tools_associated, group_name, group_aliases,
    known_behaviors
    """
    nome_grupo   = grupo_dados.get("grupo", grupo_dados.get("nome", ""))
    aliases_raw  = grupo_dados.get("aliases", [])
    aliases      = [a for a in (aliases_raw or []) if a and a != nome_grupo]

    dados        = grupo_dados.get("dados", grupo_dados)
    ferramentas  = dados.get("ferramentas", grupo_dados.get("ferramentas", []))
    tool_names   = [f.get("nome", "") for f in ferramentas if isinstance(f, dict)]

    return {
        "technique_id":     tecnica.get("id", ""),
        "technique_name":   tecnica.get("nome", tecnica.get("name", "")),
        "tactic":           (tecnica.get("fases") or [""])[0],
        "description":      tecnica.get("descricao", tecnica.get("description", ""))[:500],
        "known_behaviors":  tecnica.get("deteccao", tecnica.get("description", ""))[:600],
        "platforms":        tecnica.get("plataformas", tecnica.get("platforms", [])),
        "data_sources":     tecnica.get("fontes_dados", tecnica.get("data_sources", [])),
        "tools_associated": [t for t in tool_names if t],
        "group_name":       nome_grupo,
        "group_aliases":    aliases,
    }


# ── Helper: persist queries to JSON + TXT ─────────────────────────────────────

def _salvar_queries_llm(
    resultado: List[Dict],
    grupo_nome: str,
    backend: str,
) -> Tuple[str, str]:
    """
    Persist LLM-generated queries to two formats:

    1. Structured JSON  → findings/llm_queries/<group>_<backend>_<ts>.json
       Schema per entry: ttp_id, ttp_name, tactic, source, sigma_rule,
       backend, query, fp_risk, generated_at, model, unmapped_fields.

    2. Plain text TXT   → findings/llm_queries/<group>_<backend>_<ts>.txt
       Same format as chimera_queries_*.txt but with source annotation.

    Returns (json_path, txt_path).
    """
    dir_llm = DIR_FINDINGS / "llm_queries"
    dir_llm.mkdir(parents=True, exist_ok=True)

    ts   = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    slug = grupo_nome.replace(" ", "_")[:30]

    json_path = str(dir_llm / f"{slug}_{backend}_{ts}.json")
    txt_path  = str(dir_llm / f"{slug}_{backend}_{ts}.txt")

    try:
        with open(json_path, "w", encoding="utf-8") as fj:
            json.dump(resultado, fj, ensure_ascii=False, indent=2)
        logger.info("LLM queries JSON saved: %s", json_path)
    except Exception as exc:
        logger.warning("Could not save LLM JSON: %s", exc)

    try:
        with open(txt_path, "w", encoding="utf-8") as ft:
            for entry in resultado:
                src  = entry.get("source", "unknown")
                sig  = entry.get("sigma_rule") or ""
                ttp  = entry.get("ttp_id", "")
                risk = entry.get("fp_risk", "")
                q    = entry.get("query", "").strip()
                ft.write(f"# === {ttp} | source={src} | fp_risk={risk} ===\n")
                if sig:
                    ft.write(f"# sigma_rule: {sig}\n")
                ft.write(f"{q}\n\n")
        logger.info("LLM queries TXT saved: %s", txt_path)
    except Exception as exc:
        logger.warning("Could not save LLM TXT: %s", exc)

    return json_path, txt_path


# ── Helper: extract FP-risk label from raw LLM output ────────────────────────

def _extrair_fp_risk(raw_query: str) -> str:
    """Parse the # FP-RISK: <level> annotation from the LLM output."""
    match = re.search(r"#\s*FP[-_]?RISK\s*:\s*(LOW|MEDIUM|HIGH)", raw_query, re.IGNORECASE)
    return match.group(1).upper() if match else "MEDIUM"


def _extrair_unmapped(raw_query: str) -> List[str]:
    """Collect all # UNMAPPED: <field> annotations from the LLM output."""
    return re.findall(r"#\s*UNMAPPED\s*:\s*(\S+)", raw_query, re.IGNORECASE)


