# ── Main function — QueryGenLLM ───────────────────────────────────────────────

def executar_query_gen_llm(
    res_attck: Optional[Dict] = None,
    res_sig: Optional[Dict] = None,
    args_batch: Optional[Dict] = None,
) -> Optional[Dict]:
    """
    Execute the QueryGenLLM module.

    Decision flow per TTP
    ---------------------
    For each TTP in res_attck:
      a) If res_sig has a *successful* native conversion → skip (native is better).
      b) If res_sig has the rule but conversion failed → apply Layer A (LLM retry).
      c) If no Sigma Rule found for this TTP → apply Layer B (TTP synthesis).

    Parameters
    ----------
    res_attck  : return value of executar_find_apt_attck()  (or None)
    res_sig    : return value of executar_find_sig_rules()  (or None)
    args_batch : dict with optional keys: backend, llm_backend

    Returns
    -------
    dict with keys: queries, json_path, txt_path, html_path, backend, stats
    """
    print(Fore.CYAN + """
+--------------------------------------------+
|         QueryGenLLM v1.0                   |
|   LLM-Assisted Detection Query Generator  |
+--------------------------------------------+""" + Style.RESET_ALL)

    # ── Guard: module disabled or missing API key ─────────────────────────────
    if not LLM_QUERY_GEN_ENABLED:
        print(
            Fore.YELLOW
            + "  [!] LLM Query Generator is disabled "
            + "(set LLM_QUERY_GEN_ENABLED=true to enable)."
            + Style.RESET_ALL
        )
        return None

    if not LLM_API_KEY and LLM_PROVIDER not in ("ollama",):
        print(
            Fore.RED
            + "  [!] LLM_API_KEY is not set. "
            + "Configure it in .env or as an environment variable."
            + Style.RESET_ALL
        )
        return None

    # ── Determine target backend ──────────────────────────────────────────────
    backend = ""
    if args_batch:
        backend = args_batch.get("llm_backend") or args_batch.get("backend") or ""
    if not backend:
        backends_disponiveis = sorted(_LLM_BACKEND_SCHEMAS.keys())
        print(Fore.CYAN + "\nSupported backends:" + Style.RESET_ALL)
        for i, b in enumerate(backends_disponiveis, 1):
            print(f"  {i}. {b}")
        try:
            escolha = int(
                input(Fore.LIGHTGREEN_EX + "\nChoose backend by number: " + Style.RESET_ALL)
            ) - 1
            backend = backends_disponiveis[escolha]
        except (ValueError, IndexError):
            print(Fore.RED + "Invalid choice." + Style.RESET_ALL)
            return None

    if backend not in _LLM_BACKEND_SCHEMAS:
        print(
            Fore.RED
            + f"  [!] Backend '{backend}' has no schema defined. "
            + f"Available: {list(_LLM_BACKEND_SCHEMAS.keys())}"
            + Style.RESET_ALL
        )
        return None

    print(Fore.GREEN + f"  [*] Target backend: {backend.upper()}" + Style.RESET_ALL)
    print(Fore.GREEN + f"  [*] LLM provider  : {LLM_PROVIDER} / {LLM_MODEL}" + Style.RESET_ALL)

    # ── Build lookup: sigma rule file → converted query (native sigma-cli) ────
    queries_nativas: Dict[str, str] = {}
    regras_sigma_disponiveis: List[str] = []
    if res_sig:
        queries_nativas           = res_sig.get("queries", {}) or {}
        regras_sigma_disponiveis  = res_sig.get("arquivos_regras", []) or []

    # ── Build lookup: TTP id → list of sigma rule files ───────────────────────
    # A Sigma rule tags field lists ATT&CK technique IDs like "attack.t1059.001"
    ttp_para_regras: Dict[str, List[str]] = defaultdict(list)
    for arq in regras_sigma_disponiveis:
        meta = _extrair_metadados_sigma(arq)
        for tag in meta.get("tags", []):
            # tag format: "attack.t1059" or "attack.t1059.001"
            m = re.match(r"attack\.(t\d{4}(?:\.\d{3})?)", tag.lower())
            if m:
                ttp_para_regras[m.group(1).upper()].append(arq)

    # ── Collect groups and techniques to process ──────────────────────────────
    grupos_attck: List[Dict] = []
    if res_attck:
        grupos_attck = res_attck.get("grupos", []) or []

    if not grupos_attck:
        print(
            Fore.YELLOW
            + "  [!] No ATT&CK groups available. Run FindAPTAttck first."
            + Style.RESET_ALL
        )
        return None

    # ── Instantiate generator ─────────────────────────────────────────────────
    gen = QueryGeneratorLLM()

    resultado_final: List[Dict] = []
    stats = {"total": 0, "from_sigma": 0, "synthesized": 0, "skipped": 0}

    group_name = grupos_attck[0].get("grupo", grupos_attck[0].get("nome", "session"))

    for grupo_info in grupos_attck:
        dados  = grupo_info.get("dados", grupo_info)
        tecnicas_grupo = dados.get("tecnicas", grupo_info.get("tecnicas", []))

        for tecnica in tecnicas_grupo:
            ttp_id = tecnica.get("id", "")
            if not ttp_id:
                continue

            contexto   = _extrair_contexto_ttp(grupo_info, tecnica)
            ttp_prefix = ttp_id.split(".")[0]            # e.g. "T1059"

            # Check if any Sigma rules exist for this TTP
            regras_ttp = (
                ttp_para_regras.get(ttp_id, [])
                or ttp_para_regras.get(ttp_prefix, [])
            )

            if regras_ttp:
                # At least one Sigma Rule found for this TTP
                regra = regras_ttp[0]
                stem  = Path(regra).stem

                if stem in queries_nativas and queries_nativas[stem].strip():
                    # Native sigma-cli conversion succeeded — skip LLM
                    logger.debug(
                        "TTP %s: native sigma-cli query exists — skipping LLM.", ttp_id
                    )
                    stats["skipped"] += 1
                    continue

                # Native conversion failed or not attempted — Layer A
                print(
                    Fore.CYAN
                    + f"  [A] {ttp_id} — translating Sigma rule via LLM: {Path(regra).name}"
                    + Style.RESET_ALL
                )
                sys_p, usr_p = gen.build_layer_a_prompts(regra, backend)
                raw = gen._call_llm(sys_p, usr_p)

                if not raw:
                    logger.warning("Layer A: LLM returned empty response for %s.", ttp_id)
                    stats["synthesized"] += 1   # fall through to Layer B
                    regras_ttp = []              # trigger Layer B below
                else:
                    entry = {
                        "ttp_id":          ttp_id,
                        "ttp_name":        contexto.get("technique_name", ""),
                        "tactic":          contexto.get("tactic", ""),
                        "source":          "sigma_rule",
                        "sigma_rule":      regra,
                        "backend":         backend,
                        "query":           raw,
                        "fp_risk":         _extrair_fp_risk(raw),
                        "generated_at":    datetime.datetime.now().isoformat(),
                        "model":           LLM_MODEL,
                        "unmapped_fields": _extrair_unmapped(raw),
                    }
                    resultado_final.append(entry)
                    stats["from_sigma"] += 1
                    stats["total"] += 1
                    continue

            if not regras_ttp:
                # No Sigma rule — Layer B (TTP synthesis)
                print(
                    Fore.LIGHTMAGENTA_EX
                    + f"  [B] {ttp_id} — synthesising query from TTP context"
                    + Style.RESET_ALL
                )
                sys_p, usr_p = gen.build_layer_b_prompts(contexto, backend)
                raw = gen._call_llm(sys_p, usr_p)

                if not raw:
                    logger.warning("Layer B: LLM returned empty response for %s.", ttp_id)
                    continue

                entry = {
                    "ttp_id":          ttp_id,
                    "ttp_name":        contexto.get("technique_name", ""),
                    "tactic":          contexto.get("tactic", ""),
                    "source":          "llm_synthesized",
                    "sigma_rule":      None,
                    "backend":         backend,
                    "query":           raw,
                    "fp_risk":         _extrair_fp_risk(raw),
                    "generated_at":    datetime.datetime.now().isoformat(),
                    "model":           LLM_MODEL,
                    "unmapped_fields": _extrair_unmapped(raw),
                }
                resultado_final.append(entry)
                stats["synthesized"] += 1
                stats["total"] += 1

    if not resultado_final:
        print(Fore.YELLOW + "  [!] No queries generated." + Style.RESET_ALL)
        return None

    # ── Persist results ───────────────────────────────────────────────────────
    json_path, txt_path = _salvar_queries_llm(resultado_final, group_name, backend)
    html_path           = _gerar_html_qgen(resultado_final, backend, stats)

    # ── Console summary ───────────────────────────────────────────────────────
    print(Fore.CYAN + f"\n  LLM Query Generation summary ({backend.upper()}):" + Style.RESET_ALL)
    print(Fore.GREEN  + f"    Total queries generated : {stats['total']}" + Style.RESET_ALL)
    print(Fore.GREEN  + f"    From Sigma (Layer A)    : {stats['from_sigma']}" + Style.RESET_ALL)
    print(Fore.YELLOW + f"    Synthesised (Layer B)   : {stats['synthesized']}" + Style.RESET_ALL)
    print(Fore.CYAN   + f"    Native OK (skipped)     : {stats['skipped']}" + Style.RESET_ALL)
    print(Fore.GREEN  + f"  -> JSON: {json_path}" + Style.RESET_ALL)
    print(Fore.GREEN  + f"  -> TXT : {txt_path}" + Style.RESET_ALL)
    print(Fore.GREEN  + f"  -> HTML: {html_path}" + Style.RESET_ALL)

    registrar_historico("QueryGenLLM", {
        "backend":     backend,
        "provider":    LLM_PROVIDER,
        "model":       LLM_MODEL,
        "total":       stats["total"],
        "from_sigma":  stats["from_sigma"],
        "synthesized": stats["synthesized"],
    })

    return {
        "queries":   resultado_final,
        "json_path": json_path,
        "txt_path":  txt_path,
        "html_path": html_path,
        "backend":   backend,
        "stats":     stats,
    }


# ═══════════════════════════════════════════════════════════════════════════════
# MODULE 5 — STIX 2.1 Export
# ═══════════════════════════════════════════════════════════════════════════════

def exportar_stix21(resultado_grupos: Optional[Dict] = None,
                    resultado_attck: Optional[Dict] = None,
                    nome_ator: str = "unknown_group") -> Optional[str]:
    """
    Export collected data in STIX 2.1 JSON format.
    Includes threat-actor, attack-pattern, malware, tool objects and relationships.
    """
    if not STIX2_AVAILABLE:
        print(Fore.RED + "ERROR: stix2 library not installed. Run: pip install stix2" + Style.RESET_ALL)
        return None

    print(Fore.CYAN + "\n[*] Generating STIX 2.1 export..." + Style.RESET_ALL)

    objetos_stix = []

    # Tool identity
    identidade = Identity(
        name="Chimera Threat Intelligence Platform",
        identity_class="system",
        description=f"Exported by Chimera v{VERSION}",
    )
    objetos_stix.append(identidade)

    # Process groups found by FindAPTGroups
    if resultado_grupos and resultado_grupos.get("resultados"):
        for r in resultado_grupos["resultados"]:
            ator_nome = r.get("actor", "Unknown")
            aliases = [n.get("name", "") for n in r.get("names", []) if isinstance(n, dict)]

            threat_actor_obj = ThreatActor(
                name=ator_nome,
                description=r.get("description", "")[:2000],
                aliases=aliases or None,
                created_by_ref=identidade.id,
            )
            objetos_stix.append(threat_actor_obj)

            # Tools
            for ferr_nome in (r.get("tools", []) or [])[:10]:
                if isinstance(ferr_nome, str):
                    malware_obj = Malware(
                        name=ferr_nome,
                        is_family=False,
                        created_by_ref=identidade.id,
                    )
                    objetos_stix.append(malware_obj)
                    rel = Relationship(
                        relationship_type="uses",
                        source_ref=threat_actor_obj.id,
                        target_ref=malware_obj.id,
                        created_by_ref=identidade.id,
                    )
                    objetos_stix.append(rel)

    # Process techniques from FindAPTAttck
    if resultado_attck and resultado_attck.get("grupos"):
        for info_grupo in resultado_attck["grupos"]:
            dados = info_grupo.get("dados", {})
            for tecnica in dados.get("tecnicas", []):
                t_id = tecnica.get("id", "")
                url_tec = f"https://attack.mitre.org/techniques/{t_id.replace('.', '/')}/"
                ap = AttackPattern(
                    name=tecnica.get("nome", t_id),
                    description=tecnica.get("descricao", ""),
                    external_references=[{
                        "source_name": "mitre-attack",
                        "external_id": t_id,
                        "url": url_tec,
                    }],
                    created_by_ref=identidade.id,
                )
                objetos_stix.append(ap)

    # Build Bundle
    bundle = Bundle(objects=objetos_stix)
    ts_arq = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    caminho_saida = DIR_FINDINGS / f"chimera_stix21_{nome_ator}_{ts_arq}.json"

    with open(caminho_saida, "w", encoding="utf-8") as f:
        f.write(bundle.serialize(pretty=True))

    print(Fore.GREEN + f"  -> STIX 2.1 exported to: {caminho_saida}" + Style.RESET_ALL)
    return str(caminho_saida)


# ═══════════════════════════════════════════════════════════════════════════════
# Execution History — Menu
# ═══════════════════════════════════════════════════════════════════════════════

def menu_historico() -> Optional[Dict]:
    """Display history and allow reusing a previous search."""
    historico = listar_historico()
    if not historico:
        print(Fore.YELLOW + "No previous searches found." + Style.RESET_ALL)
        return None

    print(Fore.LIGHTCYAN_EX + "\n== Search History ==" + Style.RESET_ALL)
    for entrada in historico[-20:]:  # Show last 20
        print(f"  [{entrada['id']}] {entrada['data'][:16]}  {entrada['modo']}  {entrada['parametros']}")

    try:
        escolha = int(input(Fore.LIGHTGREEN_EX + "\nSearch number to reuse (0 = cancel): " + Style.RESET_ALL))
        if escolha == 0:
            return None
        entrada_sel = next((e for e in historico if e["id"] == escolha), None)
        if entrada_sel:
            print(Fore.GREEN + f"  -> Loading search: {entrada_sel}" + Style.RESET_ALL)
            return entrada_sel
    except ValueError:
        pass

    print(Fore.RED + "Invalid selection." + Style.RESET_ALL)
    return None


# ═══════════════════════════════════════════════════════════════════════════════
# MODULE 5 — Consolidated Final Report (with navigable tabs)
# ═══════════════════════════════════════════════════════════════════════════════

def gerar_relatorio_final(
    res_groups: Optional[Dict] = None,
    res_attck: Optional[Dict] = None,
    res_sig: Optional[Dict] = None,
    res_qgen: Optional[Dict] = None,
) -> Optional[str]:
    """
    Generate a consolidated HTML report with navigable tabs, one per module
    effectively executed in the session.

    Each tab embeds the corresponding sub-report HTML via <iframe srcdoc>,
    ensuring that the styles and scripts of each module are fully isolated
    and rendered faithfully, without CSS conflicts.

    Parameters:
        res_groups : return value of executar_find_apt_groups()  (or None)
        res_attck  : return value of executar_find_apt_attck()   (or None)
        res_sig    : return value of executar_find_sig_rules()   (or None)
        res_qgen   : return value of executar_query_gen_llm()    (or None)

    Returns the absolute path of the file generated at
    findings/REPORT_FINAL/final_report_<actor>_<timestamp>.html,
    or None if no module was executed.
    """
    # Check that at least one module was executed
    if not any([res_groups, res_attck, res_sig, res_qgen]):
        logger.debug("gerar_relatorio_final: no module executed, skipping generation.")
        return None

    ts = datetime.datetime.now()
    ts_arquivo = ts.strftime("%Y%m%d_%H%M%S")
    ts_exib    = ts.strftime("%Y-%m-%d %H:%M:%S")

    # ─── Dedicated output directory ──────────────────────────────────────────
    dir_final = DIR_FINDINGS / "REPORT_FINAL"
    dir_final.mkdir(parents=True, exist_ok=True)

    # ─── Actor/group name for the file name ───────────────────────────────────
    nome_ator = "session"
    if res_groups and res_groups.get("nomes_atores"):
        nome_ator = res_groups["nomes_atores"][0].replace(" ", "_")[:30]
    elif res_attck and res_attck.get("grupos"):
        nome_ator = (res_attck["grupos"][0].get("grupo") or "session").replace(" ", "_")[:30]

    nome_arquivo = f"final_report_{nome_ator}_{ts_arquivo}.html"
    caminho = dir_final / nome_arquivo

    # ─── Read a single HTML file from disk and return its content ────────────
    def _ler_html(caminho_html: Optional[str]) -> str:
        """Read individual HTML from disk. Returns empty string if unavailable."""
        if not caminho_html:
            return ""
        try:
            with open(caminho_html, "r", encoding="utf-8") as fh:
                return fh.read()
        except Exception as exc:
            logger.warning("Could not read sub-report %s: %s", caminho_html, exc)
        return ""

    # ─── Escape HTML for use in srcdoc ───────────────────────────────────────
    def _srcdoc_escape(conteudo: str) -> str:
        """Escape double quotes and & in HTML content for use in srcdoc attribute."""
        return conteudo.replace("&", "&amp;").replace('"', "&quot;")

    # ─── Collect tabs ─────────────────────────────────────────────────────────
    # Each tab: id (unique), rotulo (button text), icone (HTML entity), conteudo_html
    abas: List[Dict] = []

    if res_groups:
        html_g = _ler_html(res_groups.get("html_path"))
        abas.append({
            "id":            "aba-groups",
            "rotulo":        "FindAPTGroups",
            "icone":         "&#128269;",
            "conteudo_html": html_g,
        })

    if res_attck:
        for i, caminho_html_a in enumerate(res_attck.get("html_paths", [])):
            grupo_nome = ""
            if i < len(res_attck.get("grupos", [])):
                grupo_nome = (res_attck["grupos"][i].get("grupo") or "")[:20]
            html_a = _ler_html(caminho_html_a)
            rotulo_attck = f"ATT&CK: {grupo_nome}" if grupo_nome else "ATT&CK"
            abas.append({
                "id":            f"aba-attck-{i}",
                "rotulo":        rotulo_attck,
                "icone":         "&#9876;",
                "conteudo_html": html_a,
            })

    if res_sig:
        html_s = _ler_html(res_sig.get("html_path"))
        abas.append({
            "id":            "aba-sigrules",
            "rotulo":        "Sigma Rules",
            "icone":         "&#128737;",
            "conteudo_html": html_s,
        })

    if res_qgen:
        html_q = _ler_html(res_qgen.get("html_path"))
        backend_qgen = (res_qgen.get("backend") or "").upper()
        rotulo_qgen = f"LLM Queries ({backend_qgen})" if backend_qgen else "LLM Queries"
        abas.append({
            "id":            "aba-llmqueries",
            "rotulo":        rotulo_qgen,
            "icone":         "&#129302;",
            "conteudo_html": html_q,
        })

    if not abas:
        logger.warning("gerar_relatorio_final: no tab with available content.")
        return None

    # ─── Build tab buttons ────────────────────────────────────────────────────
    botoes_abas = ""
    for idx, aba in enumerate(abas):
        ativo = ' active' if idx == 0 else ''
        botoes_abas += (
            f'<button class="tab-btn{ativo}" '
            f'onclick="mudarAba(event, \'{aba["id"]}\')">'
            f'{aba["icone"]} {aba["rotulo"]}'
            f'</button>\n'
        )

    # ─── Build tab panels (each with an isolated srcdoc iframe) ──────────────
    paineis_abas = ""
    for idx, aba in enumerate(abas):
        display = 'block' if idx == 0 else 'none'
        conteudo_escapado = _srcdoc_escape(aba["conteudo_html"]) if aba["conteudo_html"] else ""
        iframe_ou_aviso = (
            f'<iframe class="tab-frame" srcdoc="{conteudo_escapado}" '
            f'sandbox="allow-scripts allow-same-origin"></iframe>'
            if conteudo_escapado
            else '<p class="sem-conteudo">&#9888; Sub-report not available for this tab.</p>'
        )
        paineis_abas += f"""
<div id="{aba['id']}" class="tab-painel" style="display:{display};">
{iframe_ou_aviso}
</div>
"""

    # ─── Complete self-contained HTML template ────────────────────────────────
    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Chimera — Final Report | {nome_ator} | {ts_exib}</title>
<style>
/* ══ Reset and variables ════════════════════════════════════════════════════ */
:root {{
    --bg:       #0d1117;
    --surface:  #161b22;
    --surface2: #1f2937;
    --border:   #30363d;
    --text:     #e6edf3;
    --muted:    #8b949e;
    --accent:   #00e5cc;
    --accent2:  #39d353;
    --warn:     #f0a800;
    --danger:   #f85149;
    --radius:   6px;
}}
*, *::before, *::after {{ box-sizing: border-box; margin: 0; padding: 0; }}
body {{
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    font-size: 14px;
    line-height: 1.6;
    min-height: 100vh;
}}
a {{ color: var(--accent); text-decoration: none; }}
a:hover {{ text-decoration: underline; }}

/* ══ Main wrapper ═══════════════════════════════════════════════════════════ */
.pagina {{
    max-width: 1200px;
    margin: 0 auto;
    padding: 24px 20px;
    display: flex;
    flex-direction: column;
    gap: 20px;
}}

/* ══ Header ═════════════════════════════════════════════════════════════════ */
.cabecalho {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 24px 28px;
    display: flex;
    align-items: center;
    gap: 18px;
}}
.cabecalho img {{
    height: 56px;
    object-fit: contain;
    flex-shrink: 0;
}}
.cab-texto h1 {{
    font-size: 1.5em;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.4px;
}}
.cab-texto .meta {{
    color: var(--muted);
    font-size: 0.8em;
    margin-top: 5px;
}}
.cab-texto .meta strong {{ color: var(--text); }}

/* ══ Tab bar ════════════════════════════════════════════════════════════════ */
.tab-barra {{
    display: flex;
    gap: 4px;
    border-bottom: 2px solid var(--border);
    padding-bottom: 0;
    flex-wrap: wrap;
}}
.tab-btn {{
    background: var(--surface2);
    color: var(--muted);
    border: 1px solid var(--border);
    border-bottom: none;
    border-radius: var(--radius) var(--radius) 0 0;
    padding: 10px 20px;
    font-size: 0.92em;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
    white-space: nowrap;
    position: relative;
    bottom: -2px;
}}
.tab-btn:hover {{
    background: var(--surface);
    color: var(--text);
}}
.tab-btn.active {{
    background: var(--surface);
    color: var(--accent);
    border-color: var(--border);
    border-bottom: 2px solid var(--bg);
    font-weight: 700;
}}

/* ══ Content panels ═════════════════════════════════════════════════════════ */
.tab-painel {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-top: none;
    border-radius: 0 0 var(--radius) var(--radius);
    min-height: 600px;
}}
.tab-frame {{
    width: 100%;
    height: 80vh;
    min-height: 600px;
    border: none;
    display: block;
    border-radius: 0 0 var(--radius) var(--radius);
    background: var(--bg);
}}
.sem-conteudo {{
    padding: 40px;
    text-align: center;
    color: var(--muted);
    font-size: 1em;
}}

/* ══ Footer ═════════════════════════════════════════════════════════════════ */
.rodape {{
    text-align: center;
    color: var(--muted);
    font-size: 0.78em;
    border-top: 1px solid var(--border);
    padding-top: 14px;
}}
</style>
</head>
<body>
<div class="pagina">

    <!-- Header -->
    <div class="cabecalho">
        <img src="{_CHIMERA_LOGO_B64}" alt="Chimera Logo">
        <div class="cab-texto">
            <h1>Chimera &#8212; Consolidated Final Report</h1>
            <div class="meta">
                Actor/Group: <strong>{nome_ator}</strong> &nbsp;&#124;&nbsp;
                Generated: <strong>{ts_exib}</strong> &nbsp;&#124;&nbsp;
                Version: <strong>{VERSION}</strong> &nbsp;&#124;&nbsp;
                Tabs: <strong>{len(abas)}</strong>
            </div>
        </div>
    </div>

    <!-- Navigation tabs -->
    <div>
        <div class="tab-barra">
{botoes_abas}        </div>

        <!-- Content panels -->
{paineis_abas}
    </div>

    <!-- Footer -->
    <div class="rodape">
        Report generated by <strong>Chimera v{VERSION}</strong>
        &#8212; Threat Intelligence &amp; Hunting Platform
    </div>

</div>

<script>
/**
 * Switch the active tab.
 * @param {{Event}} evt   - click event on the button
 * @param {{string}} abaId - id of the panel to display
 */
function mudarAba(evt, abaId) {{
    // Hide all panels
    document.querySelectorAll('.tab-painel').forEach(function(p) {{
        p.style.display = 'none';
    }});
    // Remove active class from all buttons
    document.querySelectorAll('.tab-btn').forEach(function(b) {{
        b.classList.remove('active');
    }});
    // Display the selected panel and mark the button as active
    var painel = document.getElementById(abaId);
    if (painel) {{ painel.style.display = 'block'; }}
    evt.currentTarget.classList.add('active');

    // Adjust iframe height to content after loading
    var frame = painel && painel.querySelector('.tab-frame');
    if (frame) {{
        frame.onload = function() {{
            try {{
                var h = frame.contentWindow.document.body.scrollHeight;
                if (h > 200) {{ frame.style.height = h + 'px'; }}
            }} catch(e) {{}}
        }};
    }}
}}

// Adjust height of iframes already loaded on the initial tab
window.addEventListener('load', function() {{
    var ativo = document.querySelector('.tab-painel[style*="block"]');
    if (!ativo) {{ return; }}
    var frame = ativo.querySelector('.tab-frame');
    if (!frame) {{ return; }}
    frame.addEventListener('load', function() {{
        try {{
            var h = frame.contentWindow.document.body.scrollHeight;
            if (h > 200) {{ frame.style.height = h + 'px'; }}
        }} catch(e) {{}}
    }});
}});
</script>
</body>
</html>"""

    with open(caminho, "w", encoding="utf-8") as f:
        f.write(html)
    logger.info("Consolidated report saved: %s", caminho)
    print(
        Fore.LIGHTGREEN_EX
        + f"\n  [*] Consolidated report saved at: {caminho}"
        + Style.RESET_ALL
    )
    # Open the finished consolidated report in the user's default browser
    _abrir_no_browser(str(caminho))
    return str(caminho)


# ═══════════════════════════════════════════════════════════════════════════════
# Main entry point — argparse + interactive menu
# ═══════════════════════════════════════════════════════════════════════════════

def _configurar_argparse() -> argparse.ArgumentParser:
    """Configure and return the CLI argument parser."""
    parser = argparse.ArgumentParser(
        prog="chimera",
        description="Chimera — Threat Intelligence & Hunting Platform v" + VERSION,
        epilog="""Examples:
  python chimera.py
  python chimera.py --mode full --actor "APT28" --backend splunk --output ./reports/
  python chimera.py --mode groups --sector financial --country Brazil
  python chimera.py --mode attack --actor "Lazarus Group" --domain e
  python chimera.py --mode sigrules --technique T1059 --backend elastic --level high
""",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "--mode", choices=["groups", "attack", "sigrules", "full"],
        help="Batch execution mode",
    )
    parser.add_argument("--actor",     help="Threat Actor name")
    parser.add_argument("--sector",    help="Sector filter for groups")
    parser.add_argument("--country",   help="Target country filter for groups")
    parser.add_argument("--tool",      help="Tool/malware filter for groups")
    parser.add_argument("--technique", help="MITRE ATT&CK technique (e.g. T1059)")
    parser.add_argument("--backend",   help="Backend for Sigma conversion (e.g. splunk, elastic)")
    parser.add_argument("--level",     help="Minimum severity level for Sigma rules",
                        choices=["informational", "low", "medium", "high", "critical"])
    parser.add_argument("--domain",    choices=["e", "m", "i"], default="e",
                        help="ATT&CK domain: e=Enterprise, m=Mobile, i=ICS")
    parser.add_argument("--output",    help="Output directory for reports")
    parser.add_argument("--operator",  choices=["AND", "OR"], default="AND",
                        help="Logical operator for combined search")
    parser.add_argument("--stix",         action="store_true",
                        help="Export result in STIX 2.1 format")
    parser.add_argument("--llm-backend",  dest="llm_backend",
                        choices=list(_LLM_BACKEND_SCHEMAS.keys()),
                        help="Backend for LLM query generation (e.g. splunk, qradar, sentinel)")
    parser.add_argument("--llm-queries",  action="store_true", dest="llm_queries",
                        help="Run QueryGenLLM after FindAPTAttck (requires LLM_QUERY_GEN_ENABLED=true)")
    parser.add_argument("--test-render",  action="store_true", dest="test_render",
                        help="Run test_render_llm_json() to validate LLM field rendering and exit")
    parser.add_argument("--debug",        action="store_true", help="Enable debug mode")
    return parser


def main() -> None:
    """Main entry point for Chimera."""
    parser = _configurar_argparse()
    args = parser.parse_args()

    # Adjust log level
    if args.debug if hasattr(args, "debug") else False:
        logging.getLogger().setLevel(logging.DEBUG)
        logger.setLevel(logging.DEBUG)

    # ─── Render validation test ───────────────────────────────────────────────
    if getattr(args, "test_render", False):
        test_render_llm_json()
        return

    # Adjust output directory
    global DIR_FINDINGS
    if hasattr(args, "output") and args.output:
        DIR_FINDINGS = Path(args.output)
        DIR_FINDINGS.mkdir(parents=True, exist_ok=True)

    # ─── Automatic Sigma rules update ────────────────────────────────────────
    atualizar_regras_sigma()

    # ─── Automatic sigma-cli update ──────────────────────────────────────────
    atualizar_sigma_cli()

    # ─── Batch mode (CLI arguments) ──────────────────────────────────────────
    if args.mode:
        args_batch_groups = {
            "actor": args.actor,
            "sector": args.sector,
            "country": args.country,
            "tool": args.tool,
            "operator": args.operator,
        }
        args_batch_attck = {
            "actor": args.actor,
            "domain": args.domain,
        }
        args_batch_sig = {
            "technique": args.technique,
            "backend": args.backend,
            "level": args.level,
        }
        args_batch_llm = {
            "llm_backend": getattr(args, "llm_backend", None) or args.backend,
        }

        res_groups = None
        res_attck  = None
        res_sig    = None
        res_qgen   = None

        if args.mode in ("groups", "full"):
            res_groups = executar_find_apt_groups(args_batch_groups)

        if args.mode in ("attack", "full"):
            ids = res_groups["ids_grupos"] if res_groups else None
            res_attck = executar_find_apt_attck(
                ids_grupos=ids,
                args_batch=args_batch_attck,
            )

        if args.mode in ("sigrules", "full"):
            arqs = res_attck["arquivos_tecnicas"] if res_attck else None
            res_sig = executar_find_sig_rules(
                arquivos_tecnicas=arqs,
                args_batch=args_batch_sig,
            )

        # Run LLM query generation when --llm-queries flag is set or mode=full
        # with LLM_QUERY_GEN_ENABLED=true and an ATT&CK result available.
        if (getattr(args, "llm_queries", False) or args.mode == "full") and res_attck:
            if LLM_QUERY_GEN_ENABLED:
                res_qgen = executar_query_gen_llm(
                    res_attck=res_attck,
                    res_sig=res_sig,
                    args_batch=args_batch_llm,
                )

        if args.stix and STIX2_AVAILABLE:
            nome = args.actor or "export"
            exportar_stix21(res_groups, res_attck, nome)

        # Generate consolidated report at the end of batch mode
        gerar_relatorio_final(res_groups, res_attck, res_sig, res_qgen)

        return

    # ─── Interactive mode ─────────────────────────────────────────────────────
    imprimir_banner_principal()

    res_groups = None
    res_attck  = None
    res_sig    = None
    res_qgen   = None   # captures QueryGenLLM result for the session

    while True:
        opcao = exibir_menu_principal()

        if opcao == "1":
            # Run FindAPTGroups; result is always stored in res_groups
            # for chaining with subsequent modules in the same session.
            res_groups = executar_find_apt_groups()

            # Ask about FindAPTAttck whenever the module returned data —
            # regardless of whether groups have MITRE IDs mapped, because
            # FindAPTAttck also accepts a name-based search as fallback.
            if res_groups:
                continuar = input(
                    Fore.LIGHTCYAN_EX + "\nContinue to FindAPTAttck? (Y/N): " + Style.RESET_ALL
                ).strip().upper()

                # Accepts "Y"; any other input returns to the main menu.
                if continuar == "Y":
                    # Chain directly: pass MITRE IDs when available,
                    # otherwise FindAPTAttck enters its own interactive mode.
                    res_attck = executar_find_apt_attck(
                        ids_grupos=res_groups.get("ids_grupos") or None,
                        caminho_ids=res_groups.get("caminho_ids"),
                    )

                    # Ask about FindSigRules only if FindAPTAttck produced
                    # technique files that can be used as input.
                    if res_attck and res_attck.get("arquivos_tecnicas"):
                        continuar2 = input(
                            Fore.LIGHTCYAN_EX + "\nContinue to FindSigRules? (Y/N): " + Style.RESET_ALL
                        ).strip().upper()
                        if continuar2 == "Y":
                            res_sig = executar_find_sig_rules(
                                arquivos_tecnicas=res_attck["arquivos_tecnicas"]
                            )

                    # Ask about LLM query generation whenever ATT&CK result is available.
                    # The module guards itself against missing API key / disabled flag.
                    if res_attck and LLM_QUERY_GEN_ENABLED:
                        continuar_llm = input(
                            Fore.LIGHTCYAN_EX
                            + "\nGenerate LLM-assisted detection queries? (Y/N): "
                            + Style.RESET_ALL
                        ).strip().upper()
                        if continuar_llm == "Y":
                            res_qgen = executar_query_gen_llm(
                                res_attck=res_attck,
                                res_sig=res_sig,
                            )

        elif opcao == "2":
            # FindAPTAttck standalone
            res_attck = executar_find_apt_attck()
            if res_attck and res_attck.get("arquivos_tecnicas"):
                continuar = input(
                    Fore.LIGHTCYAN_EX + "\nContinue to FindSigRules? (Y/N): " + Style.RESET_ALL
                ).strip().upper()
                if continuar == "Y":
                    res_sig = executar_find_sig_rules(
                        arquivos_tecnicas=res_attck["arquivos_tecnicas"]
                    )
            if res_attck and LLM_QUERY_GEN_ENABLED:
                continuar_llm = input(
                    Fore.LIGHTCYAN_EX
                    + "\nGenerate LLM-assisted detection queries? (Y/N): "
                    + Style.RESET_ALL
                ).strip().upper()
                if continuar_llm == "Y":
                    res_qgen = executar_query_gen_llm(
                        res_attck=res_attck,
                        res_sig=res_sig,
                    )

        elif opcao == "3":
            # FindSigRules standalone
            res_sig = executar_find_sig_rules()

        elif opcao == "4":
            # QueryGenLLM standalone
            if not LLM_QUERY_GEN_ENABLED:
                print(
                    Fore.YELLOW
                    + "  LLM Query Generator is disabled. "
                    + "Set LLM_QUERY_GEN_ENABLED=true in .env to enable."
                    + Style.RESET_ALL
                )
            else:
                res_qgen = executar_query_gen_llm(
                    res_attck=res_attck,
                    res_sig=res_sig,
                )

        elif opcao == "5":
            # History
            entrada = menu_historico()
            if entrada:
                modo = entrada.get("modo", "")
                params = entrada.get("parametros", {})
                print(Fore.CYAN + f"  Mode: {modo} | Parameters: {params}" + Style.RESET_ALL)
                reexec = input("Re-run this search? (Y/N): ").strip().upper()
                if reexec == "Y":
                    if "FindAPTGroups" in modo:
                        executar_find_apt_groups({"actor": params.get("filtros", {}).get("actor")})
                    elif "FindAPTAttck" in modo:
                        executar_find_apt_attck(
                            args_batch={"actor": params.get("grupos", [""])[0] if params.get("grupos") else ""}
                        )
                    elif "FindSigRules" in modo:
                        executar_find_sig_rules(
                            args_batch={"technique": params.get("tecnicas", [""])[0] if params.get("tecnicas") else ""}
                        )

        elif opcao == "6":
            # Export STIX 2.1
            if not STIX2_AVAILABLE:
                print(Fore.RED + "stix2 library not installed." + Style.RESET_ALL)
            else:
                nome_exp = input("Actor name for export: ").strip() or "export"
                exportar_stix21(res_groups, res_attck, nome_exp)

        elif opcao == "0":
            # Generate consolidated report with everything executed in the session
            gerar_relatorio_final(res_groups, res_attck, res_sig, res_qgen)
            print(Fore.LIGHTCYAN_EX + "\n  Chimera shutting down. Goodbye!" + Style.RESET_ALL)
            break

        else:
            print(Fore.RED + "Invalid option. Please try again." + Style.RESET_ALL)


if __name__ == "__main__":
    main()

